INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('incentivo fiscal', '2025-07-12 17:36:14', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1280', '[ Medida Provisória nº 1280/2024 ]', 'urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1280', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Congresso Nacional', '2024-01-01', NULL, 'Prorroga o prazo para utilização do Regime Especial de Tributação para Desenvolvimento da Atividade de Exibição Cinematográfica - Recine, constante da Lei nº 13.594, de 5 de janeiro de 2018, e os benefíciosfiscaisprevistos no art. 44 da Medida Provisória nº 2.228-1, de 6 de setembro de 2001, e nos art. 1º e art. 1º-A da Lei nº 8.685, de 20 de julho de 1993.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;rio.grande.sul;arroio.grande:municipal:decreto:2013-12-06;406', 'Decreto (municipal) nº 406, de 06 de dezembro de 2013', 'urn:lex:br;rio.grande.sul;arroio.grande:municipal:decreto:2013-12-06;406', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2013-12-06', NULL, 'Determina Proibição de Trânsito de veículos conjugados - Caminhão Bitrem eRodotrem-, no perímetro urbano do Município de Arroio Grande/RS e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;airr:2013-09-04;1634-2011-142-3-0', 'Acórdão do processo Nº AIRR - 1634-04.2011.5.03.0142', 'urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;airr:2013-09-04;1634-2011-142-3-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2013-09-04', NULL, 'AGRAVO DE INSTRUMENTO. ADICIONALRODOTREM. REFLEXOS DOS PRÊMIOS. Confirmada a ordem de obstaculização do recurso de revista, na medida em que não demonstrada a satisfação dos requisitos de admissibilidade, insculpidos no artigo 896 da CLT. Agravo de instrumento não provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2023-07-05;0010215-21.2023.5.03.0131', 'Acórdão PJe TRT 3ª / Setima Turma / 2023-07-05', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2023-07-05;0010215-21.2023.5.03.0131', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2023-07-05', NULL, 'EXCEÇÃO DE INCOMPETÊNCIA EM RAZÃO DO LUGAR. MOTORISTARODOTREM. ARTIGO 651 DA CLT. A regra geral, no Processo do Trabalho, é que a competência territorial fixa-se em função do local da prestação de serviços, sendo exceção a faculdade de o trabalhador ajuizar a ação no local da celebração do contrato ou da prestação dos serviços ou até mesmo no seu domicílio (art. 651 da CLT). Todavia, de acordo com o §1º do artigo 651 da CLT, no caso de "agente ou viajante comercial, a competência será da Vara da localidade em que a empresa tenha agência ou filial e a esta o empregado esteja subordinado e, na falta, será competente a Vara da localização em que o empregado tenha domicílio ou a localidade mais próxima". Assim, ainda que, em razão da sua função de motoristarodotrem, o reclamante percorresse diversas cidades - inclusive Contagem-MG -, a competência para julgamento é de uma das Varas de Chapecó/SC, em virtude da localização da sede da empresa-ré.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2016-08-31;293-2015-111-18-0', 'Acórdão do processo Nº AIRR - 293-77.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2016-08-31;293-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2016-08-31', NULL, 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA INTERPOSTO SOB A ÉGIDE DA LEI Nº 13.015/2014 -  RITO SUMARÍSSIMO -   DIFERENÇAS SALARIAIS/ PRÊMIO MOTORISTARODOTREM-  INTEGRAÇÃO -  INTERVALO INTRAJORNADA - REFLEXOS Trata-se de recurso interposto em causa sujeita ao procedimento sumaríssimo, sem o atendimento das exigências do art. 896, § 9º, da CLT. Agravo de Instrumento a que se nega provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2013-04-02;0000356-43.2012.5.03.0041', 'Acórdão TRT 3ª / Quinta Turma / 2013-04-02', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2013-04-02;0000356-43.2012.5.03.0041', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2013-04-02', 'MOTORISTA - SALÁRIO', 'EMENTA: MOTORISTA DE TRANSBORDO. PISO SALARIAL. MOTORISTA DE CARRETA. Tendo o reclamante exercido a função de motorista de transbordo durante todo o período contratual, enquadrado na categoria determinada na respectiva convenção coletiva como sendo "veículo com peso bruto acima de 9.000 Kg", não faz ele jus ao recebimento do piso salarial de motorista de carreta bitrem, tritem,rodotremou treminhão.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2025-02-26;0010465-42.2024.5.03.0156', 'Acórdão PJe TRT 3ª / Primeira Turma / 2025-02-26', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2025-02-26;0010465-42.2024.5.03.0156', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2025-02-26', 'MOTORISTA - DANO MORAL / DANO MATERIAL', 'JORNADA EXAUSTIVA DE MOTORISTA DERODOTREM, SEM INTERVALOS ADEQUADOS INTRA E INTERJORNADAS - INDENIZAÇÃO POR DANO MORAL/EXISTENCIAL. O dano existencial decorre de toda e qualquer lesão apta a comprometer, nos mais variados sentidos, a liberdade de escolha da pessoa humana, inibindo a sua convivência familiar/social e frustrando ou prejudicando o seu projeto de vida. Caracteriza-se pela supressão de tempo para que o trabalhador se realize, como pessoa humana, pessoalmente, familiarmente e socialmente. Quando é ceifado o direito do empregado ao envolvimento em atividades de sua vida privada, por causa de trabalho excessivo, deixando as relações familiares, o convívio social, a prática de esportes, o lazer, os estudos, há violação ao princípio da dignidade da pessoa humana, insculpido no art. 1º, III, da Constituição Federal. Além disto, indubitável o comprometimento da saúde psicofísica do trabalhador. Configurada a prestação laboral exaustiva, ante a realização de horas extras em excesso e a frequente sonegação dos intervalos intrajornada e interjornadas, aflora a  indenização por dano existencial, mormente se se considerar que o reclamante era motorista deRodotrem, caminhão muito logo, composto de nove eixos,  utilizado para o  transporte de cargas. À latere, pode-se, ainda, afirmar que jornadas excessivas), sem o devido respeito aos intervalos legais, colocam, não apenas os motoristas em condições de risco, mas também toda a sociedade, podendo até, metaforicamente, dizer que, pelo menos em potencia, o trabalho de motoristas em longas jornadas, representa  uma espécie de dano difuso, porque viola o direito de todo e qualquer cidadão à segurança nas estradas/vias públicas.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2018-08-15;10529-2015-111-18-0', 'Acórdão do processo Nº AIRR - 10529-88.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2018-08-15;10529-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2018-08-15', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. DIFERENÇAS SALARIAIS. Com esteio na prova oral emprestada, concluiu o Colegiado "que o reclamante comprovou ser motorista derodotreme ter ajustado com sua empregadora salário de R$ 2.100,00, não havendo falar em reforma da sentença". Assim, para se chegar à conclusão, em sentido diametralmente oposto, necessário seria o reexame do contexto fático-probatório, procedimento que encontra óbice na Súmula nº 126 desta Corte. PRÊMIO PERFORMANCE. INTEGRAÇÃO. É inespecífica a ementa apresentada, porque se refere a prêmio que não teve previsão contratual, o que não foi o caso dos autos, além do que, o acórdão regional se refere à integração mensal, circunstância não especificada no paradigma apresentado. Súmula 296 do TST.  INTERVALO INTRAJORNADA. PRÊMIO PARA MOTORISTAS DERODOTREM. RECURSO DE REVISTA QUE NÃO APRESENTA A TRANSCRIÇÃO DO TRECHO DO ACÓRDÃO REGIONAL QUE IDENTIFICA O PREQUESTIONAMENTO DA MATÉRIA OBJETO DO APELO. AUSÊNCIA DE DEMONSTRAÇÃO ANALÍTICA DA DIVERGÊNCIA JURISPRUDENCIAL INDICADA. LEI 13.015/2014. Com o advento da Lei 13.015/2014 o novel § lº-A do artigo 896 da CLT exige em seu inciso I, como ônus da parte e sob pena de não conhecimento, a indicação do trecho da decisão recorrida que consubstancia o prequestionamento da controvérsia objeto do recurso de revista. Por outro lado, o novel § 8º incumbe ao recorrente, dentre outros encargos na hipótese de o recurso pautar-se em dissenso de julgados, o de mencionar as circunstâncias que identifiquem ou assemelhem os casos confrontados. No caso concreto, o acórdão regional foi publicado em 16/11/2016, na vigência da referida lei, e o recurso de revista não apresenta a transcrição do trecho da decisão regional que consubstancia o prequestionamento da controvérsia objeto do apelo, nem realiza a demonstração analítica do dissenso de julgados. As alterações legislativas no aspecto constituem pressuposto de adequação formal de admissibilidade do recurso de revista. A ausência desses requisitos formais torna inexequível o apelo e insuscetível de provimento o agravo de instrumento. A transcrição integral do acórdão regional igualmente não atende ao comando legal. Agravo de instrumento conhecido e desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2011-03-22;0001123-60.2010.5.03.0103', 'Acórdão TRT 3ª / Segunda Turma / 2011-03-22', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2011-03-22;0001123-60.2010.5.03.0103', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2011-03-22', NULL, 'EMENTA: DIFERENÇAS SALARIAIS. PESO DO CAMINHÃO. O piso salarial não pode variar de acordo com a carga transportada pelo motorista e sim em razão do peso do caminhão. Tal conduta é confirmada no parágrafo primeiro da cláusula III do ACT, que define o piso salarial, ao dispor que o empregado que exercer a função de motorista de veículo denominado Bitrem, Tritem,Rodotremou Treminhão receberá adicional de 10% do piso salarial estipulado para motorista de carreta, nele incluído o repouso semanal.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;

-- Batch 8: Records 701-800
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2012-05-02;0000211-18.2011.5.03.0042', 'Acórdão TRT 3ª / Oitava Turma / 2012-05-02', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2012-05-02;0000211-18.2011.5.03.0042', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2012-05-02', 'MOTORISTA - NORMA COLETIVA', 'EMENTA: MOTORISTA - VEÍCULO DE TRANSBORDO - BENEFÍCIOS CONVENCIONAIS. Se, dos autos, se infere que o laborista somente se ativava na condução de veículos de transbordo, que se limitam a trafegar em lavouras, não há como enquadrá-lo na norma convencional que confere benefícios apenas aos motoristas de veículos articulados que transitam também em vias urbanas, a exemplo do bitrem, tritrem,rodotrem, treminhão e semi-reboque do tipo cegonha.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.1:acordao:2014-03-25;0001143-30.2012.5.08.0010', 'ACÓRDÃO TRT 8ª / 1ª T / RO    0001143-30.2012.5.08.0010', 'urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.1:acordao:2014-03-25;0001143-30.2012.5.08.0010', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 8', 'Tribunal Regional Trabalho', 'Acordao', '2014-03-25', NULL, 'DIFERENÇA SALARIAL. ÔNUS DA PROVA.
Admitido pela defesa que o
reclamante foi contratado como
motorista de carreta, mas dirigia
regularmente o veículorodotrem,
que possui faixa salarial
superior, a teor do art. 818 da
CLT c/c o art. 333, inc. II, do
CPC, reverte-se à empregadora o
ônus de comprovar que este fato
ocorreu por período inferior ao
alegado pelo empregado e que este
recebeu a remuneração respectiva,
por constituir-se fato extintivo
do direito postulado.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.6:acordao:2015-08-04;0000995-44.2012.5.03.0079', 'Acórdão TRT 3ª / Sexta Turma / 2015-08-04', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.6:acordao:2015-08-04;0000995-44.2012.5.03.0079', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2015-08-04', 'MOTORISTA - TRABALHO EXTERNO - JORNADA DE TRABALHO - CONTROLE', 'EMENTA: MOTORISTA. EXISTÊNCIA DE CONTROLE E FISCALIZAÇÃO DE JORNADA - Devem ser deferidas as horas extras cumpridas pelo reclamante, motorista derodotremque, embora empreendesse viagens de certa duração e sozinho, dirigia veículo rastreado por mecanismo que o mantinha em contato em tempo real e integral com a reclamada, a qual poderia interferir até mesmo no seu funcionamento em caso de desvio das rotas por ela pré-estabelecidas. Soma-se a isto o fato de que a empresa mantinha contato habitual com o motorista mediante ligações telefônicas, o que por óbvio lhe possibilitava ter ciência da duração das rotas cumpridas nas viagens, controlando, efetivamente, e fiscalizando a jornada de trabalho do autor, hipótese que não se enquadra na exceção do art. 62, I, da CLT.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2017-03-22;989-2015-111-18-0', 'Acórdão do processo Nº AIRR - 989-16.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2017-03-22;989-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2017-03-22', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. PROCESSO SOB A ÉGIDE DA LEI 13.015/2014. 1. PRÊMIO PERFORMANCE. NATUREZA JURÍDICA. APELO FUNDAMENTADO APENAS EM DIVERGÊNCIA JURISPRUDENCIAL. ARESTO INSERVÍVEL. SÚMULA 337/TST. 2. INTERVALO INTRAJORNADA. NÃO CONCESSÃO. SÚMULA 437, I E III/TST. 3. RETIFICAÇÃO DA CTPS. FUNÇÃO EFETIVAMENTE DESEMPENHADA PELO RECLAMANTE.  4. PRÊMIO DE 20% PARA MOTORISTA DERODOTREMPREVISTO EM CONVENÇÃO COLETIVA. APLICAÇÃO DA NORMA COLETIVA MAIS BENÉFICA. ART. 620 DA CLT. MATÉRIAS FÁTICAS. SÚMULA 126/TST. A jurisprudência desta Corte Superior firmou-se no sentido de que a não concessão do intervalo intrajornada, ainda que parcial, confere ao empregado o direito à remuneração correspondente ao período de repouso e alimentação assegurado em sua integralidade, acrescido do adicional de, no mínimo, 50% sobre o valor da remuneração da hora normal de trabalho. Nesse sentido é o item I da Súmula 437/TST. Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2016-06-01;208-2015-111-18-0', 'Acórdão do processo Nº AIRR - 208-91.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2016-06-01;208-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2016-06-01', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. PROCESSO SOB A ÉGIDE DA LEI 13.015/2014. 1. SUSPEIÇÃO DE TESTEMUNHA. AÇÃO CONTRA A MESMA RECLAMADA. SÚMULA 357/TST. AUSÊNCIA DE IMPUGNAÇÃO NO MOMENTO PROCESUAL OPORTUNO. PRECLUSÃO. 2. REMUNERAÇÃO. VALOR REAL. MATÉRIA FÁTICA. ÓBICE DA SÚMULA 126/TST. 3. PRÊMIO PERFORMANCE. NATUREZA JURÍDICA. APELO LASTREADO APENAS EM DIVERGÊNCIA JURISPRUDENCIAL. ARESTO INESPECÍFICO. SÚMULA 296/TST. 4. INTERVALO INTRAJORNADA. SÚMULAS 437, I E III, E 126/TST. 5. PRÊMIORODOTREM. 6. RETIFICAÇÃO DA CTPS. MATÉRIAS FÁTICAS. ÓBICE DA SÚMULA 126/TST. Recurso de natureza extraordinária, como o recurso de revista, não se presta a reexaminar o conjunto fático-probatório produzido nos autos, porquanto, nesse aspecto, os Tribunais Regionais do Trabalho revelam-se soberanos. Inadmissível, assim, recurso de revista em que, para se chegar a conclusão diversa, seria imprescindível o revolvimento de fatos e provas, nos termos da Súmula 126 desta Corte. Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;ag:2023-06-07;1077-2017-8-23-0', 'Acórdão do processo Nº Ag-AIRR - 1077-63.2017.5.23.0008', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;ag:2023-06-07;1077-2017-8-23-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ag', '2023-06-07', NULL, 'AGRAVO INTERNO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA - GRATIFICAÇÃORODOTREM- NATUREZA SALARIAL - FATOS OCORRIDOS ANTES DA LEI 13.467/2017 - INOBSERVÂNCIA DO ART. 896, § 1º-A, I A III, DA CLT. 1. Em relação ao julgamento ser extra petita, o Tribunal Regional foi claro ao dispor que "Em sede de réplica o Autor impugnou a alegação de que a CCT veda a incorporação do prêmio e requereu a declaração da nulidade da cláusula oposta pela Ré (fl. 590)." Assim, o que o juiz de primeiro grau fez foi cumprir o disposto no art. 350 do CPC. 2. Não houve manifestação no acórdão regional quanto à aplicação do § 2º do art. 457 da CLT. Por outro lado, não foram opostos embargos de declaração para elucidação da matéria. Dessa maneira, não há como analisar as alegações recursais quanto a essa questão, por falta do necessário prequestionamento disposto no art. 896, §1º-A, da CLT e na Súmula 297 do TST. 3. Em relação à natureza salarial da "gratificaçãorodotrem", o Tribunal Regional manteve a sentença de 1º grau complementando que "O § 1º do art. 457 da CLT, com a redação vigente à época dos fatos, previa que o salário era composto não só pela importância fixa estipulada, mas também por comissões, percentagens, gratificações, abonos e diárias para viagem que excedam de 50% do salário percebido". 4. A par disso, a parte agravante, nas razões do seu recurso de revista, não cumpre o disposto nos incisos I a III do §1º-A do art. 896 da CLT quanto à natureza salarial da citada gratificação, pois deixa de realizar o cotejo analítico de teses, não relacionado a exata fundamentação adotada pela Turma julgadora a quo à apresentação dos fundamentos antagônicos contidos na norma apontada como violada. Nesse sentido é que se insere a exigência de transcrição dos trechos do acórdão regional impugnado, devendo a parte relacionar o teor dessa transcrição com os fundamentos do seu recurso de revista, o que não se verificou no caso dos autos. Agravo interno desprovido. MOTORISTA PROFISSIONAL - HORAS EXTRAORDINÁRIAS -  CONTROLE DE JORNADA - INOBSERVÂNCIA DO ART. 896, § 1º-A, II E III, DA CLT. 1. Em que pese a agravante ter transcrito o trecho a respeito da fundamentação do acórdão regional, nas razões do recurso de revista, de acordo com o inciso I do §1º-A do art. 896 da CLT, deixou de indicar, de forma explícita e fundamentada, contrariedade a dispositivo de lei, súmula ou orientação jurisprudencial do Tribunal Superior do Trabalho que conflite com a decisão regional, sendo nesse sentido o disposto no art. 896, § 1º-A, II e III, da CLT. 2. A parte recorrente, além de indicar o trecho da decisão recorrida de forma suficiente e completa, a fim de demonstrar o prequestionamento da controvérsia objeto do recurso de revista, deve indicar contrariedade a dispositivo de lei, súmula ou orientação jurisprudencial do Tribunal Superior do Trabalho que vá de encontro com a decisão regional. 3. Ressalta-se que o cotejo analítico de teses implica identificação exata da fundamentação adotada pela Turma julgadora a quo e apresentação dos fundamentos antagônicos contidos na norma legal ou constitucional, ou no verbete ou orientação jurisprudencial apresentados, ou nos arestos trazidos a cotejo. Nesse sentido é que se insere a exigência de transcrição dos trechos do acórdão regional impugnado, devendo a parte relacionar o teor dessa transcrição com os fundamentos do seu recurso de revista, o que não se verificou no caso dos autos. 4. Desse modo, tendo em vista que o recurso de revista interposto pela reclamada não atende ao disposto nos incisos II e III, do § 1º-A do art. 896 da CLT, no que se refere ao tema em epígrafe, nega-se provimento ao agravo interno. Agravo interno desprovido. JUNTADA DE DOCUMENTO NOVO - ÓBICE DA SÚMULA 296, I, DO TST. O aresto oriundo do Tribunal Regional do Trabalho da 12ª região é inespecífico, em razão de não tratar sobre juntada de documento novo. Incidência do óbice da Súmula nº 296, I, do TST. Agravo interno desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2016-06-29;193-2015-111-18-0', 'Acórdão do processo Nº AIRR - 193-25.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2016-06-29;193-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2016-06-29', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. PROCESSO SOB A ÉGIDE DA LEI 13.015/2014. 1. DIFERENÇAS DE PRÊMIO PERFORMANCE. APELO FUNDAMENTADO APENAS EM DIVERGÊNCIA JURISPRUDENCIAL. ARESTO INSERVÍVEL. SÚMULA 337/TST. 2. INTERVALO INTRAJORNADA. MATÉRIA FÁTICA. SÚMULA 126/TST. CONCESSÃO PARCIAL. PAGAMENTO INTEGRAL. SÚMULA 437, I E III/TST. Após a edição da Lei nº 8.923/94, a não concessão ou a concessão parcial do intervalo intrajornada mínimo, para repouso e alimentação, a empregados urbanos e rurais, implica o pagamento total do período correspondente, e não apenas daquele suprimido, com acréscimo de, no mínimo, 50% sobre o valor da remuneração da hora normal de trabalho (art. 71 da CLT), sem prejuízo do cômputo da efetiva jornada de labor para efeito de remuneração. Incidência da Súmula 437, I/TST. Agravo de instrumento desprovido. ART. 896, § 1º-A, I, DA CLT. EXIGÊNCIA DE TRANSCRIÇÃO DOS FUNDAMENTOS EM QUE SE IDENTIFICA O PREQUESTIONAMENTO DA MATÉRIA OBJETO DE RECURSO DE REVISTA. 3. SALÁRIO PACTUADO. 4. PRÊMIO DE 20% PARA MOTORISTA DERODOTREM. ÓBICE ESTRITAMENTE PROCESSUAL. Nos termos do art. 896, § 1º-A, I, da CLT, incluído pela Lei n. 13.015/14, a transcrição dos fundamentos em que se identifica o prequestionamento da matéria impugnada constitui exigência formal à admissibilidade do recurso de revista. Havendo expressa exigência legal de indicação do trecho do julgado que demonstre o enfrentamento da matéria pelo Tribunal Regional, evidenciando o prequestionamento, a ausência desse pressuposto intrínseco torna insuscetível de veiculação o recurso de revista. Julgados. Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;ag:2023-05-24;542-2020-141-14-0', 'Acórdão do processo Nº Ag-AIRR - 542-70.2020.5.14.0141', 'urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;ag:2023-05-24;542-2020-141-14-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ag', '2023-05-24', NULL, 'AGRAVO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DA LEI Nº 13.467/2017. HORAS EXTRAS. ÔNUS DA PROVA. REEXAME DE FATOS E PROVAS. IMPOSSIBILIDADE. ÓBICE DA SÚMULA 126 DO TST. TRANSCENDÊNCIA NÃO RECONHECIDA. A finalidade precípua desta Corte Superior, na uniformização de teses jurídicas, não autoriza a revisão do conjunto fático-probatório já analisado pelo Tribunal Regional, na esteira do entendimento consolidado pela Súmula 126/TST. Na hipótese, registrou o Regional, conforme se verifica dos trechos transcritos na decisão agravada, "do cotejo das declarações iniciais da jornada do autor com os depoimentos dados pelas testemunhas que também atuavam como motoristas profissionais na ré, pode-se extrair que havia o respeito por parte da empresa quanto às restrições de rodagem do caminhãorodotrem, o qual, pela Resolução nº 211 do CONTRAM, apenas poderia transitar nas estradas do amanhecer ao pôr do sol, ou melhor, das seis da manhã as seis da tarde. Esse cumprimento inibe, a míngua de outras provas, o extrapolamento da jornada alegado pela parte reclamante. Ressalta-se que nada foi requerido na inicial quanto a tempo de espera". Decidir de maneira diversa demandaria o reexame do acervo probatório, vedado nesta instância extraordinária (Súmula 126/TST).. Pontue-se não haver falar em equívoco quanto às regras de distribuição do ônus da prova, quando o julgador, confrontando o acervo instrutório dos autos, não reputa comprovados os fatos constitutivos do direito postulado. Mantém-se a decisão recorrida. Agravo conhecido e desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2011-12-02;0000690-02.2010.5.03.0024', 'Acórdão TRT 3ª / Terceira Turma / 2011-12-02', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2011-12-02;0000690-02.2010.5.03.0024', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2011-12-02', 'MOTORISTA - TRABALHO EXTERNO - JORNADA DE TRABALHO - CONTROLE', 'EMENTA: TRABALHO EXTERNO - MOTORISTA DERODOTREM- CONTROLE DE JORNADA POR SISTEMA MISTO - RESTRIÇÃO DE TRÂNSITO - TEMPO À DISPOSIÇÃO.  Não vem em proveito da recorrente a invocação da O. J. 332 da SDI-1 do TST, pois a r. sentença recorrida não firmou o seu livre entendimento fundamentado sobre um suposto sistema de controle por disco tacógrafo, além de se tratar de entendimento jurisprudencial inespecífico para o sistema de controle da jornada de trabalho externa por sistema de rastreamento por satélite ou por sistemas de rastreamento misto, como o que foi detectado no julgamento do presente caso concreto (rastreamento por satélite+telefone). Em nada beneficia a recorrente a invocação do regulamento de trânsito sobre a circulação de rodotrens e nem o depoimento prestado pelo reclamante, que esclareceu satisfatoriamente que "a restrição é restrita" aos dias e horários que aponta, durante os quais  permaneceu à disposição da recorrente, na forma do que dispõe o artigo 4º da CLT, pois o cumprimento da jornada de trabalho não abrange apenas o período de trabalho efetivamente prestado (dirigindo), mas também o tempo dispendido na espera da liberação da rodovia para o prosseguimento da viagem.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2016-10-19;143-2015-111-18-0', 'Acórdão do processo Nº AIRR - 143-96.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2016-10-19;143-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2016-10-19', NULL, 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. 1. DIFERENÇAS SALARIAIS. ÔNUS DA PROVA. O Regional asseverou que a prova testemunhal produzida nos autos, bem como a prova emprestada, demonstram que, para os motoristas de caminhão derodotrem(nove eixos) empregados da reclamada, o salário-base acertado era de R$2.100,00. Ressaltou, ainda, não haver prova em sentido contrário. Concluiu a Corte de origem, nesse sentido, ter o reclamante se desincumbido do ônus da prova quanto ao salário efetivamente recebido, superior àquele registrado na CTPS, razão pela qual manteve a condenação da reclamada ao pagamento de diferenças salariais. Diante do contexto delineado, verifica-se que as regras atinentes à distribuição do ônus probatório foram devidamente observadas pelo Regional, restando incólumes os artigos 818 da CLT e 373 do CPC/2015 (atual artigo 333 do CPC/73). 2. PRÊMIO PERFORMANCE. INTEGRAÇÃO AO SALÁRIO. A 1ª reclamada fundamenta sua pretensão recursal unicamente em aresto formalmente inválido, pois a fonte de publicação indicada - o sítio eletrônico www.jusbrasil.com.br - não consubstancia repositório autorizado de jurisprudência desta Corte. Óbice da Súmula nº 337, IV, do TST. 3. INTERVALO INTRAJORNADA. CONCESSÃO PARCIAL. EFEITOS. NATUREZA SALARIAL. A decisão regional está em harmonia com a Súmula nº 437, I e III, desta Corte, segundo a qual a supressão do intervalo intrajornada, ainda que parcial, implica o pagamento integral do período, sendo devidos os reflexos, ante a natureza salarial da parcela. 4. PRÊMIO. NORMA COLETIVA. A recorrente ampara sua pretensão recursal unicamente em aresto formalmente inválido para cotejo, pois oriundo de Vara do Trabalho, órgão judicante não elencado no artigo 896, "a", da CLT. Agravo de instrumento conhecido e não provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2016-11-23;181-2015-111-18-0', 'Acórdão do processo Nº AIRR - 181-11.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2016-11-23;181-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2016-11-23', NULL, 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA -  PROCESSO SOB A VIGÊNCIA DA LEI Nº 13.015/2014 E CPC/73 -  SUSPEIÇÃO -  TESEMUNHA -  AUSÊNCIA DE TRANSCRIÇÃO DO ACÓRDÃO REGIONAL -  ART. 896, § 1º-A, DA CLT. O apelo esbarra no art. 896, § 1º-A, da CLT, pois a parte não indica o trecho da decisão recorrida que consubstancia o prequestionamento da matéria. RETIFICAÇÃO CTPS -  DIVERGÊNCIA JURISPRUDENCIAL -  AUSÊNCIA DE INDICAÇÃO DO ÓRGÃO OFICIAL DE PUBLICAÇÃO. O apelo está amparado unicamente em divergência jurisprudencial. Todavia, o único aresto colacionado é imprestável ao fim colimado, pois não indica o órgão oficial de publicação. Incide a Súmula nº 337 do TST. PRÊMIO PERFOMANCE -  DIVERGÊNCIA JURISPRUDENCIAL INESPECÍFICA. Extrai-se da decisão recorrida que o prêmio era pago em razão da assiduidade e da limpeza do caminhão. O apelo está amparado, exclusivamente, em divergência jurisprudencial, mas o único aresto colacionado é inespecífico, pois não aborda as mesmas premissas fáticas do acórdão regional, referindo-se a prêmio progressivo. Incide a Súmula nº 296 do TST. INTERVALO INTRAJORNADA -  PRÉ-ASSINALAÇÃO -  NORMA COLETIVA -  AUSÊNCIA DE PREQUESTIONAMENTO -  NATUREZA JURÍDICA -  SÚMULA Nº 437, III, DO TST. Não há tese na decisão recorrida a respeito da previsão em norma coletiva da pré-assinalação do intervalo intrajornada. Incide a Súmula n º 297 do TST. Quanto à natureza jurídica, não comporta mais discussão nesta Corte, ante os termos da Súmula nº 437, III, do TST. Intacto o art. 71, § 4º, da CLT. PRÊMIO MOTORISTARODOTREM-  DIVERGÊNCIA JURISPRUDENCIAL -  ARESTO ORIUNDO DE ÓRGÃO NÃO ELENCADO NO ART. 896 DA CLT. O único aresto colacionado é oriundo de Turma do TST, órgão não elencado no art. 896 da CLT. Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:17', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2017-04-05;10039-2015-111-18-0', 'Acórdão do processo Nº AIRR - 10039-66.2015.5.18.0111', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2017-04-05;10039-2015-111-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2017-04-05', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. PROCESSO SOB A ÉGIDE DA LEI 13.015/2014. 1. DIFERENÇAS SALARIAIS. SALÁRIO PAGO A MENOR. PRINCÍPIO DA PRIMAZIA DA REALIDADE. MATÉRIA FÁTICA. SÚMULA 126/TST. 2. INTERVALO INTRAJORNADA. PRÉ-ASSINALAÇÃO DESCONSTITUÍDA PELO CONJUNTO PROBATÓRIO. NATUREZA JURÍDICA. SÚMULAS 126 E 437, I E III/TST. 3. PRÊMIO PERFORMANCE. INTEGRAÇÃO À REMUNERAÇÃO. REFLEXOS. APELO FUNDAMENTADO APENAS EM DIVERGÊNCIA JURISPRUDENCIAL. ARESTO INESPECÍFICO -  SÚMULAS 23 E 296/TST. ÓBICE PROCESSUAL CONSTATADO. 4. PRÊMIO DE 20% PARA MOTORISTA DERODOTREM. APELO FUNDAMENTADO APENAS EM DIVERGÊNCIA JURISPRUDENCIAL. ARESTOS ORIUNDOS DE ÓRGÃO NÃO ELENCADO NO ART. 896, "A", DA CLT. ÓBICE PROCESSUAL CONSTATADO. 5. COMISSÕES SOBRE O CARREGAMENTO DE SOJA. MATÉRIA FÁTICA. SÚMULA 126/TST. É comando imperativo de lei a concessão de intervalo de uma hora, no mínimo, para os trabalhadores submetidos a jornada superior a 6 horas, e de 15 minutos, quando a jornada for superior a 4h e inferior a 6h (art. 71, §1º, da CLT). Importante frisar, também, que a jurisprudência desta Corte firmou entendimento no sentido de que é do empregado o ônus de comprovar o trabalho durante o intervalo intrajornada, ainda que o empregador não tenha explicitado a assinalação do início e do fim dos aludidos intervalos nos cartões de ponto, uma vez que inexiste previsão legal sob tal perspectiva, bastando, conforme a jurisprudência citada, a mera pré-assinalação (CLT, art. 74 § 2º). Na hipótese, em que pese o TRT tenha registrado a existência de pré-assinalação dos intervalos nos cartões de ponto, concluiu, de forma enfática, que os "testemunhos convergiram no sentido de que não usufruíam do intervalo intrajornada, salvo nos períodos chuvosos, tendo o autor admitido que isso ocorria de uma a duas vezes por semana". Nesse contexto, a pretensão recursal esbarra no óbice da Súmula 126/TST, uma vez que apenas com o revolvimento de fatos e provas seria possível decidir favoravelmente à Reclamada, o que é inadmissível nesta instância de natureza extraordinária. Insta destacar, ainda, que a remuneração do período suprimido do intervalo intrajornada segue o entendimento consubstanciado na Súmula 437, I/TST, de seguinte teor: "Após a edição da Lei nº 8.923/94, a não concessão ou a concessão parcial do intervalo intrajornada mínimo, para repouso e alimentação, a empregados urbanos e rurais, implica o pagamento total do período correspondente, e não apenas daquele suprimido, com acréscimo de, no mínimo, 50% sobre o valor da remuneração da hora normal de trabalho (art. 71 da CLT), sem prejuízo do cômputo da efetiva jornada de labor para efeito de remuneração". Saliente-se, outrossim, no tocante à natureza jurídica da parcela, que o acórdão recorrido está em consonância com a Súmula 437, III/TST, que ora se transcreve: "Possui natureza salarial a parcela prevista no art. 71, § 4º, da CLT, com redação introduzida pela Lei nº 8.923, de 27 de julho de 1994, quando não concedido ou reduzido pelo empregador o intervalo mínimo intrajornada para repouso e alimentação, repercutindo, assim, no cálculo de outras parcelas salariais". Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:18', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2020-11-18;10386-2017-127-15-0', 'Acórdão do processo Nº AIRR - 10386-64.2017.5.15.0127', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2020-11-18;10386-2017-127-15-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2020-11-18', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. PROCESSO SOB A ÉGIDE DA LEI Nº 13.015/2014 E ANTERIOR À LEI Nº 13.467/2017. REPRESENTAÇÃO SINDICAL. ENQUADRAMENTO SINDICAL. MATÉRIA FÁTICA. SÚMULA 126/TST. O artigo 511, § 1º, da CLT, fixa como vínculo social básico da categoria econômica "a solidariedade de interesses econômicos dos que empreendem atividades idênticas, similares ou conexas". Portanto a natureza da atividade é que se apresenta como critério de vinculação da categoria, criando a relação social inerente à associação sindical. Por outro lado, o enquadramento sindical deve, em regra, ser feito de acordo com a atividade preponderante da empresa, a teor dos arts. 570 e 581 da CLT. Na hipótese, o Tribunal Regional, com fundamento nos princípios da atividade preponderante do empregador e da especificidade sindical (CLT, artigos 511, §§ 2º e 3º, e 570, parágrafo único), reconheceu a legitimidade do Sindicato dos Trabalhadores e Empregados Rurais de Teodoro Sampaio como representante dos motoristas, tratoristas e operadores de máquina, contratados pela Requerida Concórdia Logística S.A. - CONLOG, que prestem serviços aos empregadores rurais de sua base territorial. A Corte de origem consignou expressamente que a terceirização dos serviços prestados pelos empregados ex-motoristas da Usina Alcídia pela empresa requerida CONLOG não retira a preponderância das atividades desses obreiros no âmbito rural, mormente pela constatação da existência de "certa incongruência lógica entre a atividade primordial da empresa requerida - exploração do ramo de transporte rodoviário municipal (estatuto social consolidado, artigo 3º, fl. 161) - e o fato de que a lista dos empregados aqui envolvidos só fez referência ao desempenho da atividade de ''motorista derodotrem'', típica do setor sucroalcooleiro". Outrossim, registrou que houve o trânsito em julgado da sentença prolatada na ação nº 0000129-19.2013.5.15.0127, ajuizada pelo Sindicato dos Trabalhadores e Empregados Rurais de Teodoro Sampaio em face do Sindicato dos Condutores de Veículos Rodoviários, Urbanos, Passageiros e Anexos de Santo Anastácio, Teodoro Sampaio, Primavera e Região - SINCOVERO, na qual se declarou a representatividade do Sindicato Autor perante a categoria dos motoristas, tratoristas e operadores de máquinas de empresas agrícolas em sua base territorial, bem como determinou que o Sindicato requerido, SINCOVERO, se abstivesse de promover qualquer representação sobre esses profissionais. Dessa maneira, não há como analisar as alegações recursais em sentido contrário, uma vez que, para tanto, seria necessário o revolvimento do conjunto fático-probatório dos autos, o que é defeso nesta Instância Extraordinária de jurisdição, conforme o disposto na Súmula 126/TST. Julgados desta Corte. Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rodotrem', '2025-07-12 17:36:18', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;arr:2015-04-29;2107-2011-28-3-0', 'Acórdão do processo Nº ARR - 2107-41.2011.5.03.0028', 'urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;arr:2015-04-29;2107-2011-28-3-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Arr', '2015-04-29', NULL, 'I -  AGRAVO DE INSTRUMENTO DA RECLAMADA RIOS UNIDOS LOGÍSTICA E TRANSPORTES DE AÇO LTDA. -  IRREGULARIDADE DE REPRESENTAÇÃO É inviável a regularização da representação processual na fase recursal. Não há como constatar a presença de mandato tácito, uma vez que o advogado subscritor do Recurso não participou das audiências realizadas no processo. O acórdão regional está em consonância com as Súmulas nºs 164 e 383, I e II, do TST. Agravo de Instrumento a que se nega provimento.  II -  RECURSO DE REVISTA DA RECLAMADA USINAS SIDERÚRGICAS DE MINAS GERAIS S.A. - RESPONSABILIDADE SUBSIDIÁRIA - TOMADOR DE SERVIÇOS - SÚMULA Nº 331, ITENS IV E VI, DO TST A responsabilidade subsidiária do tomador de serviços que não seja ente integrante da Administração Pública direta e indireta independe de comprovação de irregularidade na contratação/fiscalização e abrange todas as verbas devidas pelo devedor principal, nos termos dos itens IV e VI da Súmula nº 331 do TST. ADICIONAL DE FUNÇÃO MOTORISTARODOTREME PLR Revela-se impertinente a invocação aos artigos 818 da CLT e 333, I, do CPC, haja vista que a controvérsia não foi solucionada com base nas regras de distribuição do ônus da prova, mas, sim, com fundamento na análise das provas constantes dos autos. MULTA DO ARTIGO 477, § 8º, DA CLT - ATRASO NA HOMOLOGAÇÃO DA RESCISÃO O mero atraso na homologação da rescisão contratual não é fato gerador da sanção prevista no artigo 477, § 8º, da CLT. Precedentes desta Corte. HORAS EXTRAS -  CONTROLE DE JORNADA - TRABALHO EXTERNO -  ART. 62, I, DA CLTO Tribunal Regional concluiu que "tanto a existência de planos de viagens previamente definidos, quanto a previsibilidade da duração das viagens, acompanhadas pela reclamada em tempo real, implicam existência de efetivo controle e fiscalização da jornada" (fls. 531/532). Para divergir desse entendimento, no sentido de que o Reclamante exercia atividade externa incompatível com a fixação de horário de trabalho, seria necessário o reexame fático-probatório dos autos, providência vedada pela Súmula nº 126 do TST.  Desse modo, não havendo comprovação da impossibilidade de controle de horário, não há falar no enquadramento do Reclamante no art. 62, I, da CLT.  Recurso de Revista conhecido parcialmente e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
