INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('9 Máquinas e Equipamentos', '2025-07-12 17:36:27', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:medida.provisoria:1996-09-17;1508-9', 'Medida Provisória nº 1.508-9, de 17 de Setembro de 1996', 'urn:lex:br:federal:medida.provisoria:1996-09-17;1508-9', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '1996-09-17', 'EXCLUSÃO ,  INCIDENCIA ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  CORRELAÇÃO ,  INDUSTRIALIZAÇÃO ,  MISTURA ,  PIGMENTO ,  TINTA ,  DESTINAÇÃO ,  CONSUMIDOR ,  RELAÇÃO ,  COMERCIO VAREJISTA . CONCESSÃO ,  ISENÇÃO FISCAL ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  CORRELAÇÃO ,EQUIPAMENTOS,  FABRICAÇÃO NACIONAL ,  FABRICAÇÃO ESTRANGEIRA . AMPLIAÇÃO ,  PRAZO ,  MICROEMPRESA ,  PEQUENA EMPRESA ,  RECOLHIMENTO ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) . ALTERAÇÃO ,  LIMITE DE ISENÇÃO ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  IMPOSTO DE RENDA ,  MICROEMPRESA ,  PEQUENA EMPRESA .', 'Concede isenção do Imposto sobre Produtos Industrializados - IPI na aquisição deequipamentos,máquinas, aparelhos e instrumentos, dispõe sobre período de apuração e prazo de recolhimento do referido imposto para as microempresas e empresas de pequeno porte, e estabelece suspensão do IPI na saída de bebidas alcóolicas, acondicionadas para venda a granel, dos estabelecimentos produtores e dos estabelecimentos equiparados a industrial.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
