INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('9 Máquinas e Equipamentos', '2025-07-12 17:36:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.9:acordao:2016-03-07;00015922520115010072', 'ACÓRDÃO TRT 1ª  /9ª Turma / 0001592-25.2011.5.01.0072 - DOERJ 07-03-2016', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.9:acordao:2016-03-07;00015922520115010072', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2016-03-07', NULL, 'O enquadramento sindical do empregado, via de regra, é determinado pela atividade econômica preponderante da empresa, e na situação sub examine, a Certidão de Inscrição e de Situação Cadastral (1º documento de fls. 112), revela que a Ré possui como atividade econômica principal -o comércio atacadista demáquinas,equipamentospara terraplanagem, mineração e construção-, e como atividades econômicas secundárias -aluguel de outrasmáquinaseequipamentoscomerciais e industriais não especificados anteriormente, sem operador-, além de -manutenção e reparação deequipamentose produtos não especificados anteriormente-. Por outro lado, a categoria profissional representada pelo Sindicato, ora Recorrente, está voltada, prioritariamente, para os trabalhadores em empresas de locação, que não guarda relação alguma com a atividade preponderante da Acionada.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('9 Máquinas e Equipamentos', '2025-07-12 17:36:27', 'https://www.lexml.gov.br/urn/urn:lex:br;rio.grande.sul;passa.sete:municipal:lei:2008-09-09;815', 'Lei Municipal nº 815, de09de setembro de 2008', 'urn:lex:br;rio.grande.sul;passa.sete:municipal:lei:2008-09-09;815', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2008-09-09', NULL, 'Autoriza o Poder Executivo a contratar financiamento junto ao BANCO DO BRASIL S.A. objetivando a aquisição demáquinaseequipamentosno âmbito do Programa de Intervenções Viárias - PROVIAS e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
