INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2014-11-11;0010077-70.2014.5.03.0163', 'Acórdão PJe TRT 3ª / Segunda Turma / 2014-11-11', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2014-11-11;0010077-70.2014.5.03.0163', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2014-11-11', 'RELAÇÃO DE EMPREGO - TRANSPORTADOR', 'TRANSPORTADORDECARGASEM VEÍCULO PRÓPRIO - LEIS N.º 11.442/2007 E 7.920/84 - VÍNCULO EMPREGATÍCIO - NÃO CARACTERIZAÇÃO. Retratado nos autos que o reclamante desempenhava a atividadedetransportedecargasem veículo próprio e em benefício exclusivo de determinada empresa, sendo remunerado por frete realizado e arcando com os custos e riscos dos serviços por ele prestados, fica caracterizada a sua condição de transportador autônomodecargas(TAC) "agregado", nostermosdo artigo 4º, §1º, da Lei n.º 11.442/2007. Consoante a inteligência das Leis n.º 11.442/2007 e 7.920/84, otransporteautônomodecargasgera vínculo de natureza comercial entre as partes, afastando o vínculo empregatício pretendido pelo reclamante.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2016-09-02;0010432-96.2015.5.03.0017', 'Acórdão PJe TRT 3ª / Setima Turma / 2016-09-02', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2016-09-02;0010432-96.2015.5.03.0017', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2016-09-02', NULL, 'TRANSPORTADORDECARGASEM VEÍCULO PRÓPRIO. LEIS 11.442/2007 E 7.920/84. VÍNCULO EMPREGATÍCIO. NÃO CARACTERIZAÇÃO. Retratado nos autos que o reclamante desempenhava a atividadedetransportedecargasem veículo próprio e em benefício exclusivo de determinada empresa, sendo remunerado por frete realizado e arcando com os custos e riscos dos serviços por ele prestados, fica caracterizada a sua condição de transportador autônomodecargas(TAC) "agregado", nostermosdo artigo 4º, §1º, da Lei n.º 11.442/2007. Consoante a inteligência das Leis n.º 11.442/2007 e 7.920/84, otransporteautônomodecargasgera vínculo de natureza comercial entre as partes, afastando o vínculo empregatício pretendido pelo reclamante.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2006-08-28;01551-2006-148-03-00-6', 'Acórdão TRT 3ª / Primeira Turma / 2006-08-28', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2006-08-28;01551-2006-148-03-00-6', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2006-08-28', NULL, 'EMENTA:1)  CONVENÇÃO COLETIVA - BASE TERRITORIAL - ALCANCE.  As
conquistas   obtidas   pelo  Sindicato   dos   Trabalhadores   emTransportesRodoviários de Pará de Minas junto ao Sindicato  das
EmpresasdeTransportesdeCargado EstadodeMinasGeraisficam
restritas  à  base-territorial  Pará  de Minas,  uma  vez  que  a
categoria  profissional deste município é que logrou êxito  junto
ao  sindicato-patronal,  galgando os benefícios  consignados  nas
CCT.  E  o fato de a empregadora contemplar seus  empregados  com
alguns   benefícios   coincidentes  com  aqueles   versados   nas
indigitadas  CCT tampouco conduz à ilação de que assentira com  a
representatividade  buscada pelo reclamante.  A leitura há de ser
restritiva,  nostermosdo art.  114/CCB;  se inexiste  respaldo
normativo  à concessão das benesses,  impossível estendê-las além
da vontade da recorrente.  2) MULTA DO ART. 477 PARÁGRAFO 8o.  DA
CLT - AÇÃO DE CONSIGNAÇÃO EM PAGAMENTO.  A rigor, a multa do art.
477/CLT é incompatível com a procedência da Consignatória,  ainda
que parcial.  Se o lá consignatário entende pela mora  debitoris,
cabe-lhe  brandir  pela improcedência daquela  ação,  obviamente,
naqueles  autos.  É o que se deduz da leitura do inteiro teor  do
art.  896/CPC.  Ademais,  o  autor confessou,  em seu  depoimento
pessoal,  que não se apresentou na data marcada para o  pagamento
final; logo, a mora só a si pode ser imputada.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;ag:2023-06-07;101847-2019-481-1-0', 'Acórdão do processo Nº Ag-AIRR - 101847-44.2019.5.01.0481', 'urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;ag:2023-06-07;101847-2019-481-1-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ag', '2023-06-07', NULL, 'AGRAVO. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI Nº 13.467/2017. ADICIONAL DE PERICULOSIDADE. AUSÊNCIA DE TRANSCENDÊNCIA. O e. TRT consignou que a prova técnica demonstrou que as atividades realizadas pelo obreiro implicavam o carregamento etransportede materiais inflamáveis durante o período em que foi motorista de caminhão carreta, realizando otransportedecargasperigosas e a entrada em locais de armazenamento de inflamáveis. Pontuou para tanto que "a prova técnica demonstrou que as atividades realizadas pelo obreiro implicavam o carregamento etransportede materiais inflamáveis durante o período que foi motorista de caminhão carreta, realizando otransportedecargasperigosas e a entrada em locais de armazenamento de inflamáveis. E que depois, quando se tornou motorista de prancha baixa, continuou acessando áreas de risco nos portos de Macaé e Açu". Assentou, ainda, que "a Sra. Marissol, engenheira da reclamada, confirmou durante a perícia técnica que o autor trabalhava notransportedecargasemgeralentre as bases e portos operados pela Petrobras, e que a ré não fazia o controle sobre os tiposdecargastransportadas pelos motoristas, e que era frequente otransportedecargascontendo produtos perigosos e inflamáveis". Frisou que o adicional de periculosidade é devido ainda que a exposição ao risco ocorra de forma intermitente, nostermosda Súmula n° 364 do C. TST. As razões veiculadas no recurso de revista, por sua vez, estão calcadas em realidade fática diversa, qual seja, que o autor não trabalhou exposto a situações de risco em suas atividades e ambientes de trabalho. Nesse contexto, uma conclusão diversa desta Corte, contrariando aquela contida no v. acórdão regional, demandaria o reexame do conjunto probatório, atraindo o óbice contido na Súmula nº 126 do TST, segundo a qual é "Incabível o recurso de revista ou de embargos (arts. 896 e 894, '' b'' , da CLT) para reexame de fatos e provas", o que inviabiliza o exame da própria matéria de fundo veiculada no recurso de revista. O aresto transcrito para o confronto de teses revela-se inespecífico, nostermosdas Súmulas nº 23 e 296 do TST. A existência de obstáculo processual apto a inviabilizar o exame da matéria de fundo veiculada, como no caso, acaba por evidenciar, em última análise, a própria ausência de transcendência do recurso de revista, em qualquer das suas modalidades, conforme precedentes invocados na decisão agravada. Agravo não provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.recursal.juiz.fora:acordao:2022-04-01;0010216-08.2021.5.03.0153', 'Acórdão PJe TRT 3ª / Decima Primeira Turma / 2022-04-01', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.recursal.juiz.fora:acordao:2022-04-01;0010216-08.2021.5.03.0153', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2022-04-01', NULL, 'VÍNCULO DE EMPREGO. INEXISTÊNCIA. TRANSPORTADOR AUTÔNOMODECARGAS. APLICAÇÃO DA LEI Nº 11.442/2007. Especificamente em relação ao serviçodetransporterodoviáriodecargas, o STF, no julgamento da ADC 48, decidiu que "uma vez preenchidos os requisitos dispostos na Lei nº 11.442/2007, estará configurada a relação comercial de natureza civil". No caso dos autos, restou comprovada a regularidade da contratação de natureza comercial entre as partes, nostermosda Lei n. 11.442/07, não se configurando a alegada fraude trabalhista, na forma do art. 9º da CLT.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2014-03-26;0000653-29.2013.5.03.0069', 'Acórdão TRT 3ª / Terceira Turma / 2014-03-26', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2014-03-26;0000653-29.2013.5.03.0069', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2014-03-26', NULL, 'EMENTA: ENQUADRAMENTO SINDICAL. Cumpre salientar que, em regra, o enquadramento sindical é estabelecido considerando-se a atividade preponderante da empresa, sendo que, nostermosdo parágrafo 2º do art. 581 da CLT, "entende-se como atividade preponderante a que caracterizar a unidade do produto, operação ou objetivo final, para cuja obtenção todas as demais atividades convirjam, exclusivamente, em regime de conexão funcional". Nesse sentido, também o art. 511, §1º, da CLT, ao estabelecer como vínculo social básico da categoria econômica "a solidariedade de interesses econômicos dos que empreendem atividades idênticas, similares ou conexas". Ou seja, é a natureza da atividade que se apresenta como critério de vinculação da categoria, gerando o liame social inerente à associação sindical. No presente caso, os elementos de prova coligidos aos autos evidenciam que a atividadedetransportedecargasna reclamada caracteriza empreendimento acessório às demais atividades discriminadas no Contrato Social dessa empresa e no respectivo Comprovante de Inscrição e de Situação Cadastral perante a Receita Federal, não se lhe aplicando, por conseguinte, as normas coletivas firmadas entre o Sindicato autor e o Sindicato das EmpresasdeTransportesdeCargado EstadodeMinasGerais.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2015-05-06;150500-2008-53-1-0', 'Acórdão do processo Nº RR - 150500-86.2008.5.01.0053', 'urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2015-05-06;150500-2008-53-1-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2015-05-06', NULL, 'RECURSO DE REVISTA.TERMODE CONCILIAÇÃO FIRMADO PERANTE COMISSÃO DE CONCILIAÇÃO PRÉVIA. EFICÁCIA LIBERATÓRIA. DESVIRTUAMENTO DO INSTITUTO. HOMOLOGAÇÃO DE PAGAMENTO DE VERBAS RESCISÓRIAS.1. A Corte Regional rejeitou a pretensão patronal de reconhecimento de eficácia liberatóriageralaotermode conciliação firmado perante a Comissão de Conciliação Prévia. Consignou que "a eficácia liberatória de que trata o parágrafo único do art. 625-E da CLT somente pode alcançar as parcelas expressamente demandadas e recebidas". Registrou, ainda, "que os documentos existentes nos autos, notadamente o de fls. 124, deixam certo que a recorrente sequer formalizou o TRCT do reclamante, o que somente feito no momento do Acordo homologado perante o NICOP. (fls. 15/16 e 157) o que demonstra que o referido Núcleo foi utilizado como simples órgão homologador de sua rescisão contratual". Assim, considerou que "é de ser mantida a r. sentença recorrida, que, acertadamente, considerou que oTermode Conciliação extrajudicial de fls. 15/16 apenas comprova o valor recebido pelo empregado, enfatizando que o NICOP não pode funcionar como mero órgão homologador de resilição contratual". 2. Este Tribunal Superior tem entendido que a Comissão de Conciliação Prévia não pode ser utilizada como mero órgão homologador da rescisão contratual, sob pena de desvirtuamento da finalidade do instituto, de compor extrajudicialmente os interesses em conflito. Em hipóteses tais, não se reconhece eficácia liberatóriageralaotermode conciliação ali firmado. Precedentes. 3. Estando o acórdão recorrido em conformidade com esse entendimento, emergem a Súmula 333/TST e o art. 896, § 4º, da CLT como óbices ao conhecimento do recurso, não havendo falar em ofensa ao art. 625-E da CLT. 4. Arestos inespecíficos (Súmula 296, I, do TST). Recurso de revista não conhecido, no tema. JUSTA CAUSA. DESCARACTERIZAÇÃO.1. O Colegiado de origem manteve a sentença que reconhecera a dispensa imotivada, assinalando que "não há prova contundente de que o autor realmente tenha deixado de comparecer ao serviço nas ocasiões em que foram registradas as faltas, inclusive nos dias correspondentes às guias de falta". Destacou que "restou comprovado de maneira satisfatória, pelo depoimento de fls. 287 prestado pela testemunha do reclamante, que, quando não havia carro para trabalhar, o empregado era tido como ausente". Acrescentou que "a reclamada sequer apresentou qualquer comunicação de dispensa sob a alegação de justa causa, a qual, de resto, só foi invocada na defesa". 2. Nesse contexto, o debate sobre a configuração, ou não, de falta grave justificadora de dispensa por justa causa tende à reavaliação do conjunto probatório dos autos, o que encontra óbice em recursos de natureza extraordinária, a teor da Súmula 126 desta Corte Superior. Não há, pois, como aferir ofensa ao art. 482, "e", da CLT. 3. Arestos inábeis (Súmula 337, IV, "c", do TST). Recurso de revista não conhecido, no tema. MULTA DO ART. 477, §8º, DA CLT. JUSTA CAUSA REVERTIDA EM JUÍZO.1. Hipótese em que o TRT manteve a aplicação da multa prevista no art. 477, § 8º, da CLT, ao fundamento de que referida penalidade "diz respeito ao atraso no pagamento das verbas decorrentes da cessação contratual, nada tendo a ver com a existência, ou não, de controvérsia acerca dos motivos determinantes da cessação do contrato". Acrescentou que "a reclamada não fez qualquer prova de que o autor tenha se recusado a receber as verbas rescisórias". 2. O atual entendimento desta Corte Superior se consolidou no sentido de que apenas quando o trabalhador, comprovadamente, der causa à mora, não será devida a multa prevista no art. 477, § 8º, da CLT - hipótese não reconhecida nos autos, haja vista o não-pagamento das verbas devidas ao empregado em razão da alegação de demissão por justa causa, posteriormente revertida em juízo. 3. Óbices da Súmula 333/TST e do art. 896, § 4º, da CLT. Recurso de revista não conhecido, no tema. HORAS EXTRAS.1. Hipótese em que mantida a condenação em horas extras, ao registro de que "a prova testemunhal produzida pelo reclamante, como se verifica fls. 286, comprova que ele realizava, em média, três dobras semanais, daí resultando que não eram respeitados os limites de compensação previstos na norma coletiva da categoria (fls. 107), haja vista a extrapolação dacargahorária máxima semanal". 2. A controvérsia não foi solucionada pela aplicação das regras de distribuição do ônus da prova, mas pelo exame e valoração da prova oral efetivamente produzida. Nesse contexto, resulta impertinente a indicação de ofensa aos arts. 818 da CLT, 333, I, do CPC, ou de dissenso com arestos que versam sobre o ônus da prova. 3. À míngua do necessário prequestionamento, inviável aferir ofensa ao art. 5º, LIV, da Lei Maior. 4. Quanto à pretensão de reconhecimento da compensação prevista em norma coletiva, o recurso é manifestamente desfundamentado, à luz do art. 896 da CLT, porquanto não indicada, nesse particular, ofensa a preceito de lei ou da Carta Política, contrariedade a verbete deste Tribunal ou dissenso de teses. Recurso de revista não conhecido, no tema. MOTORISTA.TRANSPORTECOLETIVO. INTERVALO INTRAJORNADA. FRACIONAMENTO. NORMA COLETIVA. PRESTAÇÃO DE HORAS EXTRAS. CANCELAMENTO DO ITEM II DA OJ 342/SDI-I/TST. PERÍODO ANTERIOR AO ADVENTO DA LEI 12.619/2012.1. O Colegiado a quo manteve a condenação relativa ao intervalo intrajornada, ao entendimento de que os intervalos fracionados entre as viagens, previstos em norma coletiva, "não têm a mesma destinação daquele de que ora se trata, já que não são suficientes para permitir que o trabalhador usufrua de descanso e, notadamente, de pausa para alimentação, sendo obrigatório um intervalo de, no mínimo, uma hora ao empregado que labore mais de seis horas". 2. Outrossim, o acórdão recorrido revela a prorrogação habitual da jornada - tanto que mantida a sentença em que deferidas horas extras e reflexos. 3. Assim, não observados os requisitos previstos no antigo item II da OJ nº 342 da SDI-I do TST -  porquanto evidenciada a prestação de horas extras -, aplicável o entendimento explicitado no seu item I, que foi convertido no item II da Súmula 437/TST, no sentido de que "É inválida cláusula de acordo ou convenção coletiva de trabalho contemplando a supressão ou redução do intervalo intrajornada porque este constitui medida de higiene, saúde e segurança do trabalho, garantido por norma de ordem pública (art. 71 da CLT e art. 7º, XXII, da CF/1988), infenso à negociação coletiva". Precedentes. 4. No caso, ao reputar inviável a redução do intervalo intrajornada mediante norma coletiva, a Corte de origem decidiu em conformidade com o referido verbete. 5. Por outro lado, a pretensão empresarial de limitar a condenação ao adicional de 50% vai de encontro à jurisprudência assente nesta Corte, sedimentada no item I Súmula 437/TST ("Após a edição da Lei nº 8.923/94, a não concessão ou a concessão parcial do intervalo intrajornada mínimo, para repouso e alimentação, a empregados urbanos e rurais, implica o pagamento total do período correspondente, e não apenas daquele suprimido, com acréscimo de, no mínimo, 50% sobre o valor da remuneração da hora normal de trabalho (art. 71 da CLT), sem prejuízo do cômputo da efetiva jornada de labor para efeito de remuneração". 6. Óbices do art. 896, § 4º, da CLT e da Súmula 333/TST. Recurso de revista não conhecido, no tema.  DEVOLUÇÃO DE DESCONTOS A TÍTULO DE FALTAS.1. Hipótese em que o TRT manteve a determinação de devolução de descontos a título de faltas, ao fundamento de que "não há prova suficiente de que o autor, efetivamente, tenha faltado nas ocasiões em que sofreu descontos a título de faltas, devendo ser mantida a devolução de tais descontos". 2. No tópico, o recurso é manifestamente desfundamentado, à luz do art. 896 da CLT, porquanto não indicada, nesse particular, ofensa a preceito de lei ou da Carta Política, contrariedade a verbete deste Tribunal ou dissenso de teses. Recurso de revista não conhecido, no tema.  DEVOLUÇÃO DE DESCONTOS A TÍTULO DE UNIFORMES E VALES.1. A Corte regional manteve a determinação de devolução de parte dos descontos salariais relativos a vales e uniformes, ao entendimento de que "a reclamada não comprovou que concedeu outros adiantamentos além daqueles comprovados através dos documentos anexados a fls.125/135". 2. O acórdão recorrido denota terem sido comprovados os descontos salariais alegados pelo reclamante, não tendo sido demonstrado, por outro lado, que todos eles se referissem a adiantamentos referentes a vales e uniformes, conforme alegado pela reclamada. Assim, ao manter a devolução determinada pela sentença, por considerar que a reclamada não se desvencilhou integralmente do ônus de comprovar o fato impeditivo alegado, a Corte de origem, ao revés de violar, deu plena aplicação aos arts. 818 da CLT e 333, I, do CPC. Recurso de revista não conhecido, no tema.  EXPEDIÇÃO DE OFÍCIOS.1. O TRT manteve a sentença, ao entendimento de que "nada há a reformar no julgado, no pertinente, porquanto a expedição de ofícios se insere dentro dos poderes outorgados ao juiz para condução do processo com ampla liberdade, cabendo-lhe avaliar a conveniência de comunicar aos órgãos competentes eventuais irregularidades que venham a ser constatadas para que sejam tomadas as providências cabíveis no âmbito das respectivas atribuições, sendo de acrescentar, ainda, ante o que aduzido pela recorrente, que a Justiça do Trabalho possui competência parta tanto na medida em que tais irregularidades decorrem da relação havida entre empregado e empregador". 2. À míngua do necessário prequestionamento, inviável aferir ofensa ao art. 5º, II, LIV e LV, da Constituição Federal. Óbice da Súmula 297/TST. Recurso de revista não conhecido, no tema.  MULTA DO ART. 475-J DO CPC. INAPLICABILIDADE NO PROCESSO DO TRABALHO.1. Decisão regional em que adotado o entendimento de que aplicável ao processo do trabalho a multa do art. 475-J do CPC. 2. O Tribunal de origem dissentiu da jurisprudência desta Corte Superior, que está sedimentada no sentido de que inaplicável à situação em exame a regra contida no referido preceito, porque não se visualiza omissão na Consolidação das Leis do Trabalho, tampouco compatibilidade da norma processual civil com as normas processuais trabalhistas. Precedentes. Recurso de revista conhecido e provido, no tema. JUSTIÇA GRATUITA. HIPOSSUFICIÊNCIA. COMPROVAÇÃO.1. O Tribunal de origem manteve a concessão dos benefícios da Justiça Gratuita, ao entendimento de que "o deferimento da gratuidade, no caso sub judice, é medida que se impõe, haja vista que, desde o ajuizamento da ação, conforme se verifica a fls. 08, o reclamante declarou não possuir condições financeiras para arcar com a demanda judicial sem prejuízo de seu sustento e de seus familiares, afigurando-se, então, a sua hipossuficiência econômica". 2. A decisão regional guarda harmonia com ostermosda OJ 304/SDI-I do TST, segundo a qual, "atendidos os requisitos da Lei nº 5.584/70 (art. 14, § 2º), para a concessão da assistência judiciária, basta a simples afirmação do declarante ou de seu advogado, na petição inicial, para se considerar configurada a sua situação econômica (art. 4º, §1º, da Lei nº 7.510/86, que deu nova redação à Lei nº 1.060/50)". Incidência do art. 896, § 4º, da CLT e da Súmula 333/TST. Recurso de revista não conhecido, no tema.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('1 Termos Gerais de Transporte de Carga', '2025-07-12 17:36:32', 'https://www.lexml.gov.br/urn/urn:lex:br:terceiro.conselho.contribuintes;camara.1;turma.ordinaria:acordao:2008-07-10;301-34652,4717487', 'Acórdão nº 301-34652 do Processo 13819.003495/2003-15', 'urn:lex:br:terceiro.conselho.contribuintes;camara.1;turma.ordinaria:acordao:2008-07-10;301-34652,4717487', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Terceiro Conselho Contribuintes', 'Acordao', '2008-07-10', NULL, 'Assunto: Sistema Integrado de Pagamento de Impostos e Contribuições das Microempresas e das Empresas de Pequeno Porte - Simples
Ano-calendário: 2003
SIMPLES - EXCLUSÃO - ATIVIDADES RELACIONADAS A PRESTAÇÃO DE SERVIÇOSDETRANSPORTEDECARGASEMGERAL- INEXISTÊNCIA DE VEDAÇÃO
Não existe vedação à opção pelo regime do SIMPLES das Microempresas e Empresas de Pequeno Porte que desenvolvem atividades relacionadas a prestação de serviçosdetransportedecargasemgeral, tanto sob a égide da Lei nº 9.317/96 quanto sob a égide da LC 123/2006.
O §2º do artigo 17 da LC 123/2006, com a redação dada pela LC 127/2007, se aplica de forma retroativa aos processos administrativos fiscais pendentes de julgamento, nostermosdo artigo 106, inciso II, alínea “b” do Código Tributário Nacional. Precedentes.
RECURSO VOLUNTÁRIO PROVIDO', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:34', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2023-09-18;4516', 'PL 4516/2023', 'urn:lex:br:camara.deputados:projeto.lei;pl:2023-09-18;4516', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Camara Deputados', '2023-09-18', NULL, 'Dispõe sobre a promoção da mobilidadesustentávelde baixo carbono, o Programa Nacional deCombustívelSustentávelde Aviação, o Programa Nacional de Diesel Verde e o marco legal da captura e da estocagem geológica de dióxido de carbono.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:34', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:decreto:2010-05-07;7172', 'Decreto nº 7.172, de 7 de Maio de 2010', 'urn:lex:br:federal:decreto:2010-05-07;7172', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '2010-05-07', 'APROVAÇÃO ,  ZONEAMENTO AGROECOLOGICO ,  PRODUÇÃO ,  OLEO VEGETAL ,  DENDE ,  TERRITORIO NACIONAL ,  CORRELAÇÃO ,  DESENVOLVIMENTOSUSTENTAVEL. COMPETENCIA ,  CONSELHO MONETARIO NACIONAL (CMN) ,  DEFINIÇÃO ,  CRITERIOS ,  CONCESSÃO ,  FINANCIAMENTO ,  CREDITO RURAL ,  CREDITO AGRICOLA ,  PRODUÇÃO ,  EXTRAÇÃO ,  OLEO VEGETAL ,  DENDE ,COMBUSTIVELALTERNATIVO .', 'Aprova o zoneamento agroecológico da cultura da palma de óleo e dispõe sobre o estabelecimento pelo Conselho Monetário Nacional de normas referentes às operações de financiamento ao segmento da palma de óleo, nos termos do zoneamento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:35', 'https://www.lexml.gov.br/urn/urn:lex:br:agencia.nacional.energia.eletrica:resolucao.homologatoria:2015-03-26;1865', 'RESOLUÇÃO HOMOLOGATÓRIA nº 1865, de 26/03/2015', 'urn:lex:br:agencia.nacional.energia.eletrica:resolucao.homologatoria:2015-03-26;1865', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Agencia Nacional Energia Eletrica', '2015-03-26', 'Aprovação. Edital. Leilão. {Compra e Venda, Venda, Compra}. Fonte Alternativa de Energia. {EOL, Central Eólica, Central Geradora Eólica, Usina Eolioelétrica, Uee, Usina Eólica, Central Geradora Eólio - Elétrica}. {UTE, Central Térmica, Usina Termelétrica, Central Geradora Termelétrica, Usina Térmica}. {Combustível, Carburante}. Biomassa. {Sistema Interligado Nacional, Sin}. {Ambiente de Contratação Regulada, ACR}. Fixação. {TUST, Tarifa de Uso do Sistema de Transmissão}. {TUSDG, Tarifa de Uso dos Sistemas de Distribuição Aplicável Às Centrais Geradoras}. {(CCEE), Câmara de Comercialização de Energia Elétrica} | {CCEE, Câmara de Comercialização de Energia Elétrica}. Aprovação. Edital. {Leilões, Almoeda}. {Compra e Venda, Compra}. {Energia - Fontes alternativas, Fontes alternativas de energia, Fontes de energiasustentáveis, Recursos energéticos renováveis}. {EOL, Central Eólica, Central Geradora Eólica, Usina Eolioelétrica, Uee, Usina Eólica, Central Geradora Eólio - Elétrica}. {UTE, Central Térmica, Usina Termelétrica, Central Geradora Termelétrica, Usina Térmica}.Combustíveis. Biomassa. {Sistema Interligado Nacional, Sin}. {Ambiente de Contratação Regulada, ACR}. Fixação. {TUST, Tarifa de Uso do Sistema de Transmissão}. {TUSDG, Tarifa de Uso dos Sistemas de Distribuição Aplicável Às Centrais Geradoras}', 'Aprova o Edital do Leilão ANEEL 002 de 2015 e seus Anexos, referente à compra de energia elétrica proveniente de novos empreendimentos de geração, a partir de fontes eólica e termelétrica a biomassa, destinada ao Sistema Interligado Nacional - SIN, no Ambiente de Contratação Regulada - ACR, e estabelece as TUST e as TUSDg.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:35', 'https://www.lexml.gov.br/urn/urn:lex:br:primeiro.conselho.contribuintes;camara.5;turma.ordinaria:acordao:2006-11-08;105-16.112,4660308', 'Acórdão nº 105-16.112 do Processo 10640.002678/2005-68', 'urn:lex:br:primeiro.conselho.contribuintes;camara.5;turma.ordinaria:acordao:2006-11-08;105-16.112,4660308', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Primeiro Conselho Contribuintes', 'Acordao', '2006-11-08', NULL, 'Imposto sobre a Renda de Pessoa Jurídica - IRPJ
Anos-calendário: 2001, 2002, 2003
Ementa: 
NULIDADE. LIVRO DE MOVIMENTAÇÃO DECOMBUSTÍVEIS- Em conformidade com o  artigo 260 do Regulamento do Imposto de Imposto (Decreto nº 3.000, de 1999), a pessoa jurídica, além dos livros de contabilidade previstos em leis e regulamentos, deverá possuir, no caso de posto revendedor, Livro de Movimentação de Combusíveis devidamente escriturado. Identificada divergência entre os valores consignados no referido Livro Fiscal e os submetidos à tributação, há que se promover o competente o lançamento tributário, não sendosustentávela tese de nulidade do feito com base no argumento de que o dever formal foi instituído por norma infralegal.
LUCRO PRESUMIDO. OMISSÃO DE RECEITA - No caso de pessoa jurídica com atividades diversificadas tributadas com base no lucro presumido, não sendo possível a identificação da atividade a que se refere a receita omitida, esta será adicionada àquela que corresponder o percentual mais elevado.
LIVRO DE MOVIMENTAÇÃO DECOMBUSTÍVEIS. DIVERGÊNCIA NOS VALORES SUBMETIDOS À TRIBUTAÇÃO – Se o contribuinte, regularmente intimado, não traz aos autos elementos capazes de explicar a tributação a menor dos valores registrados a título de vendas no Livro de Movimentação deCombustíveis, há que se manter o lançamento tributário.
PAGAMENTOS A BENEFICIÁRIOS NÃO IDENTIFICADOS. PAGAMENTOS SEM CAUSA – Nos casos de pagamentos efetuados pelas pessoas jurídicas a beneficiários não identificados, bem como naqueles efetuados ou entregues a terceiros ou sócios em que não for comprovada a operação ou a sua causa, os valores correspondentes se submetem à incidência do Imposto de Renda exclusivamente na fonte, à alíquota de trinta e cinco por cento.
MULTA QUALIFICADA – Se os fatos apurados pela Autoridade Fiscal permitem caracterizar o intuito deliberado da contribuinte de subtrair valores à tributação, é cabível a aplicação, sobre os valores apurados, da multa de ofício qualificada.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:35', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;rr:2008-10-01;75600-2005-22-4-0', 'Acórdão do processo Nº RR - 75600-52.2005.5.04.0022', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;rr:2008-10-01;75600-2005-22-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2008-10-01', NULL, 'RECURSO DE REVISTA. 1. VÍNCULO EMPREGATÍCIO. IMPOSSIBILIDADE DE REVOLVIMENTO DE FATOS E PROVAS. O recurso de revista se concentra na avaliação do direito posto em discussão. Assim, em tal via, já não são revolvidos fatos e provas, campo em que remanesce soberana a instância regional. Diante de tal peculiaridade, o deslinde do apelo considerará, apenas, a realidade que o acórdão atacado revelar. Esta é a inteligência da Súmula 126 do TST. Recurso de revista não conhecido. 2. COMISSÕES. CÁLCULO DAS PARCELAS DEFERIDAS EM JUÍZO. O art. 478, § 4º, da CLT aplica-se no cálculo da indenização pela rescisão do contrato de trabalho por tempo indeterminado, ao passo que o critério utilizado pelas instâncias ordinárias refere-se às verbas deferidas pelo reconhecimento do vínculo de emprego em juízo. Ileso o referido dispositivo legal. Recurso de revista não conhecido. 3. ESTORNO DE COMISSÕES. A jurisprudência desta Corte Superior orienta no sentido de que o direito à comissão surge após ultimada a transação pelo empregado, sendo indevido o cancelamento do pagamento pela inadimplência do comprador. Recurso de revista conhecido e desprovido. 4. INDENIZAÇÃO PELOCOMBUSTÍVELE DESGASTE DO VEÍCULO. O Tribunal Regional não emitiu tese explícita a respeito da impossibilidade de ser arbitrado o dano material por prova testemunhal, limitando-se ao exame do uso do veículo particular pelo Recorrido e a correção do valor arbitrado na sentença. Incidência dos óbices das Súmulas 296 e 297 do TST. Recurso de revista não conhecido. 5. HONORÁRIOS ADVOCATÍCIOS. A mera indicação de ofensa à Lei nº 5.584/70 atrai a incidência do item I da Súmula nº 221, no sentido de que a admissibilidade do recurso de revista por violação tem como pressuposto a indicação expressa de dispositivo de lei ou da Constituição tido como violado. Por sua vez, julgados oriundos do mesmo Tribunal Regional prolator do acórdão recorrido não impulsionam a revista, pois em desacordo com o art. 896, ¿a¿, da CLT (OJ 111 da SBDI-1/TST). Recurso de revista não conhecido. 6. MULTA DO ART. 477, § 8°, DA CLT. VÍNCULO EMPREGATÍCIO RECONHECIDO EM JUÍZO. CONTROVÉRSIA DESTITUÍDA DE RAZOABILIDADE. PRESTAÇÃO DE SERVIÇOS E ATRIBUTOS DA RELAÇÃO DE EMPREGO. CABIMENTO DA PENALIDADE. Quando as parcelas devidas pela dissolução contratual decorrem de provimento judicial, havendo, antes, controvérsiasustentávelquanto à existência de relação de emprego ou quanto à razão de desfazimento do vínculo, impossível a condenação ao pagamento da multa a que alude o art. 477, § 8º, da CLT. Note-se, entretanto, que a discussão há de ser razoável, sob pena de se premiar o empregador que, voluntariamente, lesa o patrimônio jurídico de seu empregado. Embora a existência da relação de emprego venha a ser dirimida em Juízo, não se pode premiar a conduta antijurídica da empresa, que, órfã de qualquer lenitivo, mostra-se em mora, assim merecendo a penalidade a que alude o art. 477, § 8°, da CLT. Recurso de revista conhecido e desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:35', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2016-03-09;133700-2007-443-2-0', 'Acórdão do processo Nº RR - 133700-81.2007.5.02.0443', 'urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2016-03-09;133700-2007-443-2-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2016-03-09', NULL, 'INDENIZAÇÃO POR DANOS MORAIS E MATERIAIS. PENSIONAMENTO E LUCROS CESSANTES. ACIDENTE DO TRABALHO. VÍTIMA FATAL DE ATAQUE DA FACÇÃO "PCC". EXERCÍCIO DE VIGILÂNCIA. FUNÇÃO DISTINTA DA QUE FORA CONTRATADO. POSTO DECOMBUSTÍVEIS. RESPONSABILIDADE DO EMPREGADOR. 1. O novo Código Civil Brasileiro manteve, como regra, a teoria da responsabilidade civil subjetiva, calcada na culpa. Inovando, porém, em relação ao Código Civil de 1916, passou a prever, expressamente, a responsabilidade civil objetiva do empregador, com fundamento no risco gerado pela atividade empresarial (artigo 927, parágrafo único, do Código Civil). Tal acréscimo apenas veio a coroar o entendimento de que os danos sofridos pelo trabalhador, em razão da execução do contrato de emprego, conduzem à responsabilidade objetiva do empregador, quando a atividade do empregado é considerada de risco. 2. No caso dos autos, é inafastável a constatação de que a atividade do filho do autor, seja no exercício das funções de frentista, seja quando fora deslocado para funcionar como o responsável a acionar a polícia no caso de ataque da facção criminosa "PCC", reveste-se de risco flagrantemente acentuado, porquanto expõe o empregado à probabilidade da ocorrência de diversas modalidades de sinistro, especialmente os crimes praticados contra o patrimônio da empresa. Conquanto a segurança pública constitua dever do Estado, tal circunstância não ilide, no caso, a responsabilidade do empregador, porquanto o risco gerado decorre da própria atividade do empregado cuja força de trabalho era explorada. A incomum situação descrita nos autos em que o filho do autor acabou como uma das vítimas fatais do ataque -  previamente divulgado na imprensa - da facção criminosa PCC ao posto decombustíveisdurante a sua jornada de trabalho enseja, portanto, o reconhecimento da responsabilidade objetiva do empregador pelos danos morais daí advindos, na forma do artigo 927, parágrafo único, do Código Civil. Precedentes. 3. Caracterizada a responsabilidade da empresa pela morte do filho do autor da presente reclamatória tanto pela teoria da responsabilidade objetiva -  atividade de risco -  quanto pela teria da responsabilidade subjetiva -  culpa por omissão decorrente da não observância do dever geral de cautela ao deslocá-lo da atividade de frentista para a de único defensor do patrimônio da empresa - e comprovados, no caso em comento, o dano e o nexo de causalidade, conclui-se que o Tribunal Regional, ao deferir a pretensão do reclamante sob o fundamento de que resultou demonstrada a culpa do empregador, proferiu decisão em estrita observância ao preceituado no artigo 7º, inciso XXVIII, da Constituição da República. 4. Recurso de Revista não conhecido. INDENIZAÇÃO POR DANOS MORAIS E MATERIAIS. MORTE DE EMPREGADO. VÍTIMA DE POSSÍVEL ATAQUE DE FACÇÃO CRIMINOSA. R$ 180.000,00 (CENTO E OITENTA MIL REAIS). PENSÃO MENSAL NO VALOR DE R$ 530,00 (QUINHENTOS E TRINTA REAIS) MENSAIS ATÉ A DATA EM QUE A VÍTIMA COMPLETARIA 72 ANOS DE IDADE. QUANTUM INDENIZATÓRIO. 1. Diante da ausência de critérios objetivos norteando a fixação do quantum devido a título de indenização por danos morais e materiais, cabe ao julgador arbitrá-lo de forma equitativa, pautando-se pelos princípios da razoabilidade e da proporcionalidade, bem como pelas especificidades de cada caso concreto, tais como: a situação do ofendido, a extensão e gravidade do dano suportado e a capacidade econômica do ofensor. Tem-se, de outro lado, que o exame da prova produzida nos autos é atribuição exclusiva das instâncias ordinárias, cujo pronunciamento, nesse aspecto, é soberano. Com efeito, a proximidade do julgador, em sede ordinária, com a realidade cotidiana em que contextualizada a controvérsia a ser dirimida habilita-o a equacionar o litígio com maior precisão, sobretudo no que diz respeito à aferição de elementos de fato sujeitos a avaliação subjetiva, necessária à estipulação do valor da indenização. Conclui-se, num tal contexto, que não cabe a esta instância superior, em regra, rever a valoração emanada das instâncias ordinárias em relação ao montante arbitrado a título de indenização por danos morais e materiais, para o que se faria necessário o reexame dos elementos de fato e das provas constantes dos autos. Excepcionam-se, todavia, de tal regra as hipóteses em que o quantum indenizatório se revele extremamente irrisório ou nitidamente exagerado, denotando manifesta inobservância aos princípios da razoabilidade e da proporcionalidade, aferível de plano, sem necessidade de incursão na prova. 2. No caso dos autos, o Tribunal Regional, ao fixar o valor atribuído à indenização devida por danos morais em R$ 180.000,00 (cento e oitenta mil reais), levou em consideração os limites do pedido da inicial, a culpa do empregador e a gravidade do evento que culminou na morte do filho do autor da reclamatória e as repercussões pessoais, familiares e sociais, a situação econômica do empregador e o caráter pedagógico da sanção. De outro lado, na fixação da indenização por danos materiais -  pensão mensal em 100% do valor do salário-base percebido pelo de cujus - o Tribunal Regional levou em consideração a idade da vítima, as circunstâncias em que o acidente do trabalho ocorreu, o grau de culpa da empresa e os lucros que deixaram de ser auferidos pela vítima que, na data de sua morte, tinha apenas 22 (vinte e dois) anos de idade. 3. Consideradas tais hipóteses, não há cogitar na revisão do valor da condenação, para o que se faria necessário rever os critérios subjetivos que levaram o julgador à conclusão ora combatida, à luz das circunstâncias de fato reveladas nos autos. 4. Recurso de Revista não conhecido. HONORÁRIOS ADVOCATÍCIOS. INDENIZAÇÃO. JUSTIÇA DO TRABALHO. LEI N.º 5.584/70. ARTIGOS 389 E 404 DO CÓDIGO CIVIL. APLICAÇÃO SUBSIDIÁRIA NÃO AUTORIZADA. 1. Por não decorrerem da aplicação do princípio da mera sucumbência, os honorários advocatícios, na Justiça do Trabalho, somente são devidos quando demonstrado o preenchimento concomitante dos requisitos exigidos no artigo 14 da Lei n.º 5.584/70: o direito ao benefício da justiça gratuita e a assistência do sindicato. Nesse sentido dispõe a Súmula nº 219, I, deste Tribunal Superior. 2. Havendo regência legal específica a regular a matéria, não há como admitir a aplicação subsidiária do Código Civil, com o fim de tornarsustentávelo direito à indenização a reparar perdas e danos oriundos da contratação de advogado particular. 3. Recurso de Revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:35', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;rr:2011-09-14;41600-2006-29-1-0', 'Acórdão do processo Nº RR - 41600-52.2006.5.01.0029', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;rr:2011-09-14;41600-2006-29-1-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2011-09-14', NULL, 'RECURSO DE REVISTA. 1. CONTRATAÇÃO DE TRABALHADOR POR EMPRESA INTERPOSTA - COOPERATIVA - FRAUDE - RECONHECIMENTO DE RELAÇÃO DE EMPREGO DIRETAMENTE COM O TOMADOR DE SERVIÇOS. A Corte de origem, com esteio na prova dos autos (art. 131 do CPC), reconheceu o vínculo de emprego entre pretenso associado da cooperativa - assim criada com intuito de burlar a legislação trabalhista - e a recorrente, por verificar que, efetivamente, restaram preenchidos os requisitos essenciais ao negócio jurídico (arts. 2º, 3º e 9º da CLT). Recurso de revista não conhecido. 2. HORAS EXTRAS. ÔNUS DA PROVA. APLICAÇÃO DO ART. 359 DO CPC. "É ônus do empregador que conta com mais de 10 (dez) empregados o registro da jornada de trabalho na forma do art. 74, § 2º, da CLT. A não-apresentação injustificada dos controles de frequência gera presunção relativa de veracidade da jornada de trabalho, a qual pode ser elidida por prova em contrário" (Súmula 338, I, do TST). Recurso de revista não conhecido. 3. FORMA DE REMUNERAÇÃO. Não se evidenciando nos autos que o reclamante recebia por produção, inaplicável o entendimento consubstanciado na OJ 235 da SBDI-1 do TST. Recurso de revista não conhecido. 4. REFLEXOS DE REPOUSOS SEMANAIS REMUNERADOS, INTEGRADOS POR HORAS EXTRAS, EM TÍTULOS TRABALHISTAS. Nos termos da OJ nº 394 da SBDI-1/TST, "a majoração do valor do repouso semanal remunerado, em razão da integração das horas extras habitualmente prestadas, não repercute no cálculo das férias, da gratificação natalina, do aviso prévio e do FGTS, sob pena de caracterização de "bis in idem". Recurso de revista conhecido e provido. 5. MULTA DO ART. 477, § 8°, DA CLT. VÍNCULO EMPREGATÍCIO RECONHECIDO EM JUÍZO. CONTROVÉRSIA DESTITUÍDA DE RAZOABILIDADE. CABIMENTO DA PENALIDADE. Quando as parcelas devidas pela dissolução contratual decorrem de provimento judicial, havendo, antes, controvérsiasustentávelquanto à existência de relação de emprego, impossível a condenação ao pagamento da multa a que alude o art. 477, § 8º, da CLT. Note-se, entretanto, que a discussão há de ser razoável, sob pena de se premiar o empregador que, voluntariamente, lesa o patrimônio jurídico de seu empregado. Embora a existência da relação de emprego venha a ser dirimida em Juízo, não se pode premiar a conduta antijurídica da empresa, que, órfã de qualquer lenitivo, mostra-se em mora, assim merecendo a penalidade a que alude o art. 477, § 8°, da CLT. Recurso de revista conhecido e desprovido. 6. DANO MORAL. CONFIGURAÇÃO. Com a indicação de dispositivos que não protegem a tese recursal, impossível o conhecimento da revista. Recurso de revista não conhecido. 7. INDENIZAÇÃO POR DANO MORAL. PARÂMETROS RELEVANTES PARA AFERIÇÃO DO VALOR DA INDENIZAÇÃO. SISTEMA ABERTO. DOSIMETRIA DO "QUANTUM" INDENIZATÓRIO. 7.1. Dano moral consiste em lesão a atributos íntimos da pessoa, de modo a atingir valores juridicamente tutelados, cuja mensuração econômica envolve critérios objetivos e subjetivos. 7.2. A indenização por dano moral revela conteúdo de interesse público, na medida em que encontra ressonância no princípio da dignidade da pessoa humana, sob a perspectiva de uma sociedade que se pretende livre, justa e solidária (CF, arts. 1º, III, e 3º, I). 7.3. A dosimetria do "quantum" indenizatório guarda relação direta com a existência e a extensão do dano sofrido, o grau de culpa e a perspectiva econômica do autor e da vítima, razão pela qual a atuação dolosa do agente reclama reparação econômica mais severa, ao passo que a imprudência ou negligência clamam por reprimenda mais branda. 7.4. Assim, à luz do sistema aberto, cabe ao julgador, atento aos parâmetros relevantes para aferição do valor da indenização por dano moral, fixar o "quantum" indenizatório com prudência, bom senso e razoabilidade, sob pena de afronta ao princípio da restauração justa e proporcional. Recurso de revista não conhecido. 8. SALÁRIO "IN NATURA".COMBUSTÍVEL. AUSÊNCIA DE PREQUESTIONAMENTO DO TEMA SOB O ENFOQUE PRETENDIDO PELA PARTE. Apegado a aspectos não prequestionados (Súmula 297, I e II, do TST), não prospera o recurso de revista. Recurso de revista não conhecido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:35', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;airr:2021-02-10;1137-2013-7-9-0', 'Acórdão do processo Nº AIRR - 1137-68.2013.5.09.0007', 'urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;airr:2021-02-10;1137-2013-7-9-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2021-02-10', NULL, 'AGRAVO DE INSTRUMENTO INTERPOSTO PELO RECLAMANTE RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI Nº 13.015/2014. PRELIMINAR DE NULIDADE DO ACÓRDÃO POR NEGATIVA DE PRESTAÇÃO JURISDICIONAL. INOBSERVÂNCIA DE PRESSUPOSTO DE ADMISSIBILIDADE PREVISTO NO ARTIGO 896, § 1º-A, I, DA CLT. AUSÊNCIA DE INDICAÇÃO DE TRECHO DO ACÓRDÃO RECORRIDO E DOS EMBARGOS DE DECLARAÇÃO. 1. Nos termos do artigo 896, § 1º-A, I, da CLT, incluído pela Lei n.º 13.015/2014, "sob pena de não conhecimento, é ônus da parte: I - indicar o trecho da decisão recorrida que consubstancia o prequestionamento da controvérsia objeto do recurso de revista". 2. Esta Corte superior, por suas Turmas e no âmbito da Subseção I Especializada em Dissídios Individuais, tem reiteradamente decidido que é imprescindível que o recorrente, ao arguir nulidade por negativa de prestação jurisdicional, demonstre, mediante a transcrição do trecho da petição dos Embargos de Declaração e do trecho do acórdão prolatado em sede de Embargos de Declaração, a recusa do Tribunal Regional em prestar a jurisdição que lhe era devida.  Precedentes. 3. Constatada, no presente caso, a ausência de transcrição tanto do trecho dos Embargos de Declaração quanto do trecho do acórdão do Tribunal Regional que os rejeitou quanto ao pedido, resulta insuscetível de provimento o apelo. 4. Agravo de Instrumento a que se nega provimento. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI N.º 13.015/2014. DOCUMENTO NOVO. REJEIÇÃO. DUPLO FUNDAMENTO. Encontra óbice na Súmula n.º 422 desta Corte superior o conhecimento do Recurso de Revista quando o Tribunal Regional utiliza mais de um fundamento para proferir sua decisão e o recorrente limita-se a atacar apenas um deles, ignorando por completo a outra razão de decidir sobre a qual erigida a decisão, suficiente para sustentá-la de forma autônoma. Agravo de Instrumento a que se nega provimento. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI N.º 13.015/2014. INDENIZAÇÃO POR DANOS MORAIS. FIXAÇÃO DO QUANTUM INDENIZATÓRIO. 1. O exame da prova produzida nos autos é atribuição exclusiva das instâncias ordinárias, cujo pronunciamento, nesse aspecto, é soberano. Com efeito, a proximidade do julgador, em sede ordinária, com a realidade cotidiana em que contextualizada a controvérsia a ser dirimida habilita-o a equacionar o litígio com maior precisão, sobretudo no que diz respeito à aferição de elementos de fato sujeitos a avaliação subjetiva, necessária à estipulação do valor da indenização por danos morais. Conclui-se, num tal contexto, que não cabe a esta instância superior, em regra, rever a valoração emanada das instâncias ordinárias em relação ao montante arbitrado a título de indenização por danos morais, para o que se faria necessário o reexame dos elementos de fato e das provas constantes dos autos. Excepcionam-se, todavia, de tal regra as hipóteses em que o quantum indenizatório se revele extremamente irrisório ou nitidamente exagerado, denotando manifesta inobservância aos princípios da razoabilidade e da proporcionalidade, aferível de plano, sem necessidade de incursão na prova. 2. No caso dos autos, tem-se que somente com o revolvimento do substrato fático-probatório dos autos -  procedimento vedado nesta instância extraordinária -  seria possível chegar a conclusão diversa daquela erigida pelo Tribunal Regional, no sentido de que o valor de R$ 10.000,00, arbitrado à condenação, revela-se adequado para indenizar os danos sofridos pelo obreiro.  Incidência da Súmula n.º 126 do Tribunal Superior do Trabalho. 3. Agravo de Instrumento a que se nega provimento.  AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI N.º 13.015/2014. RESSARCIMENTO DE DESPESAS. VALOR PAGO PELO RECLAMADO. QUILÔMETROS RODADOS. MATÉRIA FÁTICA.É insuscetível de revisão, em sede extraordinária, a decisão proferida pelo Tribunal Regional à luz da prova carreada aos autos. Somente com o revolvimento do substrato fático-probatório dos autos seria possível afastar a premissa sobre a qual se erigiu a conclusão consagrada pela Corte de origem, no sentido de que o valor recebido pelo reclamante é suficiente para cobrir as despesas comcombustível, manutenção e depreciação do veículo. Incidência da Súmula n.º 126 do Tribunal Superior do Trabalho. Agravo de Instrumento a que se nega provimento. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI N.º 13.015/2014. HORAS EXTRAS. CARGO DE CONFIANÇA. ARTIGO 62, II, DA CONSOLIDAÇÃO DAS LEIS DO TRABALHO. 1. Nos termos da jurisprudência pacífica desta Corte superior, "a jornada de trabalho do empregado de banco gerente de agência é regida pelo art. 224, § 2º, da CLT. Quanto ao gerente-geral de agência bancária, presume-se o exercício de encargo de gestão, aplicando-se-lhe o art. 62 da CLT" (Súmula nº 287 do TST). 2. Constatado nos autos que o reclamante era a autoridade máxima na agência, tem-se que o Tribunal Regional decidiu em consonância com a jurisprudência sumulada desta Corte uniformizadora, o que inviabiliza o processamento do Recurso de Revista, ante a incidência do óbice contido na Súmula nº 333 desta Corte superior. 3. Agravo de Instrumento não provido. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI N.º 13.015/2014. INTERVALO INTRAJORNADA. GERENTE-GERAL. ARTIGO 62, II, DA CLT. 1. A jurisprudência iterativa, notória e atual desta Corte superior tem-se orientado no sentido de que o enquadramento do empregado no artigo 62, II, da CLT afasta a possibilidade de pagamento de hora extra, inclusive da relativa à supressão do intervalo intrajornada. 2. Revelando a decisão recorrida consonância com a jurisprudência desta Corte superior, o processamento do Recurso de Revista encontra óbice na Súmula nº 333 deste Tribunal Superior. 3. Agravo de Instrumento não provido. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI N.º 13.015/2014. HONORÁRIOS ADVOCATÍCIOS. INDENIZAÇÃO. ARTIGO 404 DO CÓDIGO CIVIL. SÚMULA N.º 219, I, DO TRIBUNAL SUPERIOR DO TRABALHO. 1. Por não decorrerem da aplicação do princípio da mera sucumbência, os honorários advocatícios, na Justiça do Trabalho, somente são devidos quando demonstrado o preenchimento concomitante dos requisitos exigidos no artigo 14 da Lei n.º 5.584/70: o direito ao benefício da justiça gratuita e a assistência do sindicato. Nesse sentido dispõe a Súmula n.º 219, I, deste Órgão uniformizador. 2. Havendo regência legal específica a regular a matéria, não há como admitir a aplicação subsidiária do Código Civil, com o fim de tornarsustentávelo direito à indenização a reparar perdas e danos oriundos da contratação de advogado particular. 3. Agravo de Instrumento a que se nega provimento. AGRAVO DE INSTRUMENTO INTERPOSTO PELO RECLAMADO RECURSO DE REVISTA INTERPOSTO A ACÓRDÃO PUBLICADO NA VIGÊNCIA DA LEI N.º 13.015/2014. INDENIZAÇÃO POR DANO MORAL. TRANSPORTE DE VALORES. GERENTE DE AGÊNCIA. EXERCÍCIO DE FUNÇÃO DIVERSA DAQUELA PARA A QUAL O EMPREGADO FOI CONTRATADO. A jurisprudência iterativa, notória e atual desta Corte superior tem-se orientado no sentido de que a mera conduta da empresa de atribuir aos seus empregados a atividade detransporte de valoresdá ensejo à compensação por danos morais. Leva-se em consideração, para tanto, o risco à integridade física (inclusive de morte) inerente à função em exame e o desvio funcional perpetrado pelas empresas, que, em vez de contratar pessoal especializado, se utilizam de empregados comuns. A caracterização do dano moral, em regra, prescinde da comprovação objetiva de dor, sofrimento ou abalo psicológico, especialmente diante da impossibilidade de sua comprovação material. Considera-se, assim, a ocorrência do danoin re ipsa, sendo necessária apenas a comprovação do fato lesivo, o qual, por si só, representa agressão aos direitos da personalidade e, por conseguinte, dano moral à vítima. Precedentes da SBDI-I e das Turmas deste Tribunal Superior. Agravo de Instrumento a que se nega provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('combustível sustentável', '2025-07-12 17:36:35', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.5:acordao;rms:2021-08-10;63567-2079364', 'AgRg no RMS 63567 / MS', 'urn:lex:br:superior.tribunal.justica;turma.5:acordao;rms:2021-08-10;63567-2079364', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Rms', '2021-08-10', NULL, 'AGRAVO REGIMENTAL EM RECURSO ORDINÁRIO EM MANDADO DE SEGURANÇA.
ALEGAÇÃO DE NULIDADE DE JULGAMENTO MONOCRÁTICO QUANDO HÁ PEDIDO DA
PARTE DE REALIZAÇÃO DE SUSTENTAÇÃO ORAL QUE SE AFASTA. INEXISTÊNCIA
DE VIOLAÇÃO AO PRINCÍPIO DA COLEGIALIDADE. CRIME AMBIENTAL. POLUIÇÃO
(ART. 54 DA LEI 9.605/98). ACIDENTE FERROVIÁRIO QUE CULMINOU NO
DESCARRILHAMENTO DE VAGÕES TANQUE E NO VAZAMENTO DE 67.550 LITROS DE
ÓLEO DIESEL. ALEGAÇÕES DE INÉPCIA DA DENÚNCIA E DE AUSÊNCIA DE JUSTA
CAUSA AFASTADAS. IMPUTAÇÃO À IMPETRANTE DE OMISSÃO DOLOSA NA
MANUTENÇÃO DA MALHA FERROVIÁRIA SOB SUA RESPONSABILIDADE. AGRAVO
REGIMENTAL DESPROVIDO.
1. O relator no Superior Tribunal de Justiça está autorizado a
proferir decisão monocrática, que fica sujeita à apreciação do
respectivo órgão colegiado mediante a interposição de agravo
regimental, não havendo violação do princípio da colegialidade
(arts. 932, III, do CPC e 34, XVIII, a e b, do RISTJ). (AgRg no HC
594.635/SP, Rel. Ministro JOÃO OTÁVIO DE NORONHA, QUINTA TURMA,
julgado em 16/03/2021, DJe 19/03/2021).
2. Lado outro, a prolação de decisão unilateral pelo Relator não
fere o princípio da colegialidade, tampouco caracteriza cerceamento
de defesa diante na não viabilidade da sustentação oral quando
solicitada. Ora, a adoção da atual sistemática de julgamentos, seja
da forma monocrática, quando o caso, seja da forma virtual; além de
encontrar respaldo legal, mostra-se necessária nesse momento de
Pandemia pela qual passamos e que exige distanciamento social como
protocolo de segurança sanitária, visando a não propagação do vírus.
Importante gizar, outrossim, que os temas a serem destacados na
sustentação oral, bem como o enfoque das teses que busca a parte em
sua requerida oratória, permanecem viabilizados através da
apresentação de memoriais a todos os membros do órgão colegiado,
afastando, assim, qualquer prejuízo à parte.
3. Plenamente possível, desta forma, que seja proferida decisão
monocrática por Relator, sem qualquer afronta ao princípio da
colegialidade ou cerceamento de defesa, quando todas as questões são
amplamente debatidas, havendo jurisprudência dominante sobre o tema,
ainda que haja pedido de sustentação oral (AgRg no HC 647.128/RJ,
Rel. Ministro FELIX FISCHER, QUINTA TURMA, julgado em 13/04/2021,
DJe 19/04/2021).
4. Consolidou-se, nesta Superior Corte de Justiça, entendimento no
sentido de que somente é cabível o trancamento da persecução penal
quando houver comprovação, de plano, da ausência de justa causa,
seja em razão da atipicidade da conduta praticada pelo acusado, seja
pela ausência de indícios de autoria e materialidade delitiva, ou,
ainda, pela incidência de causa de extinção da punibilidade.
5. A peça acusatória preenche os requisitos do art. 41 do Código de
Processo Penal, uma vez que descreve a tipificação legal da conduta
imputada à ora recorrente, narra os fatos e as circunstâncias do
delito, traz a qualificação da recorrente, aponta indícios mínimos
de materialidade e de autoria e expõe o nexo causal entre a conduta
omissiva da recorrente e o dano ambiental advindo do derramamento de
óleo diesel no solo.
6. Não há como se reconhecer a imputação de conduta culposa, se a
denúncia deixa claro que, ao descumprir seu dever legal, como
concessionária de um serviço público, de manutenção dos trilhos da
malha ferroviária que operava, a empresa recorrente aceitou os
riscos da ocorrência de um acidente, agindo, portanto, com dolo
eventual. Sua omissão dolosa transparece, também, do fato de que, em
datas anteriores e próximas ao local do acidente descrito nos autos
que culminou como o derramamento de 65.550 litros de óleo diesel no
solo, a empresa já havia dado causa a outros acidentes ferroviários
que também ocasionaram o derramamento de óleo diesel, ocorridos em
razão do deficiente estado da malha ferroviária sob a
responsabilidade, o que reforça a tese de que a recorrente tinha
prévio conhecimento tanto da falha na manutenção dos trilhos quanto
das consequências que dela poderiam advir.
7. Não prospera, tampouco, a alegação de que a denúncia não demostra
que a infração imputada à recorrente foi cometida (i) por decisão de
seu representante legal ou contratual, ou de seu órgão colegiado;
(ii) no interesse ou benefício do ente moral, conforme exige o art.
3º da Lei 9.605/98. Isso porque a decisão de deixar de realizar a
manutenção adequada da malha ferroviária no local em que veio a
acontecer o acidente corresponde a deliberação anterior da empresa
relacionada à gestão e alocação de recursos, deliberação essa que
somente poderia ter sido tomada por órgão de comando dentro da
estrutura hierárquica da empresa, já que a gestão de recursos não
incumbe a simples prepostos da concessionária de serviços públicos.
Ademais, é possível presumir que a escolha de direcionamento de
recursos a outras áreas em detrimento de alocá-los para manutenção
da malha ferroviária tinha em mente a obtenção de maior lucro por
parte da empresa.
8. A prova concludente da existência de dano ambiental não constitui
requisito para o aferimento de justa causa a possibilitar o trâmite
de ação penal ambiental, seja porque tais provas são necessárias
para a condenação, seja porque a jurisprudência desta Corte vem
entendendo que "a Lei de Crimes Ambientais deve ser interpretada à
luz dos princípios do desenvolvimentosustentávele da prevenção,
indicando o acerto da análise que a doutrina e a jurisprudência têm
conferido à parte inicial do art. 54 da Lei n. 9.605/1998, de que a
mera possibilidade de causar dano à saúde humana é idônea a
configurar o crime de poluição, evidenciada sua natureza formal ou,
ainda, de perigo abstrato." (RHC 62.119/SP, Rel. Ministro GURGEL DE
FARIA, QUINTA TURMA, DJe 5/2/2016). Precedentes desta Corte.
Situação em que a peça inicial acusatória faz referência expressa à
existência de Boletim de Ocorrência da Polícia Civil nº 933/2012,
Laudo de Constatação ambiental, Laudo pericial n. 15.810, além de
outros documentos, todos elementos que consubstanciam os necessários
indícios mínimos de materialidade do delito.
De mais a mais, ainda que a inicial acusatória não tenha efetuado
uma descrição detalhada da extensão dos possíveis danos ambientais
causados pelo derramamento de óleo diesel, é perfeitamente plausível
admitir-se que 67.550 litros de talcombustíveltenham se espalhado
por área considerável e que tenham poluído tanto o solo quanto a
flora existente no local.
9. Agravo regimental a que se nega provimento.
Decis?o
Vistos, relatados e discutidos os autos em que são partes as acima
indicadas, acordam os Ministros da Quinta Turma do Superior Tribunal
de Justiça,  por unanimidade, negar provimento ao agravo regimental.
 Os Srs. Ministros Ribeiro Dantas, Joel Ilan Paciornik, Jesuíno
Rissato (Desembargador Convocado) e João Otávio de Noronha votaram
com o Sr. Ministro Relator.
Licenciado o Sr. Ministro Felix Fischer.
Convocado o Sr. Ministro Jesuíno Rissato (Desembargador Convocado).', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('projeto de lei', '2025-07-12 17:36:38', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2013-05-09;5555', '[ProjetodeLei(CD) nº 5555/2013 >ProjetodeLeida Câmara nº 18/2017 >ProjetodeLei(CD) nº 5555/2013 (Emenda-CD) :Leinº 13.772 de 19/12/2018 ]', 'urn:lex:br:senado.federal:projeto.lei;plc:2017;18', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Senado Federal', '2013-05-09', NULL, 'Inclui a comunicação no rol de direitos assegurados à mulher pelaLeiMaria da Penha, bem como reconhece que a violação da sua intimidade consiste em uma das formas de violência doméstica e familiar; tipifica a exposição pública da intimidade sexual; e altera aLein° 11.340 de 7 de agosto de 2006 (LeiMaria da Penha), e o Decreto-Lein° 2.848, de 7 de dezembro de 1940 (Código Penal).', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
