INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('equipamentos de transporte', '2025-07-12 17:36:41', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.3:acordao:2004-11-04;209514', 'Acórdão nº 209514 do Processo nº20000110512757apc', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.3:acordao:2004-11-04;209514', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2004-11-04', 'MANUTENÇÃO, OBRIGAÇÃO DE DAR, INDENIZAÇÃO, DANO MATERIAL, CUSTAS, NOTIFICAÇÃO EXTRAJUDICIAL, EMPRESA,TRANSPORTEAÉREO, EXTRAVIO,EQUIPAMENTOMÉDICO, APLICAÇÃO, CÓDIGO DE DEFESA DO CONSUMIDOR, EXISTÊNCIA, RESPONSABILIDADE OBJETIVA; PROCEDÊNCIA, DENUNCIAÇÃO DA LIDE, SEGURADORA, DETERMINAÇÃO, CONTRATO.', 'AÇÃO DE REPARAÇÃO DE DANOS - EMPRESA PRESTADORA DE SERVIÇODETRANSPORTEAÉREO - EXTRAVIODEEQUIPAMENTOMÉDICO UTILIZADO PARA REALIZAÇÃO DE EXAMES DE FLUXOMETRIA E URODINÂMICA - RELAÇÃO DE CONSUMO - APLICAÇÃO DO CÓDIGO DE DEFESA DO CONSUMIDOR - RESPONSABILIDADE - OBRIGAÇÃO DE INDENIZAR OS LUCROS CESSANTES - DENUNCIAÇÃO DA LIDE À EMPRESA SEGURADORA. 1 - NÃO OBSTANTE SEREM AS PARTES PESSOAS JURÍDICAS, RECONHECE-SE ENTRE AMBAS UMA RELAÇÃO DE CONSUMO, PORQUANTO OBJETO DO CONTRATO FIRMADO ENTRE AS MESMAS NÃO É A AQUISIÇÃO DO APARELHO MÉDICO EM SI, TAMPOUCO SUA UTILIZAÇÃO, MAS SIM SEUTRANSPORTEPARA O LOCAL INDICADO, SENDO A EMPRESA AUTORA A DESTINATÁRIA FINAL DA PRESTAÇÃO REGULARMENTE CONTRATADA COM A EMPRESA RÉ, QUAL SEJA, O SERVIÇODETRANSPORTEDEEQUIPAMENTO. 2 - PREVALECEM AS DISPOSIÇÕES DO CÓDIGO DE DEFESA DO CONSUMIDOR EM RELAÇÃO À CONVENÇÃO DE VARSÓVIA, DERROGANDO-SE OS PRECEITOS DESTA QUE ESTABELECEM A LIMITAÇÃO DA RESPONSABILIDADE DAS EMPRESASDETRANSPORTEAÉREO. 3 - NOS TERMOS DO ART. 14 DO CDC, "O FORNECEDOR DE SERVIÇOS RESPONDE, INDEPENDENTEMENTE DA EXISTÊNCIA DE CULPA, PELA REPARAÇÃO DOS DANOS CAUSADOS AOS CONSUMIDORES POR DEFEITOS RELATIVOS À PRESTAÇÃO DE SERVIÇOS", SALVO SE PROVADO QUE O DEFEITO NA PRESTAÇÃO DO SERVIÇO INEXISTE OU QUE O DANO SE DEU POR CULPA EXCLUSIVA DO CONSUMIDOR OU DE TERCEIROS, HIPÓTESE DE QUE NÃO TRATA OS AUTOS. 4 - O QUANTUM DEVIDO A TÍTULO DE LUCROS CESSANTES DEVE SER APURADO EM LIQUIDAÇÃO DE SENTENÇA, TOMANDO-SE POR FUNDAMENTO A MEDIDA DO FATURAMENTO OBTIDO DECORRENTE, EXCLUSIVAMENTE, DA REALIZAÇÃO DE EXAMES DA URODINÂMICA E FLUXOMETRIA. 5 - TENDO EM VISTA O CONTRATO DE SEGURO FIRMADO ENTRE A EMPRESADETRANSPORTEAÉREO E A EMPRESA SEGURADORA, PREVENDO A OBRIGAÇÃO DESTA EM REEMBOLSAR AQUELA EM FACE DE INCIDENTES RELATIVOS ATRANSPORTEDE CARGA, ABRANGENDO-SE AÍ A INDENIZAÇÃO POR LUCROS CESSANTES DEVIDOS ENQUANTO OEQUIPAMENTOPERMANECEU EXTRAVIADO, PROCEDE A DENUNCIAÇÃO DA LIDE À SEGURADORA, QUE DEVERÁ PAGAR À DENUNCIANTE, CASO ESTA OPTE PELA UTILIZAÇÃO DO SEU DIREITO SECURITÁRIO, OS DANOS EM QUE FOI CONDENADA. 6 - RECURSO PROVIDO EM PARTE, APENAS PARA ACOLHER A DENUNCIAÇÃO DA LIDE.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('equipamentos de transporte', '2025-07-12 17:36:41', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:lei:1975-12-11;6288', 'Lei nº 6.288, de 11 de Dezembro de 1975', 'urn:lex:br:federal:lei:1975-12-11;6288', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '1975-12-11', 'TRIBUTAÇÃO ,  ISENÇÃO ,  INCENTIVO FISCAL ,TRANSPORTEDE CARGA . COMPETENCIA ,  RESPONSABILIDADE ,  EMPRESA ,  MERCADORIA NACIONAL ,  MERCADORIA ESTRANGEIRA . NORMAS ,  REGULAMENTAÇÃO ,TRANSPORTE,  MERCADORIA NACIONAL ,  MERCADORIA ESTRANGEIRA . ESPECIE ,  EMBALAGEM ,  UTILIZAÇÃO ,TRANSPORTE,  MERCADORIA ,EQUIPAMENTOS,  CARGA . DEFINIÇÃO ,  CONTAINER ,  SERVIÇO ,TRANSPORTE.', 'Dispõe sobre a utilização, movimentação etransporte, inclusive intermodal, de mercadorias em unidades de carga, e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('equipamentos de transporte', '2025-07-12 17:36:41', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2020-03-19;0010487-11.2015.5.03.0029', 'Acórdão PJe TRT 3ª / Terceira Turma / 2020-03-19', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2020-03-19;0010487-11.2015.5.03.0029', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2020-03-19', 'RESPONSABILIDADE - CONTRATODETRANSPORTE', '- TERCEIRIZAÇÃO -TRANSPORTE- ATIVIDADE ESPECIALIZADA - RELAÇÃO COMERCIAL - RESPONSABILIDADE DA CONTRATANTE - INEXISTÊNCIA. Tendo as Reclamadas firmado contratodetransportedeequipamentos, a relação existente entre elas revela natureza eminentemente comercial, sobretudo porque se trata de pactuaçãodetransporte/entrega de produto. Assim, em não se tratando de terceirização de serviços, a ativação do Autor como empregado da transportadora, nas circunstâncias narradas, não transfere qualquer responsabilidade à contratante, por inaplicável à hipótese o entendimento cristalizado na Súmula 331 do col. TST.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('equipamentos de transporte', '2025-07-12 17:36:41', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:distrital:lei:2017-09-25;6007', 'Lei nº 6007, de 25 de setembro de 2017', 'urn:lex:br;distrito.federal:distrital:lei:2017-09-25;6007', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Distrital', '2017-09-25', 'TRANSPORTEPÚBLICO COLETIVO.EQUIPAMENTODESEGURANÇA, instalação, obrigatoriedade. VIDEOMONITORAMENTO.', 'Obriga à instalação de dispositivo eletrônico de segurança (Botão do Pânico) em todos os veículos coletivos que compõem a frotadetransportepúblico que circula no Distrito Federal e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
