INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('equipamentos de transporte', '2025-07-12 17:36:41', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2019-10-17;0010108-58.2017.5.03.0075', 'Acórdão PJe TRT 3ª / Segunda Turma / 2019-10-17', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2019-10-17;0010108-58.2017.5.03.0075', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2019-10-17', 'RESPONSABILIDADE - CONTRATODETRANSPORTE', 'CONTRATODETRANSPORTE. RESPONSABILIDADE SUBSIDIÁRIA. NÃO CONFIGURAÇÃO. O contratodetransporteé regido pela Lei nº 11.442/2007 e tem natureza comercial, razão por que não acarreta responsabilidade solidária ou subsidiária para o dono da carga, no caso, a 2ª reclamada. De se ressaltar que não há no ordenamento jurídico pátrio qualquer norma que obrigue as empresas a manterem o seu próprio serviçodetransportedas mercadorias que produzem ou comercializam, tampouco dos insumos ouequipamentosque adquirem, não se podendo falar em terceirização de serviços na hipótese.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('equipamentos de transporte', '2025-07-12 17:36:41', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:distrital:decreto:2020-10-16;41352', 'Decreto nº 41352, de 16 de outubro de 2020', 'urn:lex:br;distrito.federal:distrital:decreto:2020-10-16;41352', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Distrital', '2020-10-16', 'ATO NORMATIVO, revogação.TRANSPORTEDE PASSAGEIROS, procedimento. CUPOM FISCAL, emissão. PRESTAÇÃO DE SERVIÇOS. IMPOSTO SOBRE OPERAÇÕES RELATIVAS À CIRCULAÇÃO DE MERCADORIAS E SOBRE PRESTAÇÕES DE SERVIÇOSDETRANSPORTEINTERESTADUAL E INTERMUNICIPAL E DE COMUNICAÇÃO (ICMS), convênio.', 'Revoga o Decreto nº 36.420, de 25 de março de 2015, que estabelece procedimentos adicionais a serem observados pelas empresas prestadorasdetransportedepassageiros usuáriasdeequipamentoEmissor de Cupom Fiscal (ECF), nas prestações de serviçodetransporteintermunicipal, interestadual e internacional em razão do disposto no Convênio ICMS 84/2001.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
