INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('etanol', '2025-07-12 17:36:44', 'https://www.lexml.gov.br/urn/urn:lex:br:agencia.nacional.energia.eletrica:resolucao.autorizativa:2020-08-27;9149', 'RESOLUÇÃO AUTORIZATIVA nº 9149, de 27/08/2020', 'urn:lex:br:agencia.nacional.energia.eletrica:resolucao.autorizativa:2020-08-27;9149', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Agencia Nacional Energia Eletrica', '2020-08-27', 'Canápolis Açúcar eEtanolS.A. Autorização. Regularização. Implantação. Exploração. UTE Canápolis. {Autoprodução, Autogeração, Geração Própria}. {Coordenada geográfica, Posições geográficas}. Unidade geradora. Bagaço-de-cana. {Combustível, Carburante}. Comercialização de energia. Prazo determinado. Organograma. {Grupo econômico, Grupo de investidores}. Canápolis (MG)', 'Autoriza, para fins de regularização, a Canápolis Açúcar eEtanolS.A a implantar e explorar a Usina Termelétrica Canápolis, sob o regime de autoprodução de energia elétrica, no município de Canápolis, (MG).', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('etanol', '2025-07-12 17:36:44', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:lei:2014-06-18;13000', 'Lei nº 13.000, de 18 de Junho de 2014', 'urn:lex:br:federal:lei:2014-06-18;13000', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '2014-06-18', 'NORMAS ,  FUNDO DE COMPENSAÇÃO DE VARIAÇÕES SALARIAIS (FCVS) ,  REPRESENTAÇÃO JUDICIAL ,  REPRESENTAÇÃO EXTRA JUDICIAL ,  COMPETENCIA ,  CAIXA ECONOMICA FEDERAL (CEF) ,  AUTORIZAÇÃO ,  INTERVENÇÃO ,  PROCESSO ,  ADVOCACIA-GERAL DA UNIÃO (AGU) . AUTORIZAÇÃO ,  UNIÃO FEDERAL ,  CONCESSÃO ,  SUBVENÇÃO ,  NATUREZA ECONOMICA ,  DESTINAÇÃO ,  INDUSTRIA ,ETANOL,  REGIÃO NORDESTE . AUTORIZAÇÃO ,  UNIÃO FEDERAL ,  CONCESSÃO ,  SUBVENÇÃO ,  NATUREZA ECONOMICA ,  BANCO NACIONAL DE DESENVOLVIMENTO ECONOMICO E SOCIAL (BNDES) .', 'Altera as Leis nºs 12.096, de 24 de novembro de 2009, que autoriza a concessão de subvenção econômica sob a modalidade de equalização de taxas de juros pela União, e 12.409, de 25 de maio de 2011, que autoriza o Fundo de Compensação de Variações Salariais - FCVS a assumir direitos e obrigações do Seguro Habitacional do Sistema Financeiro da Habitação - SH/SFH; autoriza a União a conceder empréstimo ao Banco Nacional de Desenvolvimento Econômico e Social - BNDES; autoriza a União a conceder subvenção econômica às unidades produtoras deetanolna região Nordeste; e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('etanol', '2025-07-12 17:36:44', 'https://www.lexml.gov.br/urn/urn:lex:br:agencia.nacional.energia.eletrica:resolucao.autorizativa:2019-04-04;7711', 'RESOLUÇÃO AUTORIZATIVA nº 7711, de 04/04/2019', 'urn:lex:br:agencia.nacional.energia.eletrica:resolucao.autorizativa:2019-04-04;7711', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Agencia Nacional Energia Eletrica', '2019-04-04', 'Vale do Pontal Açúcar eEtanolLtda. LT Subestação Elevadora - Subestação São Simão. Declaração. Utilidade pública. Servidão administrativa. Área de Terra. Faixa de Passagem. Interligação. Subestação São Simão. Santa Vitória (MG). Limeira do Oeste (MG)', 'Declara de utilidade pública, para fins de instituição de servidão administrativa, em favor da Vale do Pontal Açúcar eEtanolLtda, a área de terra necessária à passagem da Linha de Transmissão Subestação Elevadora - Subestação São Simão, nos municípios de Limeira do Oeste e Santa Vitória, (MG).', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
