INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('eficiência energética', '2025-07-12 17:36:52', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:lei:2015-12-08;13203', 'Lei nº 13.203, de 8 de Dezembro de 2015', 'urn:lex:br:federal:lei:2015-12-08;13203', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '2015-12-08', 'ALTERAÇÃO ,  NORMAS ,  REVISÃO ,  ACORDO ,  RISCOS ,  HIDROLOGIA ,  PRODUÇÃO ,  ENERGIA HIDROELETRICA . ALTERAÇÃO ,  NORMAS ,  BONIFICAÇÃO ,  CONCESSÃO ,  PRODUÇÃO ,  TRANSMISSÃO ,  DISTRIBUIÇÃO ,  ENERGIA ELETRICA . ALTERAÇÃO ,  NORMAS ,  CONSELHO NACIONAL ,  POLITICAENERGETICA,  AMPLIAÇÃO ,  COMPETENCIA ,  DEFINIÇÃO ,  CRITERIOS ,  LICITAÇÃO ,  CONCESSÃO ,  PRODUÇÃO ,  TRANSMISSÃO ,  DISTRIBUIÇÃO ,  ENERGIA ELETRICA .', 'Dispõe sobre a repactuação do risco hidrológico de geração de energia elétrica; institui a bonificação pela outorga; e altera as Leis nºs 12.783, de 11 de janeiro de 2013, que dispõe sobre as concessões de energia elétrica, 9.427, de 26 de dezembro de 1996, que disciplina o regime das concessões de serviços públicos de energia elétrica, 9.478, de 6 de agosto de 1997, que institui o Conselho Nacional de PolíticaEnergética, 9.991, de 24 de julho de 2000, que dispõe sobre realização de investimentos em pesquisa e desenvolvimento e emeficiênciaenergéticapor parte das empresas concessionárias, permissionárias e autorizadas do setor de energia elétrica, 10.438, de 26 de abril de 2002, 10.848, de 15 de março de 2004, que dispõe sobre a comercialização de energia elétrica, e 11.488, de 15 de junho de 2007, que equipara a autoprodutor o consumidor que atenda a requisitos que especifica.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
