INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.4:acordao:2016-10-18;0001237-37.2015.5.08.0118', 'ACÓRDÃO TRT 8ª / 4ª T / RO    0001237-37.2015.5.08.0118', 'urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.4:acordao:2016-10-18;0001237-37.2015.5.08.0118', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 8', 'Tribunal Regional Trabalho', 'Acordao', '2016-10-18', NULL, 'EQUIPARAÇÃO SALARIAL. NÃO COMPROVAÇÃO. Percebe-se da instrução processual  que os motoristas dirigiam vários tipos de veículos, como automóveis, pick up, ônibus, caminhões etc, porém não restou provado que o reclamante dirigia, continuamente, acarreta. Ao contrário, a própria testemunha arrolada por ele declarou que viu o reclamante dirigircarretapor aproximadamente um mês e, após isso, o autor passou a dirigir ônibus e caçamba, demonstrando que ele não permaneceu na atividade de motorista decarretapelo restante do pacto laboral, como afirmou. Indeferido o pleito principal, improcedem os acessórios.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.militar;plenario:acordao:1999-04-15;320_1999010065313', 'Recurso em Sentido Estrito (FO) - 1999.01.006531-3/PR', 'urn:lex:br:superior.tribunal.militar;plenario:acordao:1999-04-15;320_1999010065313', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Militar', 'Acordao', '1999-04-15', 'PRAÇA MISSÃO MILITAR COLISÃO CAMINHÃO ÁRVORES ACOSTAMENTO. AUSÊNCIA CINTO
SEGURANÇA CARTEIRA HABILITAÇÃO INCOMPATÍVEL DIREÇÃOCARRETA. FATOS CONHECIMENTO
SUPERIOR HIERÁRQUICO AUSÊNCIA CONDUTA VIOLAÇÃO REGRA TRÂNSITO INEXISTÊNCIA DOLO
PERIGO VIDA OUTREM DENÚNCIA REJEIÇÃO MANUTENÇÃO DECISÃO.', 'DENÚNCIA. REJEIÇÃO.
Os fatos narrados na denúncia rejeirada não tem relação de causalidade com a
conduta do denunciado.
Rejeição mantida, ressalvando-se a possibilidade de oferecimento de nova
denúncia.
Decisão unanime.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2002-03-05;6199', 'PL 6199/2002', 'urn:lex:br:camara.deputados:projeto.lei;pl:2002-03-05;6199', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Camara Deputados', '2002-03-05', NULL, 'Estabelece o uso de pára-choques nos caminhões ecarretas.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;sao.paulo;mococa:municipal:decreto:1980-01-15;949', 'Decreto Municipal n° 949, de 15 de Janeiro de 1980', 'urn:lex:br;sao.paulo;mococa:municipal:decreto:1980-01-15;949', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '1980-01-15', NULL, 'FIXA LOCAIS DE ESTACIONAMENTO DE CAMINHÕES, CARROCINHAS ECARRETASDE ALUGUEL.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;sao.paulo:estadual:lei:1962-07-05;6825', 'Lei nº 6.825, de 05/07/1962', 'urn:lex:br;sao.paulo:estadual:lei:1962-07-05;6825', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '1962-07-05', 'TRIBUTOS  ,  IMPOSTO  ,  ISENÇÃO', 'Isenta de impostos ascarretasrebocadas por tratores, nas condições que especifica', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2004-02-04;01453-2003-044-03-00-2', 'Acórdão TRT 3ª / Oitava Turma / 2004-02-04', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2004-02-04;01453-2003-044-03-00-2', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2004-02-04', NULL, 'EMENTA:  MOTORISTA  DECARRETA.  CONTROLE DE  JORNADA  -  Quando
sujeito  ao efetivo controle por parte do empregador,  tanto  nos
pontos de saída e chegada como também ao longo de todo o trajeto,
o  motorista  decarretanão se encontra  inserido  na  hipótese
prevista no artigo 62, I, da CLT.  Condenação em horas extras que
se mantém.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2010-02-03;0051400-72.2008.5.03.0096', 'Acórdão TRT 3ª / Terceira Turma / 2010-02-03', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2010-02-03;0051400-72.2008.5.03.0096', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2010-02-03', NULL, 'EMENTA: MOTORISTA DECARRETA- TRABALHO EXTERNO - HORAS EXTRAS NÃO DEVIDAS. Via de regra, o motorista decarretaque realiza trabalho externo não faz jus a horas extras, salvo quando demonstrado o efetivo controle de sua jornada de trabalho pelo empregador, não se prestando a esse fim a utilização de rastreadores via satélite ou de tacógrafos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2012-04-24;0001717-78.2011.5.03.0058', 'Acórdão TRT 3ª / Nona Turma / 2012-04-24', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2012-04-24;0001717-78.2011.5.03.0058', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2012-04-24', NULL, 'EMENTA: HORAS EXTRAS. MOTORISTA DECARRETA. JORNADA EXTERNA. INEXIGIBILIDADE. Nos termos dos instrumentos normativos constantes dos autos, aplica-se aos trabalhadores exercentes de atividade externa, como motoristas decarretas, o dispositivo do art. 62, I, da CLT, pelo que são excluídos do controle de jornada e horário, e não fazem jus a horas extras.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2023-09-29;0010741-96.2022.5.03.0074', 'Acórdão PJe TRT 3ª / Segunda Turma / 2023-09-29', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2023-09-29;0010741-96.2022.5.03.0074', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2023-09-29', NULL, 'DANO EXTRAPATRIMONIAL. ACIDENTE DE TRÂNSITO. MOTORISTA DECARRETA. ATIVIDADE DE RISCO. RESPONSABILIDADE OBJETIVA. A atividade de motorista decarretase enquadra como atividade de risco, que enseja a responsabilidade objetiva da empregadora pelos danos extrapatrimoniais decorrentes do acidente de trânsito que vitima o empregado, nos termos do art. 927, parágrafo único, do Código Civil.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2018-07-30;0011624-89.2016.5.03.0062', 'Acórdão PJe TRT 3ª / Setima Turma / 2018-07-30', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2018-07-30;0011624-89.2016.5.03.0062', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2018-07-30', 'MOTORISTA - ADICIONAL DE PERICULOSIDADE', 'ADICIONAL DE PERICULOSIDADE. MOTORISTA.CARRETA. TANQUE SUPLEMENTAR. O veículo equipado com segundo tanque, cuja capacidade é de 300 litros, acentua o grau de risco e traduz situação equivalente ao transporte de inflamável previsto no item 16.6 na NR 16. O motorista que conduzcarretacom essas características faz jus ao adicional de periculosidade.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2019-02-14;0010583-71.2018.5.03.0077', 'Acórdão PJe TRT 3ª / Setima Turma / 2019-02-14', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2019-02-14;0010583-71.2018.5.03.0077', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2019-02-14', NULL, 'ADICIONAL DE PERICULOSIDADE. MOTORISTA.CARRETA. TANQUE SUPLEMENTAR. O veículo equipado por opcional de terceiro tanque com alta capacidade acentua o grau de risco e traduz situação equivalente ao transporte de inflamável previsto no item 16.6 na NR 16 da Portaria 3.214/78 do MTE. O motorista que conduzcarretacom essas características faz jus ao adicional de periculosidade.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2021-09-13;0010967-33.2020.5.03.0087', 'Acórdão PJe TRT 3ª / Setima Turma / 2021-09-13', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2021-09-13;0010967-33.2020.5.03.0087', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2021-09-13', NULL, 'ADICIONAL DE PERICULOSIDADE. MOTORISTA.CARRETA. TANQUE SUPLEMENTAR. O veículo equipado com tanque suplementar de alta capacidade acentua o grau de risco e traduz situação equivalente ao transporte de inflamável previsto no item 16.6 na NR 16 da Portaria 3.214/78 do MTE. O motorista que conduzcarretacom essas características faz jus ao adicional de periculosidade.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2022-05-11;0010904-98.2021.5.03.0078', 'Acórdão PJe TRT 3ª / Nona Turma / 2022-05-11', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2022-05-11;0010904-98.2021.5.03.0078', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2022-05-11', NULL, 'MOTORISTA DECARRETA. CONTROLE DE JORNADA. Nos termos do art. 2º, V, "b", da Lei n. 13.103/2015 c/c art. 74, § 3º, da CLT, configura obrigação patronal controlar a jornada de trabalho do motorista decarreta, mediante anotação em diário de bordo, papeleta ou ficha de trabalho externo, ou sistema e meios eletrônicos instalados nos veículos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('carreta', '2025-07-12 17:37:14', 'https://www.lexml.gov.br/urn/urn:lex:br:senado.federal:projeto.lei;pls:1995;224', '[ Projeto de Lei do Senado nº 224/1995 ]', 'urn:lex:br:senado.federal:projeto.lei;pls:1995;224', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Senado Federal', '1995-01-01', NULL, 'DISPÕE SOBRE O USO DE PARA-CHOQUES NOS CAMINHÕES ECARRETAS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
