INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('veículos autônomos', '2025-07-12 17:37:17', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.1:acordao:2011-03-02;0247900-75.2009.5.16.0012', 'ACORDÃO TRT 16ª / 1ª Turma / RO 0247900-75.2009.5.16.0012', 'urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.1:acordao:2011-03-02;0247900-75.2009.5.16.0012', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 16', 'Tribunal Regional Trabalho', 'Acordao', '2011-03-02', 'AUTÔNOMO,AUXILIAR,CONDUTOR,EMPREGO,INEXISTÊNCIA,LEI,RELAÇÃO,VEÍCULO', 'AUXILIAR DE CONDUTORAUTÔNOMODEVEÍCULO. LEI Nº 6.094/74. RELAÇÃO DE EMPREGO. INEXISTÊNCIA. Constatando-se que o reclamado, na qualidade de motorista-proprietário de um únicoveículode praça (van), dividia a jornada com o reclamante e considerando-se a prestação de serviços do obreiro sem qualquer subordinação, mas em regime de colaboração, entendo presentes os elementos tipificadores da hipótese prevista na legislação especial (Lei n. 6.094/74), não havendo como reconhecer o liame empregatício, nos moldes do art. 3º da CLT, como postulado. Recurso conhecido, mas não provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
