INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br:segundo.conselho.contribuintes;camara.1;turma.ordinaria:acordao:1991-02-20;201-66869,4818679', 'Acórdão nº 201-66869 do Processo 10467.001029/87-82', 'urn:lex:br:segundo.conselho.contribuintes;camara.1;turma.ordinaria:acordao:1991-02-20;201-66869,4818679', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Segundo Conselho Contribuintes', 'Acordao', '1991-02-20', NULL, 'IPI - Valordefretecobrado por transportadora interdependente, que o repassa ao estabelecimento industrial, integra a base de cálculo do tributo, no que excede ao valor-limite fixado na legislação vigente à época. Conta-corrente entre empresas ligadas não constitui evidência de mútuo. Contrato de mútuo com vício de falsidade, confessado, é inservível para o efeito de constituir prova. O valor dofrete, (bem como atabelado sindicato) não poderia exceder aos preços-limite fixados em norma própria para os produtos questionados. Recurso negado.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2011-11-16;2997', 'ACÓRDÃO TCU 2997/2011', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2011-11-16;2997', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2011-11-16', NULL, 'MONITORAMENTO DO CUMPRIMENTO DE DETERMINAÇÕES E RECOMENDAÇÕES EXPEDIDAS PELO TRIBUNAL. ARRECADAÇÃO DO ADICIONALDEFRETEPARA RENOVAÇÃO DA MARINHA MERCANTE. ATENDIMENTO PARCIAL. EDIÇÃO DE NORMAS PARA ARBITRAMENTO DO VALOR DOFRETE. DETERMINAÇÃO REDIRECIONADA PARA O DEPARTAMENTO ENCARREGADO. CRIAÇÃODETABELAPROGRESSIVA DE MULTAS POR INFRAÇÃO À LEGISLAÇÃO DO AFRMM. COMPETÊNCIA DO GESTOR PARA AFERIR A CONVENIÊNCIA E OPORTUNIDADE DE ADOÇÃO DA MEDIDA. DETERMINAÇÃO. COMUNICAÇÃO. APENSAMENTO.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.2:acordao:2011-12-07;0000555-82.2010.5.08.0013', 'ACÓRDÃO TRT 8ª / 2ª T / RO    0000555-82.2010.5.08.0013', 'urn:lex:br;justica.trabalho;regiao.8:tribunal.regional.trabalho;turma.2:acordao:2011-12-07;0000555-82.2010.5.08.0013', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 8', 'Tribunal Regional Trabalho', 'Acordao', '2011-12-07', NULL, 'MODO DE EXTINÇÃO DO CONTRATO DE EMPREGO. QUEBRA DE SIGILO DA EMPRESA, FALTA NÃO CARACTERIZADA.  Embora a tese central da reclamada, ora recorrente, para justificar a dispensa da reclamante, tenha sido a ;quebra de sigilo da empresa; ou violação de segredo da empresa. Segundo o arrazoado, houve uma cumulação com ato de improbidade e incontinência de conduta ou mau procedimento. Violar significa ofender com violência. E segredo de empresa, segundo o professor e jurista WAGNER D. GIGLIO, ;é tudo que, sendo referente a produção ou negócio e do conhecimento de poucos, não deve, pela vontade de seus detentores, ser violado;. Carta proposta com valoresdefrete, não é segredo de empresa, nem mesmo quando em processo de licitação. Aliás, é comum a troca de informações de preçodefrete, de passagem, de transporte de bagagem entre as empresas do ramo. Isso é um fato público e notório. As cotações são conhecidas de todos os interessados. Portanto, não há como se concluir que o fato alegado (revelação de valordefrete), mesmo que tenha sido praticado, possa importar em falta grave capaz de autorizar a dispensa de um empregado por justa causa. Rol de preços, cotação de preços,tabeladede preço de passagem,tabeladepreço de transporte, nada disso é considerado criação ou invenção da mente humana, logo, não significa segredo de fábrica, segredo industrial e nem mesmo comercial, quando muito, uma estratégia de concorrência, mas para ser válida precisa ser leal, transparente, porque se for feita às escondidas ai será deslealdade, portanto crime.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.1:acordao;resp:2005-04-05;725983-612266', 'REsp 725983 / PR', 'urn:lex:br:superior.tribunal.justica;turma.1:acordao;resp:2005-04-05;725983-612266', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2005-04-05', 'IMPOSSIBILIDADE, LEI ORDINÁRIA, INCLUSÃO, DESCONTO
INCONDICIONAL, VALOR,FRETE, BASE DE CÁLCULO, IPI, DECORRÊNCIA,
CÓDIGO TRIBUTÁRIO NACIONAL, RESTRIÇÃO, VALOR, OPERAÇÃO COMERCIAL,
MOMENTO, SAÍDA DE MERCADORIA, ESTABELECIMENTO INDUSTRIAL, OBJETIVO,
COMPOSIÇÃO, BASE DE CÁLCULO, TRIBUTO, NECESSIDADE, LEI ORDINÁRIA,
OBSERVÂNCIA, LIMITE, PREVISÃO, CÓDIGO TRIBUTÁRIO NACIONAL.
     (VOTO VENCIDO NA PRELIMINAR) (MIN. TEORI ALBINO ZAVASCKI)
     NÃO CONHECIMENTO, RECURSO ESPECIAL, DISCUSSÃO, EXISTÊNCIA,
HIERARQUIA, LEI COMPLEMENTAR, LEI ORDINÁRIA, DECORRÊNCIA,
CARACTERIZAÇÃO, MATÉRIA CONSTITUCIONAL, COMPETÊNCIA, STF.', 'TRIBUTÁRIO. IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS. DESCONTOS
INCONDICIONAIS/BONIFICAÇÃO. INCLUSÃO NA BASE DE CÁLCULO.
IMPOSSIBILIDADE. OFENSA AO ART. 47 DO CTN. PRECEDENTES.
1. A alteração do art. 14 da Lei nº 4.502/64 pelo art. 15 da Lei nº
7.798/89 para fazer incluir, na base de cálculo do IPI, o valor dofreterealizado por empresa coligada, não pode subsistir, tendo em
vista os ditames do art. 47 do CTN, o qual define como base de
cálculo o valor da operação de que decorre a saída da mercadoria,
devendo-se entender como ?valor da operação? o contrato de compra e
venda, no qual se estabelece o preço fixado pelas partes.
2. Com relação à exigência do IPI sobre descontos
incondicionais/bonificação, a jurisprudência do Superior Tribunal de
Justiça envereda no sentido de que:
- ?Consoante explicita o art. 47 do CTN, a base de cálculo do IPI é
o valor da operação consubstanciado no preço final da operação de
saída da mercadoria do estabelecimento. O Direito Tributário vale-se
dos conceitos privatísticos sem contudo afastá-los, por isso que o
valor da operação é o preço e, este, é o quantum final ajustado
consensualmente entre comprador e vendedor, que pode ser o resultado
databelacom seus descontos incondicionais. Revela contraditio in
terminis ostentar a Lei Complementar que a base de cálculo do
imposto é o valor da operação da qual decorre a saída da mercadoria
e a um só tempo fazer integrar ao preço os descontos incondicionais.
Ratio essendi dos precedentes quer quanto ao IPI, quer quanto ao
ICMS.? (REsp nº 477525/GO, Rel. Min. LUIZ FUX, DJ de 23/06/2003)
- ?A base de cálculo do Imposto sobre Circulação de Mercadorias e
Serviços - ICMS, é o valor da operação, o que é definido no momento
em que se concretiza a operação. O desconto incondicional não
integra a base de cálculo do aludido imposto.? (REsp nº 63838/BA,
Relª Minª NANCY ANDRIGHI, DJ de 05/06/2000)
3. Precedentes das 1ª e 2ª Turmas desta Corte Superior.
4. Recurso provido.
Decisão
Vistos, relatados e discutidos os autos em que são partes as acima
indicadas, acordam os Ministros da Primeira Turma do Superior
Tribunal de Justiça, por maioria, vencidos os Srs. Ministros Teori
Albino Zavascki e Denise Arruda, conhecer do recurso especial e, no
mérito, por unanimidade, dar-lhe provimento, nos termos do voto do
Sr. Ministro Relator. Votaram os Srs. Ministros José Delgado,
Francisco Falcão, Luiz Fux, Teori Albino Zavascki e Denise Arruda.
Sustentou oralmente o Dr. Ricardo Nussrala Haddad, pela recorrente.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.3:acordao:2000-03-20;125952', 'Acórdão nº 125952 do Processo nº19980110236198apc', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.3:acordao:2000-03-20;125952', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2000-03-20', 'DENEGAÇÃO, MANDADO DE SEGURANÇA PREVENTIVO, COMPENSAÇÃO DE CRÉDITO TRIBUTÁRIO, SUBSTITUIÇÃO TRIBUTÁRIA, VENDA, VEÍCULO AUTOMOTOR, VALOR INFERIOR, FATO GERADOR, INOCORRÊNCIA, ABUSO DE PODER, ATO ILÍCITO, DIREITO LÍQUIDO E CERTO.', 'TRIBUTÁRIO E CONSTITUCIONAL. MANDADO DE SEGURANÇA PREVENTIVO. ICMS. SUBSTITUIÇÃO TRIBUTÁRIA. VEÍCULOS AUTOMOTORES. VENDA POR PREÇO INFERIOR AO DO FATO GERADOR PRESUMIDO. COMPENSAÇÃO. AUSÊNCIA DE ATO EIVADO DE ILEGALIDADE OU ABUSO DE PODER E DE DIREITO LÍQUIDO E CERTO. UTILIZAÇÃO DA VIA MANDAMENTAL CONTRA LEI EM TESE. NÃO CABIMENTO. SÚMULA 266 DO STF.
1 - O INSTITUTO DA SUBSTITUIÇÃO TRIBUTÁRIA, PELO QUAL A LEI ATRIBUI A UM CONTRIBUINTE A RESPONSABILIDADE DE ANTECIPAR O RECOLHIMENTO DE UM TRIBUTO CUJO FATO GERADOR AINDA NÃO OCORREU, VISA A SIMPLIFICAÇÃO DO SISTEMA DE ARRECADAÇÃO, COM MAIOR EFICIÊNCIA E SEGURANÇA, SENDO QUE, POR PACÍFICA JURISPRUDÊNCIA, JÁ FOI CONSIDERADO QUE A EXIGÊNCIA ANTECIPADA, NO CASO DO ICMS DE VEÍCULOS AUTOMOTORES, NÃO SE REVESTE DE NENHUMA ILEGALIDADE OU ABUSIVIDADE. 2 - NÃO HÁ PREVISÃO LEGAL PARA A PRETENSÃO DA IMPETRANTE, DE COMPENSAÇÃO DE CRÉDITOS, JUNTO AO SUBSTITUTO TRIBUTÁRIO, QUANDO A VENDA DO VEÍCULO FOR REALIZADA POR VALOR MENOR AO DO FATO GERADOR PRESUMIDO (TABELADEFÁBRICA ACRESCIDA DO VALORDEFRETE), PELO CONTRÁRIO, SENDO QUE, NOS TERMOS DA CONVENÇÃO ICMS DE Nº 13/97, HÁ PREVISÃO EXPRESSA DE QUE NÃO É CABÍVEL A RESTITUIÇÃO OU COBRANÇA COMPLEMENTAR DO ICMS, QUANDO A OPERAÇÃO OU PRESTAÇÃO SUBSEQÜENTE À COBRANÇA DO IMPOSTO, SOB A MODALIDADE DA SUBSTITUIÇÃO TRIBUTÁRIA, SE REALIZAR COM VALOR INFERIOR OU SUPERIOR ÀQUELE ESTABELECIDO COM BASE NO ART. 8º DA LEI COMPLEMENTAR 87/96. DESSA FORMA, NÃO SE ENCONTRAM PRESENTES OS PRESSUPOSTOS AUTORIZADORES DA CONCESSÃO DA SEGURANÇA, QUAIS SEJAM, ATO ABUSIVO OU ILEGAL DA AUTORIDADE COATORA E DIREITO LÍQUIDO E CERTO DA IMPETRANTE. 3 - O PARÁGRAFO 7º DO ART. 150 DA C.F. É CLARO E TAXATIVO EM ESTIPULAR QUE, "CASO NÃO SE REALIZE O FATO GERADOR PRESUMIDO, É ASSEGURADA A IMEDIATA E PREFERENCIAL RESTITUIÇÃO DA QUANTIA PAGA" E, ASSIM, CONSIDERANDO QUE A FINALIDADE BÁSICA DO INSTITUTO DA SUBSTITUIÇÃO TRIBUTÁRIA É SIMPLIFICAR A ARRECADAÇÃO E FACILITAR A FISCALIZAÇÃO E, COM ISSO, DIFICULTAR A SONEGAÇÃO FISCAL, NA INTERPRETAÇÃO DE TAL NORMA CONSTITUCIONAL NÃO SE PODE UTILIZAR UMA INTERPRETAÇÃO EXTENSIVA COM O FIM DE ENGLOBAR A SITUAÇÃO APRESENTADA PELA IMPETRANTE, POIS O TEXTO CONSTITUCIONAL NÃO FALA EM QUANTIA PAGA A MAIOR OU MENOR, SIMPLESMENTE EM DEVOLUÇÃO DA QUANTIA PAGA, DO QUE SE DEPREENDE QUE A REFERIDA NORMA SOMENTE É APLICÁVEL ÀQUELES CASOS EM QUE NÃO SE EFETIVOU O FATO GERADOR DO ICMS, OU SEJA, NÃO HOUVE A CIRCULAÇÃO DA MERCADORIA. A CONTRARIO SENSU, CASO A VENDA DO BEM FOSSE ACIMA DO FATO GERADOR PRESUMIDO, TERIA O FISCO TAMBÉM O DIREITO DE EXIGIR A COMPLEMENTAÇÃO DO TRIBUTO. 4 - COMO A IMPETRANTE NÃO DEMONSTROU DE FORMA CLARA E INEQUÍVOCA SEU DIREITO LÍQUIDO E CERTO, UTILIZOU ELA DA VIA MANDAMENTAL CONTRA LEI EM TESE, O QUE NÃO É ADMITIDO, CONFORME SÚMULA 266 DO STF. APELAÇÃO NÃO PROVIDA. UNÂNIME.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2019-11-27;11953-2016-104-3-0', 'Acórdão do processo Nº AIRR - 11953-72.2016.5.03.0104', 'urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;airr:2019-11-27;11953-2016-104-3-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2019-11-27', NULL, 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. REMUNERAÇÃO. SALÁRIO EXTRA FOLHA. DIFERENÇAS DE RSR. A Corte a quo concluiu que o reclamante se desvencilhou do ônus de comprovar que recebia remuneração exclusivamente por meio de comissões, bem como salário extra folha. Constaram do acórdão recorrido os depoimentos das testemunhas Silas e Amos, os quais corroboraram a tese de que o percentual da comissão era de 12% sobre o valor databelafretede terceiro. Logo, diante do quadro fático descrito, a decisão regional não viola o art. 884 da CLT. Agravo de instrumento conhecido e não provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br:segundo.conselho.contribuintes;camara.2;turma.ordinaria:acordao:1991-12-11;202-04709,4835111', 'Acórdão nº 202-04709 do Processo 13738.000269/87-84', 'urn:lex:br:segundo.conselho.contribuintes;camara.2;turma.ordinaria:acordao:1991-12-11;202-04709,4835111', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Segundo Conselho Contribuintes', 'Acordao', '1991-12-11', NULL, 'IPI - VALOR TRIBUTRÁVEL - Quando a própria denúncia fiscal reconhece que as despesasdefretesão cobradas através de empresa transportadora interdependente da fabricante do cimento, com destaque na nota fiscal e conhecimento de transporte com obediência àstabelasdivulgadas pelos órgãos sindicais de transporte, é operação que não integra base tributável do Imposto sobre Produtos Industrializados-IPI (base legal: art. 63, & 1º, III do RIPI/82). Recurso provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.4:acordao:2001-06-28;142874', 'Acórdão nº 142874 do Processo nº19980110558798apc', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.4:acordao:2001-06-28;142874', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2001-06-28', 'IMPROCEDÊNCIA, COMPENSAÇÃO, ICMS, PAGAMENTO A MAIOR, PROVA, VENDA, VEÍCULO AUTOMOTOR, PREÇO MÍNIMO, INEXISTÊNCIA, PREVISÃO LEGAL, SUBSTITUIÇÃO, TRIBUTO.', 'DIREITO TRIBUTÁRIO - ICMS - FATO GERADOR - REGIME DE SUBSTITUIÇÃO TRIBUTÁRIA - RESTITUIÇÃO DO IMPOSTO EM FACE DE VENDA DE VEÍCULO POR PREÇO INFERIOR AO PRESUMIDO - IMPOSSIBILIDADE - HONORÁRIOS ADVOCATÍCIOS.
AS CONCESSIONÁRIAS DE VEÍCULOS, CONTRIBUINTES DO ICMS, SUJEITAM-SE AO REGIME DE SUBSTITUIÇÃO TRIBUTÁRIA. EM DECORRÊNCIA DESTE INSTITUTO, O ESTABELECIMENTO FORNECEDOR/FABRICANTE DOS VEÍCULOS RETÉM, POR ANTECIPAÇÃO, O ICMS RELATIVO À OPERAÇÃO SUBSEQÜENTE A SER REALIZADA PELA CONCESSIONÁRIA, QUANDO DE SUA REVENDA. A BASE DE CÁLCULO DO IMPOSTO, POR SUBSTITUIÇÃO, CONSISTE NOS VALORES CONSTANTES DASTABELASDEPREÇOS DE VENDA AO CONSUMIDOR, ELABORADAS PELAS EMPRESAS MONTADORAS/ IMPORTADORAS E FIXADAS COM BASE NO PREÇO MÉDIO ESTIMADO, PRATICADO NO MERCADO DE AUTOMÓVEIS, PARA CADA VEÍCULO, ACRESCIDODEFRETEE SEGURO.
A LEGISLAÇÃO APLICÁVEL À ESPÉCIE SOMENTE PERMITE RESTITUIÇÃO DO ICMS PARA O CONTRIBUINTE SUJEITO AO REGIME DE SUBSTITUIÇÃO TRIBUTÁRIA NO CASO DE NÃO REALIZAÇÃO DO FATO GERADOR PRESUMIDO. NÃO HÁ QUE SE FALAR EM COMPENSAÇÃO DE VALORES EM FACE DE RECOLHIMENTO A MAIOR, MÁXIME SE NÃO COMPROVADA A VENDA DE VEÍCULOS POR PREÇO INFERIOR AO PRESUMIDO.
REDUZ-SE O VALOR DOS HONORÁRIOS ADVOCATÍCIOS SE DESCONFORME COM OS PARÂMETROS LEGAIS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('tabela de frete', '2025-07-12 17:37:23', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:medida.provisoria:1997-06-13;1508-18', 'Medida Provisória nº 1.508-18, de 13 de Junho de 1997', 'urn:lex:br:federal:medida.provisoria:1997-06-13;1508-18', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '1997-06-13', 'ALTERAÇÃO ,  NORMAS ,  BASE DE CALCULO ,  CONTRIBUIÇÃO ,  PROGRAMA DE INTEGRAÇÃO SOCIAL E PROGRAMA DE FORMAÇÃO DO PATRIMONIO DO SERVIDOR PUBLICO (PIS-PASEP) ,  CONTRIBUIÇÃO PARA FINANCIAMENTO DA SEGURIDADE SOCIAL (COFINS) ,  VALOR ,  RECEITA ,  EMPRESA NACIONAL ,  ESTALEIRO ,  NAVEGAÇÃO ,  ATIVIDADE ,  CONSTRUÇÃO ,  CONSERVAÇÃO ,  EMBARCAÇÃO ,  REQUISITOS ,  REGISTRO ,  REGISTRO ESPECIAL ,  BRASILEIROS ,  NORMAS ,  ISENÇÃO ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  ORGÃOS ,  SEGURANÇA PUBLICA ,  UNIÃO FEDERAL ,  ESTADOS ,  DISTRITO FEDERAL (DF) ,  MUNICIPIOS ,  HIPOTESE ,  AQUISIÇÃO ,  EQUIPAMENTOS ,  RADIO ,  TRANSMISSÃO ,  TELEFONIA ,  TELEGRAFIA ,  VEICULO AUTOMOTOR ,  OBJETIVO ,  PATRULHA ,  ARMA DE FOGO ,  MUNIÇÃO . CRITERIOS ,  EXCLUSÃO ,  BASE DE CALCULO ,  INCIDENCIA ,  TRIBUTOS ,FRETE,  TRANSPORTE AQUATICO ,  IMPORTAÇÃO ,  EXPORTAÇÃO ,  MERCADORIA ,  FINANCIAMENTO ,  CONDICIONAMENTO ,  REGISTRO ESPECIAL ,  EMBARCAÇÃO NACIONAL . RATIFICAÇÃO ,  ATO NORMATIVO . EXCLUSÃO ,  INCIDENCIA ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  CORRELAÇÃO ,  INDUSTRIALIZAÇÃO ,  MISTURA ,  PIGMENTO ,  TINTA ,  DESTINAÇÃO ,  CONSUMIDOR ,  RELAÇÃO ,  COMERCIO VAREJISTA . AMPLIAÇÃO ,  PRAZO ,  MICROEMPRESA ,  PEQUENA EMPRESA ,  RECOLHIMENTO ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) . CONCESSÃO ,  ISENÇÃO FISCAL ,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  CORRELAÇÃO ,  EQU