INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('resolução', '2025-07-12 17:37:26', 'https://www.lexml.gov.br/urn/urn:lex:br:agencia.nacional.energia.eletrica:resolucao:2003-04-24;219', 'RESOLUÇÃOnº 219, de 24/04/2003', 'urn:lex:br:agencia.nacional.energia.eletrica:resolucao:2003-04-24;219', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Agencia Nacional Energia Eletrica', '2003-04-24', '{Alteração, Modificação}. Redação. {Artigo, Artigos}.Resolução. Fixação. {Requisito, Condições}. Contratação. Acesso. {Utilização, Uso}. {Conexão, Vão de Saída}. Sistema de Transmissão. Sistema de Distribuição. Energia Elétrica | {Alteração, Modificação}. Redação. {Artigo, Artigos}.Resolução. Fixação. {Requisito, Condições}. Contratação. Acesso. {Utilização, Uso}. {Conexão, Vão de Saída}. Sistema de Transmissão. Sistema de Distribuição. Energia Elétrica', 'Dá nova redação ao art. 22 daResoluçãoANEEL 281 de 01.10.1999, que estabelece as condições gerais de contratação do acesso, compreendendo o uso e a conexão dos sistemas de transmissão e distribuição de energia elétrica, com prazo para republicação integral e atualizada daResolução.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
