INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('veículos pesados', '2025-07-12 17:37:34', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.recursal.juizados.especiais.civeis.criminais.df.2:acordao:2010-09-28;459047', 'Acórdão nº 459047 do Processo nº20101210022994acj', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.recursal.juizados.especiais.civeis.criminais.df.2:acordao:2010-09-28;459047', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2010-09-28', 'PROCEDÊNCIA, REDUÇÃO, INDENIZAÇÃO, DANO MATERIAL, ABALROAMENTO,VEÍCULOAUTOMOTOR, CONTEXTO PROBATÓRIO, COMPROVAÇÃO, CULPA CONCORRENTE, MOTORISTA, CARACTERIZAÇÃO, DIVISÃO, PREJUÍZO. IMPROCEDÊNCIA, REPARAÇÃO DE DANOS, DANO MORAL, INOBSERVÂNCIA, VIOLAÇÃO, DIREITO DA PERSONALIDADE. 

VOTO VENCIDO: CONFIRMAÇÃO, INDENIZAÇÃO, DANO MORAL, OBSERVÂNCIA, VIOLAÇÃO, DIREITO DA PERSONALIDADE.', 'CIVIL. COLISÃO DEVEÍCULOEM MOVIMENTO EM POSTE SUSPENSO SOBREVEÍCULOPESADO(CAMINHÃO). CONJUNTO PROBATÓRIO QUE INDICA CULPA CONCORRENTE. BRINCADEIRAS E GALHOFAS DE PREPOSTOS DA PARTE QUE NÃO CONFIGURAM VIOLAÇÃO DE DIREITOS DA PERSONALIDADE. RECURSO CONHECIDO E PARCIALMENTE PROVIDO. 1. AGE COM CULPA A EMPRESA QUE NÃO ADOTA MEDIDAS DE SEGURANÇA ADEQUADAS À EXECUÇÃO DE SERVIÇO DE INSTALAÇÃO DE POSTES EM PISTA MOVIMENTADA, E O CONDUTOR QUE EMPREENDE MOVIMENTO NO SEUVEÍCULOEM CIRCUNSTÂNCIA TAL QUE VEM A COLIDIR COM POSTE PENDURADO SOBRE CAMINHÃO, EM POSIÇÃO DE REPOUSO. 2. A CULPA CONCORRENTE, DETERMINADA EM PROPORÇÃO IGUAL PARA AMBAS AS PARTES, INDUZ A REPARTIÇÃO DA RESPONSABILIDADE EM METADE PARA CADA QUAL. 3. DE BRINCADEIRAS E GALHOFAS NÃO SE EXTRAI NECESSÁRIA VIOLAÇÃO A ATRIBUTOS DA PERSONALIDADE, DE ORDEM A ENSEJAR INDENIZAÇÃO POR DANOS MORAIS, AINDA QUANDO RELATIVOS À CULPA DA PARTE EM ACIDENTE QUE ACABA DE ACONTECER E SE REFIRAM, AS BRINCADEIRAS, A QUESTÃO DE GÊNERO. 4. RECURSO CONHECIDO E PARCIALMENTE PROVIDO, PARA AFASTAR A INDENIZAÇÃO POR DANOS MORAIS E PARA REDUZIR A CONDENAÇÃO DA REQUERIDA À METADE DO VALOR DAS AVARIAS ORÇADAS. 5. SEM CUSTAS E SEM HONORÁRIOS, PORQUE VENCEDOR O APELANTE.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('veículos pesados', '2025-07-12 17:37:34', 'https://www.lexml.gov.br/urn/urn:lex:br;rio.grande.sul;capao.canoa:municipal:lei:2019-12-06;3468', 'Lei Municipal nº 3.468, de 06 de dezembro de 2019', 'urn:lex:br;rio.grande.sul;capao.canoa:municipal:lei:2019-12-06;3468', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2019-12-06', NULL, 'Altera  o  Padrão  de Vencimento do Cargo de Motorista deVeículosLeves e Motorista deVeículosPesados, previsto na Lei nº 3.392, de 24 de maio de 2019.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
