INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.4:acordao:2006-11-13;266616', 'Acórdão nº 266616 do Processo nº20040110479525apc', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.4:acordao:2006-11-13;266616', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2006-11-13', 'SUCESSIVO AO 160743.', 'CIVIL E PROCESSUAL CIVIL. ACIDENTE DE TRÂNSITO.  FALHA NO SISTEMA ELÉTRICO. SINALIZAÇÃO DA RODOVIA.  AUSÊNCIA DE CASO FORTUITO OU DE FORÇA MAIOR. LEGITIMIDADE DA EMPRESA ATUANTE NO TRANSPORTE DE CARGAS E PROPRIETÁRIA DO VEÍCULOSEMI-REBOQUE. RESPONSABILIDADE SOLIDÁRIA DOS PROPRIETÁRIOS DA CARRETA E CAVALO MECÂNICO. CULPA DA VÍTIMA AFASTADA. DANOS MORAIS. INEXISTÊNCIA.
1.  NA AÇÃO DE INDENIZAÇÃO DE DANOS ORIUNDOS DE ACIDENTE DE TRÂNSITO, A EMPRESA ATUANTE NO RAMO DE TRANSPORTE DE CARGAS E PROPRIETÁRIA DO VEÍCULO ENVOLVIDO NA COLISÃO (SEMI-REBOQUE), ESTÁ LEGITIMADA A FIGURAR COMO RÉ EM VISTA DO RISCO DA ATIVIDADE ECONÔMICA, CONSOANTE REGRA DO ARTIGO 927, PARÁGRAFO ÚNICO DO CÓDIGO CIVIL.
2. SENDO OBJETIVA A RESPONSABILIDADE DA EMPRESA PROPRIETÁRIA DO VEÍCULO ENVOLVIDO NO ACIDENTE, IRRELEVANTE PERQUIRIR SOBRE A CULPA DE SEUS PREPOSTOS. AO COLOCAR EM CIRCULAÇÃO OSEMI-REBOQUE, MEDIANTE O AVENTADO COMODATO,  A PROPRIETÁRIA CRIOU UM RISCO, QUE ENSEJA O DEVER DE INDENIZAR.
3. INEXISTINDO PROVA CONTUNDENTE DA AVENTADA EMBRIAGUEZ DA VÍTIMA OU MESMO DE ESTAR DESENVOLVENDO VELOCIDADE EXCESSIVA, HÁ QUE SE AFASTAR QUALQUER CULPA DESTA.
5. O DEFEITO MECÂNICO EXPERIMENTADO PELO CAMINHÃO, FAZENDO-O PERMANECER EM REPOUSO NA FAIXA DE ROLAMENTO, SEM SINALIZAÇÃO,  JUSTIFICA A CULPA  DOS RÉUS, POIS, DE FATO, A HIPÓTESE NÃO SE ENQUADRA EM CASO FORTUITO. AO CONTRÁRIO, INDUZ CUIDAR-SE DE FALTA DE MANUTENÇÃO ADEQUADA.
6. A INDENIZAÇÃO POR DANOS MORAIS RECLAMA EFETIVA PROVA DA OCORRÊNCIA DE FATO QUE, DE REGRA, CONDUZA A ABORRECIMENTOS RELEVANTES, PASSÍVEIS DE RESSARCIMENTO. CUIDANDO-SE DE ACIDENTE DE TRÂNSITO, FAZ-SE NECESSÁRIA A POSITIVAÇÃO DE QUE, DO EVENTO, TENHAM ORIGINADO CONSEQÜÊNCIAS GRAVES E ANORMAIS. MEROS ABORRECIMENTOS, EM SUMA,  NÃO JUSTIFICAM A PRETENSÃO.
7. RECURSOS CONHECIDOS E PARCIALMENTE PROVIDO O DO AUTOR.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2009-12-14;0100900-79.2007.5.03.0149', 'Acórdão TRT 3ª / Terceira Turma / 2009-12-14', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2009-12-14;0100900-79.2007.5.03.0149', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2009-12-14', NULL, 'EMENTA: VEÍCULO AUTOMOTOR. REGISTRO. OBRIGATORIEDADE. COMPROVAÇÃO DA PROPRIEDADE. A teor do art. 120 do Código de Trânsito Brasileiro, "[t]odo veículo automotor, elétrico, articulado,reboqueousemi-reboque, deve ser registrado perante o órgão executivo de trânsito do Estado ou do Distrito Federal, no Município de domicílio ou residência de seu proprietário, na forma da lei." Sendo assim, constatando-se que os documentos originários do DETRAN dão conta de que os automóveis indicados à penhora ainda estão registrados em nome do executado, conclui-se que ele ainda seja o seu legítimo proprietário.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:terceiro.conselho.contribuintes;camara.3;turma.ordinaria:acordao:1995-04-25;303-28182,4818003', 'Acórdão nº 303-28182 do Processo 10314.000285/93-35', 'urn:lex:br:terceiro.conselho.contribuintes;camara.3;turma.ordinaria:acordao:1995-04-25;303-28182,4818003', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Terceiro Conselho Contribuintes', 'Acordao', '1995-04-25', NULL, 'Rodas de alumínio forjado para caminhões. Estando a alíquota do
imposto de importação de mercadoria de que se trata reduzida a zero
pela Portaria MF nº 10/93, incabível a exigência do imposto, ainda que
as mesmas possam ser utilizadas, também, em ônibus esemi-reboques.
Recurso provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:primeiro.conselho.contribuintes;camara.6;turma.ordinaria:acordao:1999-10-19;106-11001,4688542', 'Acórdão nº 106-11001 do Processo 10935.003031/96-22', 'urn:lex:br:primeiro.conselho.contribuintes;camara.6;turma.ordinaria:acordao:1999-10-19;106-11001,4688542', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Primeiro Conselho Contribuintes', 'Acordao', '1999-10-19', NULL, 'ATIVIDADE RURAL - EX. 1991 - VEÍCULOS ESEMI-REBOQUES- VINCULAÇÃO – IN/SRF 138/90. Formulando o contribuinte no exercício de 1992 a opção de dedução do custo de aquisição de bens e benfeitorias constantes da declaração do ano-base de 1989, consoante IN/SRF n. 138/90, eventual equívoco há que ser sanado mediante pleito retificatório no exercício de opção.  Deste modo, não se faz possível pleitear a redução correspondente ao custo dos bens omitidos no exercício fiscalizado, por ser diverso daquele de opção.

Recurso negado.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2003-09-01;181756', 'Acórdão nº 181756 do Processo nº20000710122483apc', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2003-09-01;181756', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2003-09-01', 'PROCEDÊNCIA, REDUÇÃO, INDENIZAÇÃO, DANO MATERIAL, DOIS TERÇOS, VENCIMENTOS, DE CUJUS, ACIDENTE DE TRÂNSITO, PENSÃO, OBSERVÂNCIA, DESCONTO, DESPESA, PARTICULAR, PRINCÍPIO DA RAZOABILIDADE.', 'PROCESSO CIVIL E CIVIL. RESPONSABILIDADE CIVIL. VIOLAÇÃO AOS PRINCÍPIOS DO CONTRADITÓRIO E DA AMPLA DEFESA AFASTADA. DANOS MORAIS E MATERIAIS. ACIDENTE DE VEÍCULO. LEGITIMIDADE PASSIVA DA EMPRESA PROPRIETÁRIA DOSEMI-REBOQUEQUE ATINGIU A VÍTIMA. REDUÇÃO DO MONTANTE FIXADO A TÍTULO DE INENIZAÇÃO POR DANOS MATERIAIS. MANUTENÇÃO DO QUANTUM RELATIVO AOS DANOS MORAIS. APELO PROVIDO PARCIALMENTE.
NÃO HÁ QUE SE FALAR EM NULIDADE DO PROCESSO A PARTIR DA PRODUÇÃO DO LAUDO PERICIAL, AINDA QUE ELABORADO SEM A INTERVENÇÃO DAS PARTES, VEZ QUE CONSTITUI EXAME PROMOVIDO NO CURSO DE INQUÉRITO DESTINADO A APURAR AS CIRCUNSTÂNCIAS DO ACIDENTE DEDUZIDO NOS AUTOS, O QUAL NÃO SE CONFUNDE COM A PERÍCIA CONTEMPLADA PELO CÓDIGO DE PROCESSO CIVIL, CUJA PRODUÇÃO ADMITE A INTERVENÇÃO DE ASSISTENTE TÉCNICO NOMEADO PELOS LITIGANTES.
INOCORRENTE O CERCEAMENTO DO DIREITO DE DEFESA DA APELANTE, VEZ QUE, INSTADA A ESPECIFICAR AS PROVAS QUE PRETENDIA PRODUZIR, DEIXOU TRANSCORRER IN ALBIS O PRAZO FIXADO.
PATENTE A LEGITIMIDADE PASSIVA DA EMPRESA PROPRIETÁRIA DOSEMI-REBOQUEACOPLADO AO "CAVALO TRATOR" QUE ATINGIU A VÍTIMA, VEZ QUE, NA DINÂMICA DO ACIDENTE, O VEÍCULO COMPOSTO POR UNIDADES PERTENCENTES À EMPRESAS DIVERSAS TORNA-SE UM TODO, OCASIONANDO A SOLIDARIEDADE DOS PROPRIETÁRIOS. 
PRESENTES OS ELEMENTOS INDISPENSÁVEIS PARA ENSEJAR O RESSARCIMENTO PRETENDIDO PELA APELADA, TENDO EM VISTA O FALECIMENTO DE SEU ESPOSO EM RAZÃO DE TRAUMATISMO CRÂNIO ENCEFÁLICO CAUSADO PELO ABALROAMENTO DO VEÍCULO QUE CONDUZIA POR CAMINHÃO DE PROPRIEDADE DAS RÉS, HÁ QUE SE ARBITRAR A INDENIZAÇÃO POR DANOS MATERIAIS EM DOIS TERÇOS DOS RENDIMENTOS AUFERIDOS PELA VÍTIMA, DESDE O EVENTO LESIVO ATÉ OS SETENTA ANOS DE IDADE, ACRESCIDO DO VALOR RELATIVO À PERDA DO AUTOMÓVEL E DAS DESPESAS COM FUNERAL.
CONSIDERANDO-SE A NATUREZA COMPENSATÓRIA E PENALIZANTE DA INDENIZAÇÃO POR DANOS MORAIS, ALIADA À CAPACIDADE ECONÔMICA DAS PARTES, BEM COMO À INTENSIDADE DO DANO IMPUTADO À APELADA, ENTENDO JUSTO O VALOR ARBITRADO PELA R. SENTENÇA A TÍTULO DE INDENIZAÇÃO POR DANOS MORAIS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:conselho.administrativo.recursos.fiscais;secao.julgamento.3;camara.4;turma.ordinaria.1:acordao:2018-07-26;3401-005.210,7413696', 'Acórdão nº 3401-005.210 do Processo 10736.000002/2011-19', 'urn:lex:br:conselho.administrativo.recursos.fiscais;secao.julgamento.3;camara.4;turma.ordinaria.1:acordao:2018-07-26;3401-005.210,7413696', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Conselho Administrativo Recursos Fiscais', 'Acordao', '2018-07-26', NULL, 'Assunto: Classificação de Mercadorias
Período de apuração: 20/02/2009 a 22/10/2010
REVISÃO ADUANEIRA. INEXISTÊNCIA DE MUDANÇA DE CRITÉRIO JURÍDICO.
Revisão aduaneira consiste em reexame do despacho de importação e não de lançamento, o qual somente se perfaz com a homologação expressa ou tácita, sendo, por isso, incabível a argüição de mudança de critério jurídico.
CLASSIFICAÇÃO FISCAL DE MERCADORIA.
O conjunto composto desemi-reboque, torre de iluminação e grupo eletrogêneo, classifica-se de acordo com a função principal do conjunto que é a iluminação. Correta a NCM 9405.40.10.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2013-09-11;712275', 'Acórdão nº 712275 do Processo nº20090111617437apc', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.2:acordao:2013-09-11;712275', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2013-09-11', 'PROCEDÊNCIA, INDENIZAÇÃO, DANO MORAL, MORTE, REUNIÃO, ÁREA PÚBLICA, PARTIDO POLÍTICO, FALTA, CUIDADO, INSTALAÇÃO, EQUIPAMENTO, OCORRÊNCIA, ACIDENTE, INEXISTÊNCIA, CASO FORTUITO, FORÇA MAIOR, COMPROVAÇÃO, NEXO DE CAUSALIDADE, DANO, NEGLIGÊNCIA, RESPONSABILIDADE SOLIDÁRIA, OMISSÃO, DISTRITO FEDERAL,  RESPONSABILIDADE SUBJETIVA DO ESTADO, FIXAÇÃO, VALOR, OBSERVÂNCIA, PRINCÍPIO DA RAZOABILIDADE, PROPORCIONALIDADE. IMPROCEDÊNCIA, PENSÃO VITALÍCIA, INEXISTÊNCIA, DEPENDÊNCIA ECONÔMICA,  COMPANHEIRA, DE CUJUS.', 'PROCESSO CIVIL. RESPONSABILIDADE CIVIL. ACIDENTE OCORRIDO EM SHOWMÍCIO. MORTE POR ESMAGAMENTO DE CRÂNIO. DANO MORAL. CRITÉRIOS PARA A FIXAÇÃO DO QUANTUM.
DEVIDAMENTE CARACTERIZADA A RESPONSABILIDADE DOS RÉUS  QUE, AO PROMOVEREM GRANDE EVENTO DEIXARAM DE PROCEDER À FISCALIZAÇÃO APTA À SEGURANÇA DAS PESSOAS QUE PRESTIGIARAM O SHOWMÍCIO, AGINDO DE FORMA TOTALMENTE NEGLIGENTE, INQUESTIONÁVEL A CULPA PELA MORTE DE UM DOS ESPECTADORES POR ESMAGAMENTO DE CRÂNIO PORSEMI-REBOQUEQUE SE ENCONTRAVA ESTACIONADO DE FORMA IRREGULAR.
A DOUTRINA E A JURISPRUDÊNCIA TÊM CONSAGRADO A DUPLA FUNÇÃO NA COMPENSAÇÃO PECUNIÁRIA DO DANO MORAL: COMPENSATÓRIA E PENALIZANTE, VALENDO RESSALTAR QUE O VALOR ARBITRADO DEVE GUARDAR PERTINÊNCIA COM A FORÇA ECONÔMICO-FINANCEIRA DAS PARTES E A INTENSIDADE DO DANO SOFRIDO.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2018-05-22;1571571-1727452', 'AgInt no REsp 1571571 / MG', 'urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2018-05-22;1571571-1727452', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2018-05-22', NULL, 'AGRAVO  INTERNO NO RECURSO ESPECIAL. DIREITO CIVIL. RESPONSABILIDADE
CIVIL.   ACIDENTE  DE  TRÂNSITO  CAUSADO  PELO  CONDUTOR  DO  CAVALO
MECÂNICO.  RESPONSABILIDADE SOLIDÁRIA DO CONTRATANTE PROPRIETÁRIO DOSEMI-REBOQUE.  LEGITIMIDADE  PASSIVA.  PRECEDENTES  DO  STJ. DECISÃO
AGRAVADA MANTIDA. AGRAVO INTERNO DESPROVIDO.
Decisão
Vistos e relatados estes autos em que são partes as acima indicadas,
decide a Egrégia TERCEIRA TURMA do Superior Tribunal de Justiça, por
unanimidade,  negar  provimento ao agravo, nos termos do voto do Sr.
Ministro Relator. Os Srs. Ministros Ricardo Villas Bôas Cueva, Marco
Aurélio  Bellizze  (Presidente),  Moura  Ribeiro  e  Nancy  Andrighi
votaram com o Sr. Ministro Relator.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.1:acordao:2006-01-12;239663', 'Acórdão nº 239663 do Processo nº19990610029435apr', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.criminal.1:acordao:2006-01-12;239663', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2006-01-12', 'VIDE EMENTA.', 'CRIMINAL - HOMICÍDIO CULPOSO - ABSOLVIÇÃO - RECURSO DO MINISTÉRIO PÚBLICO- ALEGAÇÃO DE IMPRUDÊNCIA E NEGLIGÊNCIA - TRANSPORTE DE PASSAGEIROS NA PLATAFORMA EXTERNA DO CAMINHÃO - FIXAÇÃO DA PENA - EXTINÇÃO DA PUNIBILIDADE PELA PRESCRIÇÃO.
1.O RÉU, AO PERMITIR QUE A VÍTIMA FOSSE TRANSPORTADA DO LADO DE FORA DA BOLEIA DO CAMINHÃO, ENTRE A CABINE E OSEMI-REBOQUE, INCORREU EM CULPA, QUE SE MANIFESTA NA MODALIDADE DA IMPRUDÊNCIA, QUE É SEMPRE NORMATIVA, JÁ QUE DECORRE DE UM JUÍZO AXIOLÓGICO, DE UMA VALORAÇÃO DAS CIRCUNSTÂNCIAS EM QUE O FATO OCORREU. NO CASO ESPECÍFICO DOS AUTOS, O MOTORISTA, AO ADMITIR QUE A VÍTIMA FOSSE TRANSPORTADA EM SITUAÇÃO DE ALGUM RISCO, DEU CAUSA A RESULTADO PREVISÍVEL.
2.FIXADA A PENA PRIVATIVA DE LIBERDADE EM 2 (DOIS) ANOS DE DETENÇÃO EM REGIME INICIAL ABERTO E TENDO TRANSCORRIDO A PRESCRIÇÃO RETROATIVA, DECLARA-SE EXTINTA A PUNIBILIDADE.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2015-10-06;1521006-1475201', 'AgRg no REsp 1521006 / SP', 'urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2015-10-06;1521006-1475201', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2015-10-06', NULL, 'AGRAVO REGIMENTAL. AGRAVO NO RECURSO ESPECIAL. RESPONSABILIDADE
CIVIL. ACIDENTE DE TRÂNSITO.SEMI-REBOQUE. PROPRIETÁRIO.
LEGITIMIDADE PASSIVA.
1. O proprietário do veículo responde solidariamente pelos danos
decorrentes de acidente de trânsito causado por culpa do condutor,
pouco importando que ele não seja seu empregado ou preposto, ou que
o transporte seja oneroso ou gratuito.
2. Não apresentação pela parte agravante de argumentos novos capazes
de infirmar os fundamentos que alicerçaram a decisão agravada.
3. AGRAVO REGIMENTAL DESPROVIDO.
Decisão
Vistos e relatados estes autos em que são partes as acima indicadas,
decide a Egrégia TERCEIRA TURMA do Superior Tribunal de Justiça, por
unanimidade, negar  provimento ao agravo regimental, nos termos do
voto do Sr. Ministro Relator. Os Srs. Ministros Ricardo Villas Bôas
Cueva (Presidente), Marco Aurélio Bellizze, Moura Ribeiro e João
Otávio de Noronha votaram com o Sr. Ministro Relator.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.5:acordao:2012-12-13;642529', 'Acórdão nº 642529 do Processo nº20120020195473agi', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.5:acordao:2012-12-13;642529', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2012-12-13', NULL, 'DIREITO CIVIL E PROCESSUAL CIVIL. AÇÃO DE RESCISÂO DE CONTRATO C/C DECLARATÓRIA DE INEXISTÊNCIA DE DÍVIDA, DEVOLUÇÂO DE PARCELAS ANTECIPADAS, PERDAS E DANOS, LUCROS CESSANTES E DANOS MORAIS. ALEGAÇÂO DE ATRASO NA ENTREGA DE IMPLEMENTO MECÂNICO (SEMI-REBOQUE). PRETENSÂO À ANTECIPAÇÃO DA TUTELA. INDEFERIMENTO. AUSÊNCIA DOS REQUISITOS. DECISÃO MANTIDA.
1. AGRAVO DE INSTRUMENTO CONTRA A DECISÃO QUE, EM AÇÃO DE RESCISÃO DE CONTRATO, INDEFERIU O PEDIDO DE ANTECIPAÇÃO DA TUTELA SOB O ARGUMENTO DE QUE OS DOCUMENTOS QUE INSTRUEM A INICIAL NÃO SÃO SUFICIENTES PARA ELUCIDAR A QUESTÃO SOB ANÁLISE. 
2. A ANTECIPAÇÃO DE TUTELA, PROVIDÊNCIA CAUTELAR INTRODUZIDA POR FORÇA DA NOVA REDAÇÃO CONFERIDA AO ARTIGO 273, DO CPC, EXIGE PROVA INEQUÍVOCA DE VEROSSIMILHANÇA, SOMADA AO RECEIO DE DANO IRREPARÁVEL OU AO ABUSO DE DIREITO DE DEFESA MANIFESTADO PELO RÉU EM CARÁTER PROTELATÓRIO. 
3. AS RAZÕES EXTERNADAS NA DECISÃO AGRAVADA, AO MENOS NESSA SEDE RECURSAL, DEVEM SER PRESERVADAS, POIS, A PRETENSÃO DA AGRAVANTE DEMANDA NECESSARIAMENTE A RESCISÃO DO CONTRATO FIRMADO ENTRE AS PARTES E A RESTITUIÇÃO DE TODO O MONTANTE PAGO. 3.1. ASSIM, A CONSTATAÇÃO DA VERACIDADE DAS ALEGAÇÕES DA RECORRENTE DEPENDE DE MAIOR APROFUNDAMENTO COGNITIVO, O QUE NÃO SE MOSTRA POSSÍVEL NESTE MOMENTO PROCESSUAL.
4. RECURSO IMPROVIDO.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.4:acordao;aresp:2020-02-20;1574249-1926417', 'AgInt no AREsp 1574249 / PR', 'urn:lex:br:superior.tribunal.justica;turma.4:acordao;aresp:2020-02-20;1574249-1926417', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Aresp', '2020-02-20', NULL, 'AGRAVO INTERNO NO AGRAVO EM RECURSO ESPECIAL. PROCESSUAL CIVIL. AÇÃO
DE RESCISÃO CONTRATUAL CUMULADA COM PEDIDO DE REINTEGRAÇÃO DE POSSE
E INDENIZAÇÃO DOS DANOS MATERIAIS. NEXO CAUSAL. AUSÊNCIA DE
FUNDAMENTAÇÃO. AGRAVO INTERNO PROVIDO.
1. In casu, a Corte de origem concluiu pela responsabilidade do
agravante pelos danos materiais causados pela deterioração dosemi-reboqueda recorrida, enquanto o veículo estava em sua posse,
sob o único fundamento de que havia estipulação contratual nesse
sentido. Contudo, não especificou quais os danos materiais sofridos
pela agravada, tampouco qual o nexo causal entre eles e a conduta
imputada ao agravante.
2. Impõe-se, portanto, o retorno dos autos à Corte de origem para
que verifique se foram comprovados os danos e o nexo causal
necessários à condenação do réu ao pagamento de indenização por
danos materiais.
3. Agravo interno provido para reconsiderar a decisão agravada e, em
novo exame, conhecer do agravo para dar provimento ao recurso
especial, determinando o retorno dos autos ao Tribunal de origem.
Decis?o
Vistos e relatados estes autos, em que são partes as acima
indicadas, decide a Quarta Turma, por unanimidade, dar provimento ao
agravo interno, nos termos do voto do Sr. Ministro Relator. Os Srs.
Ministros Maria Isabel Gallotti, Antonio Carlos Ferreira, Marco
Buzzi (Presidente) e Luis Felipe Salomão votaram com o Sr. Ministro
Relator.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.4:acordao;aresp:2022-10-10;694701-2222342', 'AgInt no AREsp 694701 / RS', 'urn:lex:br:superior.tribunal.justica;turma.4:acordao;aresp:2022-10-10;694701-2222342', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Aresp', '2022-10-10', NULL, 'AGRAVO INTERNO NO AGRAVO EM RECURSO ESPECIAL. AÇÃO COMINATÓRIA.
AQUISIÇÃO DE VEÍCULOSEMIREBOQUEPOR MEIO DE DAÇÃO EM PAGAMENTO.
ALIENAÇÃO INDEVIDA DO BEM A TERCEIRO. PROCEDÊNCIA DA AÇÃO. JUNTADA
DE DOCUMENTOS COM A APELAÇÃO. DOCUMENTO NOVO. NÃO CARACTERIZAÇÃO.
LUCROS CESSANTES. DISPOSITIVOS APONTADOS COMO VIOLADOS. FALTA DE
PREQUESTIONAMENTO. INCIDÊNCIA DA SÚMULA 211/STJ.  AGRAVO INTERNO NÃO
PROVIDO.
1. No caso, os documentos apresentados pelo réu somente com a
apelação não se caracterizam propriamente como novos, porquanto
visavam comprovar fatos anteriores e impeditivos do direito da parte
autora, relacionados a simulação, fraude e má-fé. Deveriam ter sido
exibidos ainda na primeira instância, durante a instrução
processual.
2. Fica inviabilizado o conhecimento de temas trazidos no recurso
especial, mas não debatidos e decididos nas instâncias ordinárias,
não obstante a oposição de embargos declaratórios, porquanto ausente
o indispensável prequestionamento. Incidência da Súmula 211 do STJ.
3. Agravo interno a que se nega provimento.
Decis?o
Vistos e relatados estes autos em que são partes as acima indicadas,
acordam os Ministros da QUARTA TURMA do Superior Tribunal de
Justiça, em sessão virtual de 04/10/2022 a 10/10/2022, por
unanimidade, negar provimento ao recurso, nos termos do voto do Sr.
Ministro Relator.
Os Srs. Ministros João Otávio de Noronha, Maria Isabel Gallotti,
Antonio Carlos Ferreira e Marco Buzzi  votaram com o Sr. Ministro
Relator.
Presidiu o julgamento o Sr. Ministro Raul Araújo.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2016-06-22;1028-2012-585-9-0', 'Acórdão do processo Nº RR - 1028-03.2012.5.09.0585', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2016-06-22;1028-2012-585-9-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2016-06-22', NULL, 'INDENIZAÇÃO POR DANOS MORAIS E MATERIAIS. ACIDENTE DO TRABALHO. MOTORISTA DE CAMINHÃO PROFISSIONAL. ATIVIDADE DE RISCO. TEORIA DA RESPONSABILIDADE OBJETIVA. INDENIZAÇÃO POR DANO MORAL FIXADA EM R$ 10.000,00. INDENIZAÇÃO POR DANO MATERIAL INDEVIDA. Trata-se de pedido de indenização por danos morais e materiais decorrente de acidente do trabalho sofrido pelo empregado, na função de motorista profissional, durante o trabalho. Não há notícia nos autos de que o reclamante sofreu sequelas permanentes decorrentes do acidente. Conforme se constata da leitura da decisão regional, o Tribunal a quo concluiu que não há responsabilidade da empresa pelo acidente de trabalho sofrido pelo empregado motorista, porque, "ainda que a atividade de motorista possa ser enquadrada como de risco, prevalecendo a responsabilidade objetiva da empresa, a situação retratada não enseja reparação por dano moral. Não há notícia de que o Reclamante tenha ficado com sequelas decorrentes do acidente. Tampouco há informação de que a Ré tenha se negado a prestar assistência ao Autor, pois nada em sentido contrário foi mencionado a esse respeito. Por fim, após o afastamento por 60 dias, em percepção de benefício previdenciário, voltou a laborar na Ré em outra atividade, concluindo-se pela plena recuperação de sua capacidade laborativa". Todavia, ao contrário do entendimento adotado pelo Regional, o fato de o reclamante não ter apresentado sequelas decorrentes do acidente e de não existir nos autos informação de que a ré tenha se negado a prestar assistência ao autor, por si só, não afasta o risco de acidente de trabalho.  Outrossim, importante salientar que, sendo aatividade da empresa de risco, deve ser aplicada a responsabilidade objetiva no caso em exame, pois configurados o dano e o nexo causal. Infere-se do contexto fático delineado no acórdão recorrido que "Conforme vestígios encontrados no local bem como declaração dos envolvidos, V1 - Caminhão de placa MET -1493-, descia a Serra da BR376, no sentido Joinville, quando por volta do Km 673,4, perdeu o freio por pane mecânica ou defeito do veículo, desgovernou-se, colidiu na traseira de v2 - Conjunto Caminhão HRO-1703 eSemiReboqueAFC-4429 - e, na sequência, colidiu na lateral de v3 - Caminhão de Placa MDG-5833. V1, durante o acidente derramou toda a carga na pista e finalmente colidiu com barranco na lateral esquerda da pista." e que "de acordo com o que consta dos autos, o V1 (veículo 1) em questão era dirigido pelo Embargante Helio Ramiro Rodrigues e, que de acordo com o boletim de acidente de trânsito, o estado físico do condutor constava como: "lesões graves". Além disso, tratando-se de acidente de trabalho ocorrido no exercício de atividade de risco acentuado, como é o caso dos autos, caracterizada está a responsabilidade objetiva da empresa reclamada. Isso se mostra ainda mais evidente quando se está diante de atividade de motorista profissional, considerada de risco acentuado, ou seja, um risco mais elevado que aquele inerente às atividades de risco em geral, diante da maior pontencialidade de ocorrência do sinistro, o que configura o dano moral in re ipsa (decorrente do próprio fato em si). Com efeito, a Corte regional, ao desconsiderar a aplicação da teoria da responsabilidade objetiva do empregador, mesmo tratando-se de atividade laboral considerada de risco desenvolvida pelo autor (motorista de caminhão), decidiu em desacordo com a jurisprudência predominante nesta Corte superior e em afronta ao artigo 927 do Código Civil. No caso do pedido de indenização por danos morais, levando em consideração os requisitos como a extensão do dano (no caso, não há notícia de sequelas), o caráter satisfativo da medida, a condição econômica do ofensor e, ainda, os princípios da razoabilidade e da proporcionalidade, fixo a indenização em R$ 10.000,00. Todavia, não cabe falar em indenização por danos materiais. Não obstante conste da decisão regional que o reclamante retornou o serviço após o acidente para trabalhar em outra atividade, não há como se inferir que isso ocorreu em razão da redução da capacidade laborativa do reclamante. Isso porque também está registrado no acórdão recorrido que não houve sequelas decorrentes do acidente e que houve plena recuperação da capacidade laborativa. Recurso de revista conhecido e parcialmente provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('semi-reboque', '2025-07-12 17:37:37', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2015-11-18;146500-2008-751-4-0', 'Acórdão do processo Nº RR - 146500-02.2008.5.04.0751', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2015-11-18;146500-2008-751-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2015-11-18', NULL, 'I -  RECURSO DE REVISTA DO RECLAMANTE 1 - INTERVALO INTRAJORNADA. CONCESSÃO PARCIAL. PAGAMENTO TOTAL DO PERÍODO. Nos termos da Súmula 437, I, do TST, a concessão parcial do intervalo intrajornada, implica o pagamento total do período correspondente, e não apenas daquele suprimido, com acréscimo de cinquenta por cento. Recurso de revista conhecido e provido.  2 -  ADICIONAL DE PERICULOSIDADE. No caso, ao contrário do que alega o reclamante, a prova pericial, segundo se extrai do acórdão regional, constatou que os tanques de combustível eram originais de fábrica, razão pela qual, em conformidade com o disposto no item 16.6.1 da NR-16 da Portaria 3.214/78, a quantidade de inflamável transportada não pode ser considerada perigosa em função da capacidade dos tanques de combustível. O único aresto transcrito nas razões recursais é inespecífico, pois trata de hipótese diversa, relativa a caso em que foi utilizado tanque suplementar acoplado em carretasemi-reboqueem desacordo com a capacidade fixada por norma do Contran. Inteligência da Súmula 296, I, do TST. Recurso de revista não conhecido.  3 -  HORAS DE PRONTIDÃO. De acordo com o acórdão regional, não restou comprovada a exigência de o reclamante permanecer no veículo durante a noite. Para se chegar a conclusão diversa seria necessário o reexame da matéria fática-probatória, o que não se admite na presente fase recursal, na forma da Súmula 126 do TST. Recurso de revista não conhecido.  4 - DESCONTOS FISCAIS E PREVIDENCIÁRIOS. INDENIZAÇÃO. PERDAS E DANOS. Nos termos da parte final a Orientação Jurisprudencial 363 da SBDI-1 do TST, a culpa do empregador pelo inadimplemento das verbas remuneratórias não exime a responsabilidade do empregado pelos pagamentos do imposto de renda devido e da contribuição previdenciária que recaia sobre sua quota-parte. Recurso de revista não conhecido.  II -  RECURSO DE REVISTA DAS RECLAMADAS 1 -  CERCEAMENTO DE DEFESA. 1.1. Na hipótese, a reclamada alega que pretendia ouvir as testemunhas apenas para comprovar que o reclamante exercia atividade externa. 1.2. De acordo com o acórdão regional, é incontroverso que o reclamante exercia atividade externa, pois motorista de caminhão. A única controvérsia era saber se havia ou não possibilidade de controle de horário de trabalho para fins de enquadramento na exceção do art. 62, I, da CLT. Quanto a tal aspecto, segundo se extrai da decisão recorrida, em nada acrescentaria a oitiva das testemunhas arroladas pela reclamada, porquanto existentes outros elementos nos autos quanto a prova do controle da jornada de trabalho do reclamante. 1.3. Nesse contexto, não há de se falar cerceamento de defesa, pois compete ao magistrado, destinatário final da prova, em harmonia com o princípio do livre convencimento do juiz (CPC, art. 131), dirigir a instrução probatória (CLT, art. 765), podendo indeferir aqueles pedidos ou diligências que entender serem inúteis ou desnecessários (CPC, art. 130) à formação de seu convencimento, considerando o conjunto probatório dos autos, o que ocorreu no caso concreto. Recurso de revista não conhecido.  2 -  SALÁRIO "POR FORA". DIFERENÇAS DE COMISSÕES. MULTA POR LITIGÂNCIA DE MÁ-FÉ. 2.1. No caso dos autos, a perícia grafodocumentoscópica comprovou a inidoneidade dos recibos de pagamento de salários, razão pelas quais a Corte de origem concluiu como verdadeiros os fatos ventilados na inicial, quanto ao pagamento "por fora" dos salários e comissões. A revisão desse entendimento esbarra no óbice da Súmula 126 do TST. 2.2. Demonstrada a conduta desleal das reclamadas, ao produzirem em juízo documentos inidôneos, consoante constatado pela perícia, deve ser mantida a multa por litigância de má-fé. Recurso de revista não conhecido.  3 -  HORAS EXTRAS. TRABALHO EXTERNO. O Tribunal Regional manteve a condenação da reclamada ao pagamento de horas extras, afastando a excludente do art. 62, I, da CLT, pois, conforme se observa do acórdão recorrido, a prova dos autos demonstrou que, mesmo exercendo atividade externa, a jornada de trabalho do reclamante poderia ser controlada por parte da reclamada. A revisão desse entendimento, diante do quadro fático delimitado pela Corte de origem, demandaria o reexame de fatos e provas, circunstância que inviabiliza o processamento do recurso de revista, nos termos da Súmula 126 do TST. Recurso de revista não conhecido.  4 - FGTS. DIFERENÇAS. ÔNUS DA PROVA. À luz do princípio da aptidão para a prova, segundo a qual a prova deve ser produzida pela parte que tem acesso facilitado a ela, é do empregador o ônus da prova do correto recolhimento do FGTS, pois é seu dever legal manter em arquivo os recolhimentos realizados nas contas vinculadas de seus empregados. Diante disso, esta Corte inclusive cancelou o entendimento preconizado na Orientação Jurisprudencial 301 da SBDI-1 do TST. Recurso de revista não conhecido.  5 - HONORÁRIOS ADVOCATÍCIOS. O entendimento desta relatora é no sentido de que os honorários advocatícios, na Justiça do Trabalho, devem ser deferidos tanto pela mera sucumbência quanto a título de perdas e danos, seja na relação de emprego, amparada pela CLT, seja na relação de trabalho, protegida pela legislação ordinária, posição que melhor se coaduna com o princípio constitucional da igualdade, regendo uniformemente o assunto para todos os jurisdicionados da seara laboral. Entretanto, a Súmula 219 desta Corte, à qual me curvo em nome da uniformização da jurisprudência, exige a observância dos requisitos previstos na Lei 5.584/70. No caso dos autos, está ausente um dos requisitos previstos na Lei 5.584/70, consistente na assistência sindical, não sendo possível, pois, nos termos do entendimento sumulado, a condenação da reclamada ao pagamento dos honorários advocatícios. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('RNTRC', '2025-07-12 17:37:40', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.decreto.legislativo;pdc:2009-06-30;1664', 'PDC 1664/2009', 'urn:lex:br:camara.deputados:projeto.decreto.legislativo;pdc:2009-06-30;1664', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Camara Deputados', '2009-06-30', NULL, 'Susta as alíneas "a" e "d" do inciso I do art. 4º da Resolução nº 3.056, de 12 de março de 2009, da Agência Nacional de Transportes Terrestres, que dispõe sobre o exercício da atividade de transporte rodoviário de cargas por conta de terceiros e mediante remuneração, estabelece procedimentos para inscrição e manutenção no Registro Nacional de Transportadores Rodoviários de Cargas -RNTRCe dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('RNTRC', '2025-07-12 17:37:40', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.decreto.legislativo;pdc:2010-07-07;2828', 'PDC 2828/2010', 'urn:lex:br:camara.deputados:projeto.decreto.legislativo;pdc:2010-07-07;2828', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Camara Deputados', '2010-07-07', NULL, 'Susta a alínea "b" do inciso II do art. 4º da Resolução nº 3.056, de 12 de março de 2009, da Agência Nacional de Transportes Terrestres - ANTT, que dispõe sobre o exercício da atividade de transporte rodoviário de cargas por conta de terceiros e mediante remuneração, estabelece procedimentos para inscrição e manutenção no Registro Nacional de Transportadores Rodoviários de Cargas -RNTRCe dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('RNTRC', '2025-07-12 17:37:40', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2024-06-10;2111400-2445754', 'AgInt no REsp 2111400 / ES', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2024-06-10;2111400-2445754', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2024-06-10', NULL, 'PROCESSUAL CIVIL. ADMINISTRATIVO. ATOS ADMINISTRATIVOS. AÇÃO
ANULATÓRIA. PEDIDO DE ANTECIPAÇÃO DE TUTELA. RESOLUÇÃO ANTT N.
5.847/2019. SÚMULA N. 126/STJ. MULTA APLICADA PELA ANTT EM RAZÃO DA
EVASÃO DE POSTO DE FISCALIZAÇÃO. DESPROVIMENTO DO AGRAVO INTERNO.
MANUTENÇÃO DA DECISÃO RECORRIDA.
I - Na origem, trata-se de ação anulatória, com pedido de
antecipação de tutela. Na sentença o pedido foi julgado
improcedente. No Tribunal a quo, a sentença foi reformada, para dar
parcial provimento à apelação da autora, para (i) reduzir a multa a
ela imposta, adotando-se o novo valor fixado pela Resolução ANTT n.
5.847/2019, e (ii) condenar a apelante e a apelada ao pagamento de
honorários de sucumbência.
II -  Com efeito, em relação à alegada violação dos arts. 22, IV,
44, IV, e 26, IV, da Lei n. 10.233/2001, dos arts; 1º, 2º e 6º, §1º,
da LICC, e do art. 2º da Lei n. 9.784/1999, a Corte Regional, na
fundamentação do decisum vergastado, assim firmou entendimento (fls.
366-367): "[...] Ressalte-se, inicialmente, que não assiste razão à
ANTT quando alega que o pedido de redução da multa, formulado
apenas em sede de apelação, não deveria ser conhecido, pois, do
contrário, se estaria placitando uma ampliação indevida da causa de
pedir. A aplicação do princípio geral de direito sancionador da
retroatividade de lei mais benéfica (que pode ser extraído do art.
5º, XL, da CRFB/88 e do art. 9º do Pacto de São José da Costa Rica)
é matéria de ordem pública, que poderia ser conhecida até mesmo de
ofício por este Tribunal, na medida em que o pedido de afastamento
da multa imposta abrange a possibilidade de redução da sanção. No
caso, a Apelante foi autuada por ter cometido, em 20/3/2015, a
infração prevista no art. 34, VII, da então vigente Resolução ANTT
nº 3.056/2009, que, com a redação dada pela Resolução ANTT nº
3.745/2011, previa: Art. 34. Constituem infrações:(...). VII -
evadir, obstruir ou de qualquer forma, dificultar a fiscalização:
multa de R$ 5.000,00 (cinco mil reais), cancelamento doRNTRCe
impedimento de obter registro pelo prazo de dois anos. Em seguida, a
Resolução ANTT nº 4.799 de 27/7/2015 revogou a Resolução ANTT nº
3.056/2009 e, em relação à infração sob análise, passou a prever:
Art. 36. Constituem infrações, quando: I - o transportador, inscrito
ou não noRNTRC, evadir, obstruir ou, de qualquer forma, dificultar
a fiscalização durante o transporte rodoviário de cargas: multa de
R$ 5.000,00 (cinco mil reais);Por fim, foi editada a Resolução ANTT
nº 5.847 de 21/5/2019, que, alterando a redação do mencionado inciso
I do art. 36, reduziu o valor da multa em questão de R$ 5.000,00
(cinco mil reais) para R$ 550,00 (quinhentos e cinquenta reais):
Art. 36. Constituem infrações, quando: I - o transportador, inscrito
ou não noRNTRC, obstruir ou, de qualquer forma, dificultar a
fiscalização durante o transporte rodoviário de cargas: multa de R$
550,00 (quinhentos e cinquenta reais).[...]."
III - Consoante se verifica dos excertos reproduzidos do aresto
vergastado, a Corte a quo decidiu a matéria com fundamento principal
de índole constitucional (art. 5º, XL, da CRFB/88 e art. 9º do
Pacto de São José da Costa Rica), o que impede a análise da alegação
relativa à mesma matéria nesta Corte Superior. Todavia, não houve
interposição de recurso extraordinário nem cumprimento ao
determinado, nos termos do art. 1.032 do CPC, o que impossibilita o
conhecimento do recurso especial. Isso porque, de acordo com a
Súmula n. 126/STJ, "É inadmissível recurso especial, quando o
acórdão recorrido assenta em fundamentos constitucional e
infraconstitucional, qualquer deles suficiente, por si só, para
mantê-lo, e a parte vencida não manifesta recurso extraordinário".
Nesse sentido: AgInt no REsp n. 2.068.131/RS, relator Ministro
Herman Benjamin, Segunda Turma, julgado em 2/10/2023, DJe de
9/10/2023; AgInt no AREsp n. 2.457.642/DF, relator Ministro Humberto
Martins, Terceira Turma, julgado em 11/3/2024, DJe de 14/3/2024;
AgInt no AREsp n. 2.098.451/MG, relator Ministro Humberto Martins,
Segunda Turma, julgado em 27/3/2023, DJe de 30/3/2023.
IV - Quanto ao mais, observa-se que o Tribunal abordou controvérsia
relacionada à análise e interpretação de atos normativos infralegais
(Resolução ANTT n. 5.847/2019, Resolução ANTT n. 4.799/2015,
Resolução ANTT n. 3.056/2009 e Resolução ANTT n. 3.745/2011), que
não equivalem à lei federal para fins de interposição de recurso
especial. A propósito, dentro inúmeros: AgInt nos EDcl no AREsp n.
2.164.761/SP, relator Ministro Marco Buzzi, Quarta Turma, julgado em
26/2/2024, DJe de 28/2/2024; EDcl no AgInt nos EDcl no REsp n.
1.932.247/RS, relator Ministro Herman Benjamin, Segunda Turma,
julgado em 12/12/2023, DJe de 24/1/2024.
V - Agravo interno improvido.
Decisão
Vistos e relatados estes autos em que são partes as acima
indicadas, acordam os Ministros da SEGUNDA TURMA do Superior
Tribunal de Justiça, em sessão virtual de 04/06/2024 a 10/06/2024,
por unanimidade, negar provimento ao recurso, nos termos do voto do
Sr. Ministro Relator.
Os Srs. Ministros Herman Benjamin, Mauro Campbell Marques, Teodoro
Silva Santos e Afrânio Vilela  votaram com o Sr. Ministro Relator.
Presidiu o julgamento o Sr. Ministro Afrânio Vilela.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('RNTRC', '2025-07-12 17:37:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;ag:2021-09-15;978-2012-291-4-0', 'Acórdão do processo Nº Ag-RR - 978-24.2012.5.04.0291', 'urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;ag:2021-09-15;978-2012-291-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ag', '2021-09-15', NULL, 'AGRAVO INTERNO EM RECURSO DE REVISTA DA RECLAMADA. "HORAS EXTRAS ACT". AUSÊNCIA DE IMPUGNAÇÃO DO ÓBICE DIVISADO NA DECISÃO MONOCRÁTICA. Verificado que o agravante não infirma o óbice processual divisado na decisão monocrática, não há como conhecer do apelo. Exegese da Súmula n.º 422, I, do TST. Agravo não conhecido, no tópico. RECONHECIMENTO DE VÍNCULO DE EMPREGO ENTRE TRANSPORTADOR AUTÔNOMO E PROPRIETÁRIO DE EMPRESA TRANSPORTADORA. VÍNCULO ANTERIOR À VIGÊNCIA DA LEI N.º 11.442/2007. SÚMULA N.º 126 DO TST. In casu, diante da premissa fática delineada pela Corte de origem, no sentido de que: a) foram preenchidos os pressupostos dos arts. 2.º e 3.º da CLT, em especial a subordinação jurídica, ante a constatação de que o reclamante cumpria roteiro de entrega e prestava contas, bem como tinha que se adequar às normas internas de funcionamento da empresa; e b) não foi comprovado o atendimento das exigências previstas na Lei n.º 11.442/2007, dentre as quais a inscrição do autor no Registro Nacional de Transportadores Rodoviários de Cargas -RNTRC; o registro do caminhão de propriedade do reclamante no órgão de trânsito como veículo de aluguel; a experiência de três anos ou a aprovação em curso específico, somente mediante o reexame do conjunto fático-probatório seria possível afastar o reconhecimento do vínculo empregatício, de forma a se permitir o enquadramento do obreiro na Lei n.º 11.442/2007. Assim, deve ser mantida a decisão ora agravada que aplicou a Súmula n.º 126 do TST como óbice ao conhecimento do Recurso de Revista. Agravo conhecido e não provido, no tópico.  MÉDIA SALARIAL. ART. 896, § 1.º-A, III, DA CLT. A despeito das razões expostas pelo agravante, deve ser mantida a decisão pela qual foi não foi conhecido o Recurso de Revista, pois não observados os requisitos elencados no art. 896, § 1.º-A, III, da CLT. Agravo conhecido e não provido, no tópico. AGRAVO INTERNO EM RECURSO DE REVISTA DO RECLAMANTE. RECONHECIMENTO DO VÍNCULO DE EMPREGO. AUSÊNCIA DE INTERESSE RECURSAL. Diante da manutenção da decisão regional que reconheceu o vínculo empregatício, é manifesta a ausência de interesse recursal do reclamante quanto à reforma do julgado. Agravo não conhecido, no tópico. HONORÁRIOS ADVOCATÍCIOS. ASSISTÊNCIA SINDICAL. Verificado o equívoco na decisão monocrática agravada, em dissonância com a jurisprudência do TST (Súmula n.º 219, I e 333), merece provimento o Agravo Interno do reclamante para afastar a conclusão adotada na decisão monocrática em relação ao provimento da reclamada que excluiu da condenação os honorários advocatícios. Agravo conhecido e provido para analisar novamente o Recurso de Revista da reclamada somente quanto ao tema. RECURSO DE REVISTA DA RECLAMADA. APELO INTERPOSTO ANTES DA VIGÊNCIA DA LEI N.º 13.015/2014. HONORÁRIOS ADVOCATÍCIOS. ASSISTÊNCIA SINDICAL. BASE TERRITORIAL DA ENTIDADE SINDICAL. Em conformidade com a jurisprudência desta Corte, a concessão dos honorários advocatícios na Justiça do Trabalho, nos processos anteriores à Lei n.º 13.467/2017, depende do preenchimento dos requisitos previstos no art. 14 da Lei n.º 5.584/1970 e na Súmula n.º 219, I, do TST, quais sejam: a condição de miserabilidade jurídica e a assistência judiciária pela entidade sindical profissional, independentemente da sua base territorial. In casu, tendo sido firmada a declaração de miserabilidade jurídica e, estando o reclamante assistido pelo Sindicato dos trabalhadores do Estado do Rio Grande do Sul, que representa a sua categoria profissional, a concessão da verba honorária se afigura devida. Recurso de Revista não conhecido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('RNTRC', '2025-07-12 17:37:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2021-09-29;11323-2017-7-15-0', 'Acórdão do processo Nº AIRR - 11323-46.2017.5.15.0007', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:2021-09-29;11323-2017-7-15-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2021-09-29', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. PROCESSO SOB A ÉGIDE DA LEI 13.015/2014 E ANTERIOR À LEI 13.467/2017. VÍNCULO DE EMPREGO. NÃO CONFIGURAÇÃO. TRANSPORTE RODOVIÁRIO DE CARGAS POR CONTA DE TERCEIROS E MEDIANTE REMUNERAÇÃO. LEI Nº 11.442/2007. RELAÇÃO COMERCIAL DE NATUREZA CIVIL. CONSTITUCIONALIDADE RECONHECIDA NO JULGAMENTO CONJUNTO DA ADC 48 E DA ADIn 3.961 PELO SUPREMO TRIBUNAL FEDERAL. O fenômeno sociojurídico da relação empregatícia emerge quando reunidos os seus cinco elementos fático-jurídicos constitutivos: prestação de trabalho por pessoa física a outrem, com pessoalidade, não eventualidade, onerosidade e sob subordinação. A diferenciação central entre o trabalhador autônomo e o empregado situa-se na subordinação. Fundamentalmente, trabalho autônomo é aquele que se realiza sem subordinação do trabalhador ao tomador de serviços. Autonomia é conceito antitético ao de subordinação. Enquanto esta traduz a circunstância juridicamente assentada de que o trabalhador acolhe a direção empresarial no tocante ao modo de concretização cotidiana de seus serviços, a autonomia traduz a noção de que o próprio prestador é que estabelece e concretiza, cotidianamente, a forma de realização dos serviços que pactuou prestar. Não se desconhece, outrossim, que o princípio constitucional da valorização do trabalho e do emprego, ao lado de outros princípios constitucionais convergentes (dignidade da pessoa humana e justiça social) tornam presumido o vínculo empregatício nos casos em que desponta incontroversa a prestação se serviços (Súmula 212, TST). Tal presunção, contudo, é relativa, podendo ser elidida por prova em contrário. A Constituição da República, a propósito, elogia e estimula a relação empregatícia,ao reportar a ela, direta ou indiretamente, várias dezenas de princípios, regras e institutos jurídicos. Em consequência, possuem caráter manifestamente excetivo fórmulas alternativas de prestação de serviços a alguém, por pessoas naturais, como, ilustrativamente, contratos de estágio, vínculos autônomos ou eventuais, relações cooperativadas e a fórmula intitulada de "pejotização". Em qualquer desses casos - além de outros -, estando presentes os elementos da relação de emprego, esta prepondera, impõe-se e deve ser reconhecida, uma vez que a verificação desses pressupostos, muitas vezes, demonstra que a adoção de tais práticas se dá apenas como meio de precarizar as relações empregatícias. Somente não se enquadrará como empregado o efetivo trabalhador autônomo ou eventual. Na hipótese, o Tribunal Regional, após a análise das provas produzidas pelas partes,  concluiu que a prestação de serviços pelo Reclamante se deu de forma autônoma, nos moldes da Lei nº 11.442/2007, reconhecendo a natureza civil do contrato e registrando o cumprimento do requisito previsto no art. 2º da referida lei: "No caso, o reclamante possuiRNTRCativo desde 1º.2.2005 até 16.5.2021, conforme documento trazido com a defesa (¿) e as partes (primeira e segunda reclamadas e o reclamante) firmaram contratos de '' Transporte Rodoviários de Bens'' , inerentes a cada frete realizado entre 19.11.2014 e 4.8.2016 (¿), tendo o reclamante sido contratado na condição de Transportador de Cargas Autônomo - TCA." Consignou ainda o Regional, à luz do acervo fático-probatório examinado: '' Assim, ainda que se extraia a presença de um dos requisitos da relação de emprego, qual seja, a pessoalidade, ficou comprovado que o autor, como freteiro/motorista agregado não precisava cumprir horário de trabalho e somente os prazos estipulados para o serviço de entrega, o qual, inclusive, poderia ser rejeitado pelo obreiro, sem qualquer punição e represália por parte das reclamadas. (...) Quanto às despesas (custos de manutenção do veículo e combustível) entende-se que todas elas corriam por conta do próprio reclamante, em razão do preço ajustado, assumindo os riscos de seu negócio. Perceba-se que o valor mencionado na exordial de R$12.000,00 mensais, engloba os valores de combustível, pedágio e manutenção em razão do importe salarial claramente elevado para os motoristas, conforme se verifica pelos instrumentos normativos trazidos pelo reclamante, onde, por exemplo, o salário médio do motorista de caminhão de transporte pesado é de R$1.783,44. Diante de todos esses fatos, não se pode admitir que a simples programação de transporte do reclamante pela reclamada é suficiente para caracterizar subordinação. Dessa forma, por ausente o requisito da subordinação, reconheço que de fato o vínculo entre o reclamante e a reclamada se deu de forma autônoma, pelo que não reconheço a existência do vínculo empregatício." Registre-se, a propósito, que o Supremo Tribunal Federal, ao decidir a ADC 48, em conjunto com a ADIn 3.961, declarou a constitucionalidade da Lei 11.442/2007, firmando a seguinte tese: "1 -  A Lei 11.442/2007 é constitucional, uma vez que a Constituição não veda a terceirização, de atividade-meio ou fim. 2 -  O prazo prescricional estabelecido no art. 18 da Lei 11.442/2007 é válido porque não se trata de créditos resultantes de relação de trabalho, mas de relação comercial, não incidindo na hipótese o art. 7º, XXIX, CF. 3 -  Uma vez preenchidos os requisitos dispostos na Lei nº 11.442/2007, estará configurada a relação comercial de natureza civil e afastada a configuração de vínculo trabalhista" (ADC 48, Relator(a): ROBERTO BARROSO, Tribunal Pleno, julgado em 15/04/2020, PROCESSO ELETRÔNICO DJe-123DIVULG 18-05-2020PUBLIC 19-05-2020). Portanto, do cenário exposto no acórdão recorrido, constata-se que a Corte Regional não vislumbrou a presença dos elementos configuradores do vínculo de emprego, porquanto revelado que a natureza da relação mantida entre as Partes se deu nos moldes da Lei nº 11.442/2007, que dispõe sobre o transporte rodoviário de cargas por conta de terceiros e mediante remuneração. No mesmo sentido, julgados desta Corte Superior. Por estar a decisão recorrida em harmonia com a jurisprudência atual, notória e reiterada desta Corte Superior Trabalhista, o apelo revisional não se viabiliza, restando incólumes os dispositivos constitucionais e legais apontados e irrelevantes eventuais arestos trazidos ao confronto de teses. Incidência da Súmula 333/TST e do § 7º do art. 896 da CLT. Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('RNTRC', '2025-07-12 17:37:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2017-05-24;1364-2012-802-4-0', 'Acórdão do processo Nº RR - 1364-73.2012.5.04.0802', 'urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2017-05-24;1364-2012-802-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2017-05-24', NULL, 'I) AGRAVO. HORAS EXTRAORDINÁRIAS. CONTROLE DE JORNADA DE TRABALHO. LABOR EXTERNO. MOTORISTA. PROVIMENTO. Ante o equívoco no exame do agravo de instrumento, dá-se provimento ao agravo. Agravo a que se dá provimento. II) AGRAVO DE INSTRUMENTO.  HORAS EXTRAORDINÁRIAS. CONTROLE DE JORNADA DE TRABALHO. LABOR EXTERNO. MOTORISTA. POSSÍVEL OFENSA AO ARTIGO 62, I, DA CLT. PROVIMENTO. Ante a possível violação do artigo 62, I, da CLT, o provimento do agravo de instrumento para o exame do recurso de revista é medida que se impõe. Agravo de instrumento a que se dá provimento.  III) RECURSO DE REVISTA. 1. VÍNCULO DE EMPREGO. MOTORISTA. TRANSPORTE RODOVIÁRIO DE CARGAS. RELAÇÃO COMERCIAL PREVISTA NA LEI Nº 11.442/2007. NÃO COMPROVAÇÃO.  REEXAME DE FATOS E PROVAS. SÚMULA Nº 126. NÃO CONHECIMENTO. A Lei nº 11.442/2007, que dispõe sobre o transporte rodoviário de cargas, preceitua que essa atividade, a qual pode ser explorada por pessoa física ou jurídica, possui natureza comercial, e, como corolário, as relações decorrentes dessa contratação não caracterizam vínculo de emprego.  Ademais, referida lei, em seu artigo 2º, estabelece vários requisitos a serem observados por quem deseje realizar tal atividade, tais como a inscrição no Registro Nacional de Transportadores Rodoviários de Cargas -RNTRC; ser o transportador autônomo possuidor ou proprietário de pelo menos um veículo automotor de carga, registrado em seu nome no órgão de trânsito como veículo de aluguel; e ter experiência de três anos ou ter sido aprovado em curso específico. Se comprovada a relação comercial, estando o transportador autônomo de cargas devidamente enquadrado nas disposições da Lei nº 11.442/2007 - mediante a demonstração, por exemplo, de que ele realiza o transporte de carga com veículo de sua propriedade, sem qualquer interferência do tomador na direção dos serviços prestados, arcando com as despesas dessa atividade -, a ele se aplica a presunção legal de inexistência de relação de emprego, não havendo falar em trabalho subordinado para fins de incidência das normas trabalhistas. Ocorre que referida presunção é relativa, porquanto é possível que no caso concreto resultem configurados os requisitos da relação de emprego previstos no artigo 3º da CLT. Isso porque no Direito do Trabalho vigora o princípio da primazia da realidade, segundo o qual a verdade dos fatos se sobrepõe a aspectos formais, de modo que a presunção de inexistência de relação de emprego pode ser afastada pelos elementos probatórios constantes do processo. Na hipótese dos autos, não se identifica no acórdão regional o enquadramento do reclamante nos ditames da Lei nº 11.442/2007, relativamente ao período em discussão (posterior a 06.05.2011). Consta do acórdão recorrido que o reclamante foi admitido pela reclamada em 11.08.2009, como motorista carreteiro, despedido sem justa causa em 05.05.2011, e no dia seguinte, em 06.05.2011, adquiriu da reclamada o veículo SCANIA/P-310 e passou a prestar-lhe serviços mediante "CONTRATO DE PRESTAÇÃO DE SERVIÇOS DE TRANSPORTE RODOVIÁRIO DE BENS E OUTRAS AVENÇAS", após constituir em 24.02.2011 a empresa W A RILLO MARTINS - TRANSPORTES-ME. O egrégio Tribunal Regional entendeu que era de emprego a relação existente entre o reclamante e a reclamada a partir de 06.05.2011. Dentre os seus fundamentos, considerou que "a existência de contrato de trabalho anterior, no período de 11.08.2009 a 05.05.2011, e a aquisição do caminhão na mesma data da extinção do referido contrato, evidencia a fraude aos direitos trabalhistas, pois o reclamante continuou exercendo as mesmas funções, sem a empresa adimplir com todas as obrigações decorrentes da relação empregatícia.". Por outro lado, julgou, com base nas provas produzidas no processo, que restaram devidamente demonstrados os requisitos previstos no artigo 3º da CLT, quais sejam, a onerosidade, a pessoalidade, a não eventualidade e a subordinação. Sendo assim, esta Corte Superior somente poderia reconhecer a relação comercial de que trata a Lei nº 11.442/2007 e, por conseguinte, afastar o vínculo de emprego, após a modificação do quadro fático delineado pelo Tribunal Regional, o que, no entanto, é vedado pela Súmula nº 126.  Recurso de revista de que não se conhece. 2. HORAS EXTRAORDINÁRIAS. CONTROLE DE JORNADA DE TRABALHO. LABOR EXTERNO. MOTORISTA. VIOLAÇÃO DO ARTIGO 62, I, DA CLT. PROVIMENTO. O artigo 62, I, da CLT estabelece exceção ao regime de controle de jornada aos empregados que exercem atividade externa, sempre que não for possível a fixação de horário. A contrario sensu, quando na atividade externa for viável a aferição do horário de trabalho, com o controle da jornada, não há falar na incidência do disposto no mencionado preceito, o que possibilita o empregado a reivindicar o pagamento de horas extraordinárias, caso demonstrado labor superior ao estabelecido em lei. Sobre as formas de controle, este Tribunal Superior tem admitido todos aqueles que, de forma direta ou indireta, tornem possível o acompanhamento da jornada de trabalho, sendo despiciendo para o afastamento da exceção do artigo 62, I, da CLT, o fato de o empregador não realizar a efetiva fiscalização, mesmo dispondo de meios para tanto.  Oportuno realçar que o dispositivo em epígrafe cuida de uma excepcionalidade, de um tipo específico de empregado, que, dado o ofício que desempenha, fora do ambiente de trabalho da empresa, lhe é aplicado tratamento diferenciado. E diante da natureza especial do labor, a norma jurídica estabeleceu a presunção de que esses empregados não estão submetidos à fiscalização de jornada. Por conta disso, apenas por meio de prova em contrário poderá ser afastada a circunstância presumida da inviabilidade do citado controle. E não basta a constatação de um fato isolado na atividade exercida pelo empregado externo para que se infira como viável a fiscalização da sua jornada.   É necessário que exista um conjunto de elementos de prova (registro de itinerários das viagens; visitas a clientes de forma programada; itinerários pré-estabelecidos; monitoramento do serviço por meio telefônico ou outro instrumento de comunicação; obrigação de iniciar e terminar a jornada na empresa em determinado horário; acompanhamento do percurso de trabalho por meio de equipamento via satélite) capaz de levar à indubitável conclusão de que, no caso concreto, de fato, há a possibilidade do efetivo controle do horário de labor do empregado. Ressalte-se que a fiscalização do trabalho é uma consequência lógica da relação de emprego, porquanto inerente ao contrato de trabalho. Por essa razão, fiscalização do trabalho não se confunde com fiscalização de horários, de maneira que os meios de que dispõe o empregador para monitorar a prestação dos serviços não necessariamente implicam, por si sós, formas de controle da jornada cumprida pelo trabalhador. Na hipótese, o egrégio Tribunal Regional concluiu que a existência de rastreador, GPS e telefone celular no caminhão possibilitava à reclamada o controle da jornada externa do reclamante, pois o monitoramento efetuado por meio dos aludidos equipamentos indicava "que a reclamada tinha plenas e viáveis condições de saber a localização do reclamante, bem como se este estava parado ou se deslocando", ainda que "não houvesse controle ostensivo do horário de trabalho dos empregados da reclamada, admitidos na função de motorista". Ocorre que a utilização do GPS - Global Positioning System -  instrumento por meio do qual é possível saber a localização, posição e, em alguns casos, velocidade do veículo, não se apresenta como suficiente para a conclusão de que haveria possibilidade de controle de jornada de trabalho do reclamante. A finalidade de tal instrumento, em casos tais, é sem dúvida a localização da carga transportada e não da quantidade de horas trabalhadas. O mesmo se diga em relação ao rastreador. A utilização de rastreador e GPS não serve ao controle da efetiva jornada laboral do empregado, porquanto tais instrumentos se destinam ao monitoramento da carga a ser entregue, e não das horas trabalhadas pelo motorista. Também o celular não se revela apto a permitir o controle da jornada do reclamante, pois eventual contato por meio desse equipamento não tem o condão de possibilitar à reclamada a aferição dos horários de trabalho efetivamente cumpridos pelo empregado, ou se o reclamante estaria usufruindo dos intervalos de descanso. É possível, inclusive, que, estando longe da supervisão direta do patrão, o empregado esteja se ocupando com atribuições de ordem pessoal, durante o período em que contatado por meio de telefone celular. Ora, uma vez que a conclusão da Corte Regional acerca da possibilidade de controle de jornada na atividade externa exercida pelo reclamante amparou-se, única e exclusivamente, na existência dos mencionados equipamentos no caminhão (rastreador, GPS e telefone celular), reputa-se violado o artigo 62, I, da CLT, sendo imperioso excluir da condenação as horas extraordinárias deferidas. Recurso de revista de que se conhece e a que se dá provimento. 3. ADICIONAL DE PERICULOSIDADE. TRANSPORTE DE PRODUTOS INFLAMÁVEIS (TINTAS E SOLVENTES). ANEXO 2 DA NR 16 DA PORTARIA Nº 3.214/78 DO MTE. CONTATO PERMANENTE. ACÓRDÃO REGIONAL AMPARADO NO LAUDO PERICIAL. ÓBICE DA SÚMULA Nº 126. NÃO CONHECIMENTO. O Tribunal Regional decidiu manter a condenação ao pagamento do adicional de periculosidade, nos meses de dezembro/2009 e março/2011, por constatar, com base no laudo pericial, que nesse período o reclamante efetivamente transportou produtos inflamáveis (tintas e solventes) em recipientes de 200 litros, ficando comprovado o enquadramento de sua atividade no Anexo 2 da NR-16, da Portaria 3.214/78 do MTE, que considera perigoso o transporte de vasilhames (em caminhões de carga) contendo inflamável líquido, em quantidade total igual ou superior a 200 litros. Enfatizou aquela Corte Regional que a exposição do reclamante ao risco se deu de forma permanente, pois, na função de motorista de caminhão, ele percorria longas distâncias transportando a carga contendo produtos inflamáveis. Desse modo, a pretensão da reclamada, no sentido de que o autor mantinha contato eventual com os inflamáveis, porque teria transportado tintas e solventes somente "em duas viagens ao longo de todo o contrato de trabalho, com intervalo de 14 meses entre uma e outra", somente se viabilizaria nesta instância extraordinária após a modificação do quadro fático delineado no acórdão regional, o que encontra óbice na Súmula nº 126. Recurso de revista de que não se conhece.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('veículos comerciais', '2025-07-12 17:37:42', 'https://www.lexml.gov.br/urn/urn:lex:br;sao.paulo:estadual:lei:2007-01-02;12521', 'Lei nº 12.521, de 02/01/2007', 'urn:lex:br;sao.paulo:estadual:lei:2007-01-02;12521', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '2007-01-02', 'Autopeças  ,  Desmanche deVeículo,VeículoAutomotor  ,  Comércio  ,  EstabelecimentoComercial', 'Disciplina o funcionamento de estabelecimentoscomerciaisde desmonte deveículosautomotores de via terrestre dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
