INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('veículos comerciais', '2025-07-12 17:37:42', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:1996-09-02;46729-130343', 'REsp 46729 / SP', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:1996-09-02;46729-130343', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '1996-09-02', 'CABIMENTO, INDENIZAÇÃO, FURTO, DANO,VEICULOAUTOMOTOR,
ESTACIONAMENTO, ESTABELECIMENTOCOMERCIAL, UTILIZAÇÃO, GRATUIDADE,
CARACTERIZAÇÃO, RESPONSABILIDADE CIVIL, GUARDA,VEICULOAUTOMOTOR.', 'RESPONSABILIDADE CIVIL. GUARDA DEVEICULOS. ESTABELECIMENTOCOMERCIAL. ESTACIONAMENTO.
I - NO CASO A MATERIA CONTROVERTIDA FOI EXAMINADA APENAS SOB O
PRISMA CONSTITUCIONAL PELAS INSTANCIAS ORDINARIAS. TODAVIA, AINDA
QUE ASSIM NÃO FOSSE, NÃO TERIA COMO PROSPERAR A IRRESIGNAÇÃO,
PORQUANTO FIRMOU-SE A JURISPRUDENCIA DESTE TRIBUNAL NO SENTIDO DE
QUE O ESTABELECIMENTOCOMERCIALQUE OFERECE ESTACIONAMENTO EM AREA
PROPRIA PARA COMODIDADE DOS SEUS CLIENTES, AINDA QUE A TITULO
GRATUITO, ASSUME EM PRINCIPIO A OBRIGAÇÃO DE GUARDA DOSVEICULOS,
SENDO ASSIM RESPONSAVEL CIVILMENTE PELO SEU FURTO OU DANIFICAÇÃO.
PRECEDENTES.
II - RECURSO ESPECIAL NÃO CONHECIDO.
Decisão
POR UNANIMIDADE, NÃO CONHECER DO RECURSO.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
