INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('conversão', '2025-07-12 17:37:51', 'https://www.lexml.gov.br/urn/urn:lex:br:senado.federal:projeto.lei.conversao;plv:2013;11', '[ Projeto de Lei deConversão(CN) nº 11/2013 ]', 'urn:lex:br:senado.federal:projeto.lei.conversao;plv:2013;11', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Senado Federal', '2013-01-01', NULL, 'Altera as Leis nº 12.546, de 14 de dezembro de 2011, para prorrogar o Regime Especial de Reintegração de Valores Tributários para as Empresas Exportadoras - Reintegra, e para alterar o regime de desoneração da folha de pagamentos; nº 11.774, de 17 de setembro de 2008; nº 10.931, de 2 de agosto de 2004; nº 12.431, de 24 de junho de 2011; nº 9.718, de 27 de novembro de 1998; nº 9.514. de 20 novembro de 1997; nº 10.925, de 23 de julho de 2004; nº 10.485, de 3 de julho de 2002; nº 12.249, de 11 de junho de 2010; nº 9.430, de 27 de dezembro de 1996; nº 9.393, de 19 de dezembro de 1996; nº 10.522, de 19 de julho de 2002; nº 8.218, de 29 de agosto de 1991; nº 10.833, de 29 de dezembro de 2003; nº 10.865, de 30 de abril de 2004; nº 11.727, de 23 de junho de 2008; nº 12.350, de 20 de dezembro de 2010; regula a compra, venda e transporte de ouro; altera a sistemática de aproveitamento do saldo de créditos presumidos da Contribuição para o PIS/Pasep e da Cofins oriundos da cadeia de comercialização do café; cria crédito presumido do Imposto sobre Produtos Industrializados na aquisição de desperdícios, resíduos e aparas de plástico; dispõe sobre a comprovação de regularidade fiscal pelo contribuinte; altera a incidência da Contribuição para o PIS/Pasep e da Cofins na cadeia de produção e comercialização da soja e de seus subprodutos; concede incentivo tributário para a construção de cisternas