INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('gás natural veicular', '2025-07-12 17:38:01', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais:estadual:decreto:2024-12-26;48970', 'Decreto nº 48970, de 26 de dezembro de 2024', 'urn:lex:br;minas.gerais:estadual:decreto:2024-12-26;48970', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '2024-12-26', 'Prorroga a data da eficácia da redução da base de cálculo para 
operações de saída interna deGásNaturalVeicular- GNV -, 
passando de 31/12/2024 para 31/12/2025. Estende o prazo da 
isenção aplicada às importações do exterior e às operações de 
saída interna ou interestadual de cateter balão para 
septostomia, utilizado na prestação de serviços de saúde, 
alterando a data de 1º/12/2024 para 31/07/2025.', 'Altera o Decreto nº 48.589, de 22 de março de 2023, que regulamenta o Imposto sobre Operações relativas à Circulação de Mercadorias e sobre Prestações de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação – ICMS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('gás natural veicular', '2025-07-12 17:38:01', 'https://www.lexml.gov.br/urn/urn:lex:br;santa.catarina:estadual:lei:2014-06-11;16402', 'LEI Nº 16.402, DE 11 DE JUNHO DE 2014', 'urn:lex:br;santa.catarina:estadual:lei:2014-06-11;16402', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '2014-06-11', 'GNV', 'Art. 1º Os postos de abastecimento de combustíveis que forneçamGásNaturalVeicular(GNV) somente poderão abastecer os veículos dos consumidores do combustível gasoso mediante a apresentação prévia do Selo de Abastecimento de GNV válido, conforme modelo previsto na regulamentação específica do Instituto Nacional de Metrologia, Qualidade e Tecnologia (INMETRO), dentro da validade.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('gás natural veicular', '2025-07-12 17:38:01', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais:estadual:decreto:2023-03-08;48584', 'Decreto nº 48584, de 8 de marÃ§o de 2023', 'urn:lex:br;minas.gerais:estadual:decreto:2023-03-08;48584', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '2023-03-08', 'Prorroga a data de eficácia da redução da base de cálculo 
tributária para saída, em operação interna, deGásNaturalVeicular– GNV - e, no âmbito do regime especial de tributação, 
determina que o diferimento com relação ao pagamento do imposto 
incidente nas sucessivas saídas de lingote ou tarugo de metal 
não ferroso, classificados na posição 7901 da Nomenclatura 
Brasileira de Mercadorias - Sistema Harmonizado (NBM/SH - com o 
sistema de classificação adotado até 31/12/1996) aplica-se 
somente nas operações com destino a estabelecimento industrial 
