INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;sao.paulo:estadual:decreto:2014-05-26;60491', 'Decreto nº 60.491, de 26/05/2014', 'urn:lex:br;sao.paulo:estadual:decreto:2014-05-26;60491', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '2014-05-26', 'Transporte Coletivo  ,  TransportedeCarga', 'Institui Grupo de Trabalho, no âmbito do Plano de Ação da Macrometrópole - PAM, com o objetivo de consolidar as estratégias de transporte de passageiro e delogísticadecargas, e dá providências correlatas', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.1:acordao:2010-02-03;0038500-46.2008.5.16.0015', 'ACORDÃO TRT 16ª / 1ª Turma / RO 0038500-46.2008.5.16.0015', 'urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.1:acordao:2010-02-03;0038500-46.2008.5.16.0015', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 16', 'Tribunal Regional Trabalho', 'Acordao', '2010-02-03', 'AUTÔNOMO,CARGAS,CLT,COMETA,CONFIGURAÇÃO,CONTRATO,CPC,EMPREGO,LOGÍSTICA,RAPIDÃO,RELAÇÃO,TRANPORTE,TRANSPORTE', 'CONTRATO DE TRANPORTEDECARGASAUTÔNOMO - RELAÇÃO DE EMPREGO - CONFIGURAÇÃO. Em se tratando de reconhecimento de vínculo empregatício, de início, o ônus probatório é do autor, conforme explica o art. 818 da CLT. Porém, negando tal vínculo, e admitindo a existência de outro tipo de relação entre as partes, como a de Transportador AutônomodeCargasIndependente, o reclamado atrai para si o ônus da prova, nos termos do art. 333, II, do CPC. Não restando demonstrado nos autos a existência de contrato formal celebrado entre as partes, tendo por objeto a prestação de serviços como transportador rodoviáriodecargaspor conta de terceiro, de natureza comercial, bem como a inscrição do prestador de serviços em registro nacional ou órgão disciplinar, consoante exigência das Leis 7.290/84 e 11.442/2007, aliada à circunstância de restar caracterizada no plano fático a relação de emprego, nos moldes do art. 3º da CLT, faz-se necessário o reconhecimento do vínculo empregatício. Recurso ordinário conhecido e não provido.                        Vistos, relatados e discutidos os presentes autos de recurso ordinário, oriundos da 5ª Vara do Trabalho de São Luís/MA, em que figura como recorrente RAPIDÃO COMETALOGÍSTICAE TRANSPORTE S.A. e como recorrido xxxxx, acordam os desembargadores da 1ª Turma do Tribunal Regional do Trabalho da 16ª Região, por unanimidade, conhecer do recurso e, no mérito, negar-lhe provimento, nos termos deste voto.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.6:acordao:2015-11-19;00008058020145010301', 'ACÓRDÃO TRT 1ª  / 6ª Turma / 0000805-80.2014.5.01.0301 - DOERJ 19-11-2015', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.6:acordao:2015-11-19;00008058020145010301', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2015-11-19', NULL, 'NORMA COLETIVA APLICÁVEL.  O objeto social da ré define como sua atividade o transporte rodoviáriodecargae operaçãologísticadetransportedecargas, dentre outras, enquadrando-se perfeitamente na categoria representada pelo sindicato patronal que firmou a convenção coletiva juntada às fls. 22/42.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;rio.grande.sul;bento.goncalves:camara.municipal:resolucao:2015-10-28;166', 'RESOLUÇÃO n° 166,  de 28 de Outubro de 2015', 'urn:lex:br;rio.grande.sul;bento.goncalves:camara.municipal:resolucao:2015-10-28;166', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Camara Municipal', '2015-10-28', NULL, 'Concede Diploma de "HONRA AO MÉRITO" conforme Resolução 20/1995, ao SINDIBENTO - Sindicato das Empresas de TransportesdeCargaseLogísticadeBento Gonçalves e Região.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;rio.grande.sul;vespasiano.correa:municipal:lei:2011-04-04;15', 'Lei Municipal nº 15, de 04 de abril de 2011', 'urn:lex:br;rio.grande.sul;vespasiano.correa:municipal:lei:2011-04-04;15', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2011-04-04', NULL, 'Autoriza concessão de uso de imóvel para atividades de organizaçãologísticadetransportedecargae dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;rio.grande.sul;vespasiano.correa:municipal:lei:2019-12-24;1513', 'Lei Municipal nº 1.513, de 24 de dezembro de 2019', 'urn:lex:br;rio.grande.sul;vespasiano.correa:municipal:lei:2019-12-24;1513', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2019-12-24', NULL, 'Autoriza a prorrogação de concessão de uso de imóvel para funcionamento de indústria e de atividades de organizaçãologísticadetransportedecargae dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:distrital:lei:2003-05-06;3152', 'Lei nº 3152, de 06 de maio de 2003', 'urn:lex:br;distrito.federal:distrital:lei:2003-05-06;3152', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Distrital', '2003-05-06', 'CRIAÇÃO. PROGRAMA. INCENTIVO. IMPLANTAÇÃO. DESENVOLVIMENTO. (PRÓ-DF). TRATAMENTO ESPECIAL. REGIME TRIBUTÁRIO. IMPOSTO SOBRE OPERAÇÕES RELATIVAS À CIRCULAÇÃO DE MERCADORIAS E SOBRE PRESTAÇÕES DE SERVIÇOS DE TRANSPORTE INTERESTADUAL E INTERMUNICIPAL E DE COMUNICAÇÃO (ICMS). IMPOSTO SOBRE SERVIÇOS DE QUALQUER NATUREZA (ISS). OPERAÇÃO. MERCADORIA. PRESTAÇÃO DE SERVIÇO. TRANSPORTEDECARGA. ENCOMENDA. SERVIÇO. COLETA. RECEBIMENTO. ARMAZENAMENTO. MOVIMENTAÇÃO. ESTOQUE. DISTRIBUIÇÃO. ENTREGA. FIXAÇÃO. NORMAS. REQUISITOS. OPÇÃO. CONTRIBUINTE. ESTABELECIMENTO. EMPRESA.', 'Institui o Programa de Estímulo à Implantação e ao Desenvolvimento do SetorLogísticodo Distrito Federal – PRÓ-DF/Logísticoe dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;airr:2013-04-17;340-2010-130-15-0', 'Acórdão do processo Nº AIRR - 340-51.2010.5.15.0130', 'urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;airr:2013-04-17;340-2010-130-15-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2013-04-17', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. CONTRIBUIÇÃO SINDICAL E CONTRIBUIÇÃO ASSISTENCIAL PATRONAL. ENQUADRAMENTO SINDICAL. ATIVIDADE-FIM. MATÉRIA FÁTICA. O Tribunal Regional, à luz dos elementos instrutórios, concluiu que a reclamada não pode ser enquadrada como categoria diferenciada como pretende o sindicato autor, pois está enquadrada na categoria econômica representada pelo Sindicato dos Trabalhadores em Transporte Rodoviário de Campinas e Região, uma vez que tem como objeto societário "a exploração do ramo de transporte intermodaldecargasem geral, armazenamento elogísticadetransportes em seu todo" e, portanto, o transportedecargasem seu todo constitui atividade-fim da agravada, atraindo o enquadramento sindical na regra geral do art. 511, § 2º, e 581, § 2º, da CLT.  Nesse contexto, demandaria o revolvimento de fatos e provas - procedimento vedado a esta Instância Superior, a teor da Súmula 126/TST - examinar a controvérsia sob o prisma trazido na revista. Agravo de instrumento conhecido e não provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;sao.paulo:estadual:lei:2022-12-19;17612', 'Lei nº 17.612, de 19/12/2022', 'urn:lex:br;sao.paulo:estadual:lei:2022-12-19;17612', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '2022-12-19', 'Transporte Ferroviário  ,  Infraestrutura  ,  Secretaria deLogísticae Transportes', 'Dispõe sobre o Subsistema Ferroviário do Estado de São Paulo - SFE/SP, a organização do transporte ferroviáriodecargase de passageiros, o uso da infraestrutura ferroviária e os tipos de outorga para a exploração indireta de ferrovias no âmbito do Estado de São Paulo e dá outras providências', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;rr:2020-10-14;1001874-2018-271-2-0', 'Acórdão do processo Nº RR - 1001874-57.2018.5.02.0271', 'urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;rr:2020-10-14;1001874-2018-271-2-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2020-10-14', NULL, 'I - AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. PROCEDIMENTO SUMARÍSSIMO. LEI Nº 13.467/2017. QUARTA RECLAMADA (GEODISLOGISTICADO BRASIL LTDA.). TRANSCENDÊNCIA. RESPONSABILIDADE SUBSIDIÁRIA. CONTRATODETRANSPORTEDECARGA. Há transcendência política quando se constata em exame preliminar o desrespeito da instância recorrida à jurisprudência do TST. RESPONSABILIDADE SUBSIDIÁRIA. CONTRATO DE TRANSPORTEDECARGA. QUARTA RECLAMADA (GEODISLOGISTICADO BRASIL LTDA.). 1 -  Atendidos os requisitos da Lei nº 13.015/2014. 2 -  Aconselhável o provimento do agravo de instrumento, por aparente má aplicação da Súmula nº 331, IV, do TST, para determinar o processamento do recurso de revista. 3 -  Agravo de instrumento a que se dá provimento. II - RECURSO DE REVISTA. PROCEDIMENTO SUMARÍSSIMO. LEI Nº 13.467/2017. QUARTA RECLAMADA (GEODISLOGISTICADO BRASIL LTDA.). RESPONSABILIDADE SUBSIDIÁRIA. CONTRATODETRANSPORTEDECARGA. 1 -  Atendidos os requisitos da Lei nº 13.015/2014. 2 - O contrato de transporte é um pacto tipicamente civil, regulado pelos arts. 730 e seguintes do Código Civil. 3 -  No caso, conforme consta do acórdão do TRT, as reclamadas firmaram contrato de transporte de mercadorias. 4 - Ademais, o acórdão regional não aponta nenhum fato que demonstre o desvirtuamento do contrato de transporte, como a ingerência da recorrente ou a subordinação direta do reclamante. 5 - Recurso de revista a que se dá provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.6:acordao:2010-06-16;01631001520065010020', 'ACÓRDÃO TRT 1ª  / 6ª Turma / 0163100-15.2006.5.01.0020 - DOERJ 16-06-2010', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.6:acordao:2010-06-16;01631001520065010020', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2010-06-16', NULL, 'RELAÇÃO DE  EMPREGO. CONFIGURAÇÃO.  GESTÃO DE CONTRATO DE MOVIMENTAÇÃODECARGALOGÍSTICA. Se o trabalhador presta serviços relacionados à atividade-fim do empregador e, ainda, de forma pessoal, habitual, subordinada e remunerada, impõe-se-lhe o reconhecimento do liame de emprego, nos moldes do art. 3º da CLT. Apelo patronal improvido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;airr:2023-09-06;21071-2017-611-4-0', 'Acórdão do processo Nº AIRR - 21071-42.2017.5.04.0611', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;airr:2023-09-06;21071-2017-611-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2023-09-06', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA INTERPOSTO NA ÉGIDE DA LEI N.º 13.015/2014. REPRESENTAÇÃO SINDICAL. MOTORISTADECARGA. REEXAME FÁTICO-PROBATÓRIO. INCIDÊNCIA DA SÚMULA 126/TST. Hipótese em que o Tribunal Regional manteve a sentença no sentido de que o sindicato autor não possui a representação sindical dos empregados motoristas que trabalham na reclamada. Assentou ser incontroverso que a empresa reclamada labora com a prestação de serviços em engenharia de concreto, possuindo frota própria com empregados motoristas e ajudantes de motoristas para o transportedecargas, bem como que já recolhe contribuições para o "Sindicato dos Trabalhadores em Transportes RodoviáriosdeCargado Noroeste do Estado do Rio Grande do Sul" com o qual, inclusive, o Sindicato das Empresas de TransportedeCargaeLogísticano Estado do RS - SETERGS já firmou convenção coletiva. Registrou que o sindicato autor não acostou aos autos as normas coletivas da categoria a qual representa, a fim de possibilitar análise quanto à relevância e impacto do critériode"cargaspróprias" sobre a categoria de trabalhadores em voga. Adotar entendimento em sentido oposto implicaria o revolvimento de fatos e provas, inadmissível em sede de recurso de revista, conforme a Súmula 126/TST. Agravo de instrumento a que se nega provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;rio.grande.sul;santa.rosa:municipal:lei:2020-12-30;5617', 'Lei Municipal nº 5.617, de 30 de dezembro de 2020', 'urn:lex:br;rio.grande.sul;santa.rosa:municipal:lei:2020-12-30;5617', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2020-12-30', NULL, 'Autoriza o Município de Santa Rosa, por intermédio do Poder Executivo, a efetivar a concessão do direito real de uso com encargos e promessa de doação de bens públicos imóveis classificados como dominicais e integrantes de seu patrimônio disponível em favor das pessoas jurídicas beneficiárias Arend E Cia Ltda., Bamberg Comércio e Representações Ltda., Cristiano Soares dos Santos ¿ EIRELI, Dall Ago E Andrade Ltda., Edlog Transportes eLogísticaLtda., Enio Genz ¿ EIRELI,  Extingases Comércio e Transporte de Gases Ltda., Gambini Distribuidora de Alimentos Ltda., Hemsing Kubitz E Cia. Ltda., J.L. dos Santos E Cia. Ltda., Leonardo Schnepfleitner, Nilen Transportes Ltda., Rodrigo Almeida Genz, Sindicato das Empresas de TransportedeCargaseLogísticadeSanta Rosa, Transportadora Ajor Ltda., Transportes MDFS Ltda., Três Marcos - Transportes e Agricultura Ltda., e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.9:acordao:2017-01-24;00114234820155010431', 'ACÓRDÃO TRT 1ª  / 9ª Turma / 0011423-48.2015.5.01.0431 - DOERJ 24-01-2017', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.9:acordao:2017-01-24;00114234820155010431', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2017-01-24', NULL, 'O instrumento normativo trazido aos autos, no qual o Autor fundamenta suas pretensões, foi entabulado entre o Sindicato dos Empregados Motociclistas no Estado do Rio de Janeiro e o Sindicato das Empresas do Transporte RodoviáriodeCargaseLogísticado Rio de Janeiro, sendo certo que o empregador não se fez representar no referido ajuste, porquanto, consoante sua própria razão social denuncia, explora atividade ligada ao "ramo de farmácia e perfumaria" (Contrato Social, Id. c832a83 - Pág. 1), ao passo que o Sindicato patronal signatário do referido instrumento normativo representa "as empresas de transporte rodoviáriodecargas".', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2015-06-17;27740-2009-19-11-0', 'Acórdão do processo Nº RR - 27740-30.2009.5.11.0019', 'urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2015-06-17;27740-2009-19-11-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2015-06-17', NULL, 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. EXECUÇÃO. ACORDO EXTRAJUDICIAL HOMOLOGADO JUDICIALMENTE. DESCUMPRIMENTO. MULTA. DECISÃO REGIONAL PAUTADA NA INEXIGIBILIDADE DO TÍTULO. COISA JULGADA. OCORRÊNCIA. ART. 5º,XXXVI, DA CF. VIOLAÇÃO CARACTERIZADA. O e. Tribunal deixa registrado que "A discussão dos autos trava-se em derredor da contratação dos 22 motoristas listados em auto de infração lavrado pela fiscalização do trabalho, que segundo o MPT atestaria o descumprimento do acordo firmado nos autos da presente execução".  Consignou, ainda que, "Em verdade, nem o TAC no 192/2 004 nem o novo acordo que o substituiu referem-se explicitamente à proibição de terceirizar os serviços de transporte rodoviário na cidade de Manaus para a coleta e entregadecarga. A abstenção para contratar trabalhadores terceirizados dizia respeito ao exercício de atividade-fim da empresa". Nesse contexto, tratando-se de trabalhadores sem registro na CTPS, que exercem atividade de motorista, a ensejar a ilação de que se trata de trabalhador ligado à atividade-fim da reclamada, empresa de transportedecarga, merece ser processado o recurso de revista, por violação do art. 5º, XXXVI, da CF, ante o aparente descumprimento do acordo judicial homologado. Agravo de instrumento conhecido e provido. RECURSO DE REVISTA. EXECUÇÃO. ACORDO EXTRAJUDICIAL HOMOLOGADO JUDICIALMENTE. DESCUMPRIMENTO. MULTA. DECISÃO REGIONAL PAUTADA NA INEXIGIBILIDADE DO TÍTULO. COISA JULGADA. OCORRÊNCIA. ART. 5º,XXXVI, DA CF.VIOLAÇÃO CARACTERIZADA. 1. O e. Tribunal deixa registrado que "A discussão dos autos trava-se em derredor da contratação dos 22 motoristas listados em auto de infração lavrado pela fiscalização do trabalho, que segundo o MPT atestaria o descumprimento do acordo firmado nos autos da presente execução. Segundo a empresa, esses motoristas estariam executando serviços de entrega rápida, atividade que é terceirizada, posto que os serviços de distribuição elogísticanão estão ligados à sua atividade-fim, pois não opera o transporte rodoviário municipal. Em verdade, nem o TAC nº 192/2 004 nem o novo acordo que o substituiu referem-se explicitamente à proibição de terceirizar os serviços de transporte rodoviário na cidade de Manaus para a coleta e entregadecarga. A abstenção para contratar trabalhadores terceirizados dizia respeito ao exercício de atividade-fim da empresa. Ao que parece, a agravante tem por atividade-fim o transporte rodoviário intermunicipal e interestadual e multimodaldecargas(cláusula segunda do contrato social), com CNAE da atividade principal 49.30-2/02, enquanto o transporte rodoviáriodecargasmunicipal  (distribuição elogística) tem o CNAE de nº 49.30-2/01. Apesar de não ter sido juntado o contrato social nem o CNPJ, inclusive das empresas contratadas, o exequente não se manifestou sobre tal questão. O título executivo foi silente quanto a motoristas-carreteiros que operam no transportedecargaem Manaus. (...). Assim, subsistem controvérsias acerca do Auto de infração no tocante ao vínculo empregatício dos 22 motoristas-carreteiros nele listados. Inclusive está em curso processo administrativo para anulá-lo (fls. 278/283), não se tendo notícia sobre a sua conclusão". Entendeu, por isso, que "O fato que respalda a execução consistente na alegação de estar a empresa contratando terceirizados para sua atividade-fim não se reveste de certeza e exigibilidade, como estabelece o art. 586 do CPC" e extinguiu a execução, com base no artigo 267, IV, do CPC. 2. Diante desse quadro fático, verifica-se que a reclamada tem por atividade o transportedecargas, razão porque a contratação de motoristas-carreteiros teria por objetivo a realização de sua atividade-fim. Assim, a diferenciação que a reclamada pretende, ao sustentar que teria por atividade-fim apenas o transporte intermunicipal e interestadual, pelo enfoque do critério geográfico, tão somente, não se sustenta, pois o que se leva em conta é a atividade desenvolvida que, no caso, é a de transportedecarga. Esclareça que se eventualmente a reclamada tem por atividade principal e predominante o transporte interestadual e intermunicipal, e em menor escala, o transporte intramunicipal, tal fato não torna aquele tipo de transporte em atividade-fim, de modo a excluir do conceito o transportedecargarealizado dentro do Município. 3. Nesse contexto, a decisão regional ao deixar de reconhecer a violação da coisa julgada, visto que claro e explícito o descumprimento do acordo homologado judicialmente, incorreu em ofensa ao art. 5º, XXXVI, da CF. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;ag:2023-03-15;4000-2009-751-4-0', 'Acórdão do processo Nº Ag-AIRR - 4000-73.2009.5.04.0751', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;ag:2023-03-15;4000-2009-751-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ag', '2023-03-15', NULL, 'I -  AGRAVO DO EXECUTADO PAULO DE MELO. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. EXECUÇÃO. ART. 896, §1º-A, I, DA CLT. FALTA DE TRANSCRIÇÃO DO TRECHO DA DECISÃO REGIONAL QUE CONSUBSTANCIA O PREQUESTIONAMENTO DA CONTROVÉRSIA. AUSÊNCIA DE IMPUGNAÇÃO ESPECÍFICA. SÚMULA 422, I, DO TST. Como restou detalhado na decisão em que denegado seguimento ao agravo de instrumento, o recurso de revista encontra óbice no art. 896, §1º-A, I, CLT. Todavia, a parte, ao insurgir-se contra a decisão agravada, limita-se a renovar as questões de fundo, expostas na minuta de agravo de instrumento. A agravante, portanto, não cuidou de atacar especificamente os fundamentos da decisão agravada, atraindo a incidência do item I da Súmula 422/TST. Agravo não conhecido. II -  AGRAVO DO EXECUTADO UMBERTO PEREIRA. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA.  NEGATIVA DE PRESTAÇÃO JURISDICIONAL. Dos argumentos lançados pelo TRT, tem-se que a decisão regional, ainda que contrária aos interesses da recorrente, foi devidamente fundamentada, o que não acarreta sua nulidade, conforme suscitado. Agravo não provido. VÍCIO DE CITAÇÃO. NÃO CONHECIMENTO DO AGRAVO DE PETIÇÃO. APLICAÇÃO DA LEGISLAÇÃO PROCESSUAL INFRACONSTITUCIONAL DE REGÊNCIA. INVIABILIDADE DE REEXAME EM SEDE DE EXECUÇÃO. Na forma estabelecida pelo § 2º do artigo 896 da CLT e pela Súmula 266 do TST, o cabimento do recurso de revista em execução de sentença está restrito às hipóteses de ofensa direta e literal de norma da Constituição da República. Na situação dos autos, não procede a alegação de ofensa aos dispositivos da Constituição Federal apontados, quando a lide está adstrita ao exame de legislação processual infraconstitucional de regência da matéria, circunstância que impossibilita a configuração de violação literal e direta à norma constitucional. Óbices das Súmulas 266 do TST e 636 do STF. Agravo não provido. III -  AGRAVOS DAS EXECUTADAS EXPRESSO CASCAVEL E VIAÇÃO XAVANTE LTDA. AGRAVOS DE INSTRUMENTO. RECURSOS DE REVISTA. GRUPO ECONÔMICO. RESPONSABILIDADE SOLIDÁRIA. COISA JULGADA. MATÉRIA COMUM. ANÁLISE CONJUNTA. Na situação dos autos, o Tribunal Regional registrou que "a controvérsia acerca da responsabilidade das executadas Viação Xavante Ltda. e Expresso Cascavel TransportedeCargaseLogísticaLtda. pela dívida em execução já foi objeto de decisão trânsita proferida por esta Seção Especializada, na qual é [...] reconhecida a formação de grupo econômico entre todas as demais empresas executadas, quais sejam, Expresso Vitória do Xingu Ltda., Viação Nossa Senhora Medianeira Ltda., Viação Viagem Com Jesus, Expresso Cascavel TransportedeCargaseLogisticaLtda., Rápido Marajó Ltda., Viação Xavante Ltda. e Transportes Medianeira Express Ltda. (acórdão Id 0a6e352)". (Destaques do original). O Colegiado ressaltou que "as razões recursais das executadas Viação Xavante Ltda. e Expresso Cascavel TransportedeCargaseLogísticaLtda. - EPP são tentativa das agravantes de rediscutirem matéria passada em julgado, o que não é mais possível nesse momento processual, sob pena de afronta à coisa julgada, cujo respeito é garantido pelo art. 5º, XXXVI, da Constituição Federal, pelo art. 879, § 1º, da CLT e pelo art. 502 do CPC". No caso, o que se observa é que o entendimento adotado pelo Tribunal Regional é fruto do estrito cumprimento dos termos da decisão transitada em julgado, circunstância que impossibilita a configuração de ofensa literal e direta ao art. 5º, XXXVI, da Constituição Federal, e aos demais dispositivos constitucionais indicados. Agravos não providos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;ro:2015-06-08;20484-2010-0-4-0', 'Acórdão do processo Nº RO - 20484-54.2010.5.04.0000', 'urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;ro:2015-06-08;20484-2010-0-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ro', '2015-06-08', NULL, 'RECURSO ORDINÁRIO EM DISSÍDIO COLETIVO DE NATUREZA ECONÔMICA, INTERPOSTO PELO SUSCITADO, SINDICATO DAS EMPRESAS DE TRANSPORTESDECARGAELOGÍSTICANO ESTADO DO RIO GRANDE DO SUL. AUSÊNCIA DE COMUM ACORDO. ART. 114, § 2º, DA CONSTITUIÇÃO FEDERAL. EXTINÇÃO DO PROCESSO, SEM RESOLUÇÃO DE MÉRITO. O entendimento pacífico desta Corte é o de que o comum acordo, exigência trazida pelo art. 114, § 2º, da Constituição Federal para o ajuizamento do dissídio coletivo de natureza econômica, é pressuposto de constituição e desenvolvimento válido e regular do processo e que, embora idealmente devesse ser materializado na forma de petição conjunta da representação, é interpretado de maneira mais flexível, no sentido de se admitir a concordância tácita na instauração da instância, desde que não haja a oposição expressa do suscitado, na contestação. In casu, o Sindicato das Empresas de TransportesdeCargaeLogísticano Estado do Rio Grande do Sul, em sua defesa, destacou, expressamente, a ausência do comum acordo no ajuizamento do dissídio coletivo e apontou a falta do referido pressuposto processual como causa extintiva do processo, reiterando sua discordância nas razões do recurso ordinário. Nesse contexto, não cabe a esta Justiça Especializada o exercício espontâneo da jurisdição contra a vontade manifesta da parte de se opor ao ajuizamento da ação, respaldada na Constituição Federal. Reforma-se, pois, a decisão regional para julgar extinto o processo, sem resolução de mérito, nos termos dos arts. 114, § 2º, da CF e 267, IV, do CPC, ficando ressalvadas, contudo, as situações fáticas já constituídas, a teor do que dispõe o art. 6º, § 3º, da Lei nº 4725/1965. Processo extinto sem resolução de mérito, pela falta de comum acordo.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;ro:2013-12-09;7357-2010-0-2-0', 'Acórdão do processo Nº RO - 7357-06.2010.5.02.0000', 'urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;ro:2013-12-09;7357-2010-0-2-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ro', '2013-12-09', NULL, 'RECURSOS ORDINÁRIOS INTERPOSTOS PELO SINDICATO DOS TRABALHADORES EM EMPRESAS DE TRANSPORTES RODOVIÁRIOSDECARGASSECAS E MOLHADAS, EMPRESAS DELOGÍSTICANO RAMODETRANSPORTEDECARGASDE SÃO PAULO E ITAPECERICA DA SERRA E PELO SINDICATO DOS MOTORISTAS E TRABALHADORES DO RAMO DE TRANSPORTES DE EMPRESASDECARGASSECAS E MOLHADAS, E DIFERENCIADOS DO COMÉRCIO, INDÚSTRIA, GÁS, ESTABELECIMENTOS BANCÁRIOS E FINANCEIROS DE OSASCO E REGIÃO. ANÁLISE CONJUNTA - MATÉRIA COMUM. A entidade sindical representante da classe profissional diferenciada é legitima para buscar melhores e mais adequadas condições de trabalho, que atendam às peculiaridades da profissão. Na outra ponta, qualquer integrante da categoria econômica que utilize a mão de obra específica desses trabalhadores, ou que, ao menos, potencialmente possa vir a utilizá-la, é legítimo para figurar no polo passivo da demanda coletiva, independentemente do ramo da atividade econômica preponderante da empresa. No caso dos autos, os suscitantes pretendem obter instrumento normativo heterônomo que atenda tão somente às reivindicações da categoria profissional dos motoristas por eles representada, sem que ocorra invasão na área de atuação do sindicado opoente. Forçoso reconhecer a legitimidade dos suscitantes para o ajuizamento deste dissídio coletivo em nome e em defesa dos interesses da categoria profissional dos motoristas. Recursos ordinários providos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;ro:2014-06-09;9267-2011-0-4-0', 'Acórdão do processo Nº RO - 9267-77.2011.5.04.0000', 'urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;ro:2014-06-09;9267-2011-0-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ro', '2014-06-09', NULL, '1) RECURSO ORDINÁRIO EM DISSÍDIO COLETIVO INTERPOSTO PELA FEDERAÇÃO DAS EMPRESAS DELOGÍSTICAEDETRANSPORTEDECARGASNO RIO GRANDE DO SUL - FETRANSUL LEGITIMIDADE PASSIVA AD CAUSAM. A teor dos arts. 8º, VI, da Constituição Federal e 611, e parágrafos, da CLT, a entidade que detém poderes para a negociação coletiva, quer referente à categoria profissional, quer à econômica, é o sindicato. Assim, a legitimidade das Federações ocorre em caráter residual, ou seja, quando inexistente bases organizadas sindicais no âmbito do primeiro grau de representação. Ocorre que, in casu, existe sindicato que representa as empresas delogísticaedetransportedecargasno Estado do Rio Grande do Sul, que, inclusive, consta como suscitado neste dissídio, pelo que se dá provimento ao recurso para declarar a ilegitimidade ad causam da Federação suscitada, extinguindo-se o processo, sem resolução de mérito, nos termos do art. 267, VI, do CPC. Processo extinto, sem resolução de mérito. 2) RECURSO ORDINÁRIO EM DISSÍDIO COLETIVO INTERPOSTO PELO SINDICATO DAS EMPRESAS DE TRANSPORTEDECARGAELOGÍSTICANO ESTADO DO RIO GRANDE DO SUL - SETCERGS. AUSÊNCIA DE COMUM ACORDO. ART. 114, § 2º, DA CONSTITUIÇÃO FEDERAL. JURISPRUDÊNCIA DO TST. EXTINÇÃO DO PROCESSO, SEM RESOLUÇÃO DE MÉRITO. O entendimento que prevalece nesta Seção Especializada é o de que o comum acordo (art. 114, § 2º, da CF) é pressuposto de constituição e de desenvolvimento válido e regular do processo, específico para o ajuizamento do dissídio coletivo de natureza econômica. Entretanto, o comum acordo é interpretado de maneira flexível por esta Corte, no sentido de se admitir a concordância tácita na instauração da instância, desde que não haja a oposição expressa do suscitado, na contestação. Ocorre que, in casu, o suscitado SETCERGS, em sede de defesa, expressamente afirmou não concordar com o ajuizamento do dissídio coletivo e apontou a ausência de comum acordo como causa extintiva do feito, reiterando suas alegações nas razões de seu recurso ordinário. Não cabe, pois, a esta Justiça especializada o exercício espontâneo da jurisdição contra a vontade manifesta da parte de se opor ao ajuizamento do dissídio coletivo, respaldada na Constituição Federal. Reforma-se, pois, a decisão regional e julga-se extinto o processo, sem resolução de mérito, nos termos dos arts. 114, § 2º, da CF e 267, IV, do CPC, ressalvadas, contudo, as situações fáticas já constituídas, a teor do que dispõe o art. 6º, § 3º, da Lei nº 4725/1965. Processo extinto sem resolução de mérito, pela falta de comum acordo.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.24:tribunal.regional.trabalho;tribunal.pleno:acordao:2011-01-27;0125000-26.2008.5.24.0005', 'ACÓRDÃO TRT 24ª / Tribunal Pleno / RO.1 0125000-26.2008.5.24.0005', 'urn:lex:br;justica.trabalho;regiao.24:tribunal.regional.trabalho;tribunal.pleno:acordao:2011-01-27;0125000-26.2008.5.24.0005', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 24', 'Tribunal Regional Trabalho', 'Acordao', '2011-01-27', 'TERCEIRIZAÇÃO', 'ECT - TERCEIRIZAÇÃO LÍCITA - TRANSPORTE DE CORRESPONDÊNCIAS ECARGASPOSTAIS. É lícita a terceirização da árealogísticada Empresa Brasileira de Correios e Telégrafos - ECT -, a qual abarca o transporte internodecargaspostais entre as unidades de correio e não o destinatário final. Recurso não provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.1:acordao:2012-07-25;00953006920095010341', 'ACÓRDÃO TRT 1ª  / 1ª Turma / 0095300-69.2009.5.01.0341 - DOERJ 25-07-2012', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.1:acordao:2012-07-25;00953006920095010341', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2012-07-25', NULL, 'ENQUADRAMENTO SINDICAL -  ATIVIDADE PREPONDERANTE DA EMPRESA- O enquadramento sindical é feito levando-se em conta a atividade preponderante do empregador, à exceção dos integrantes de categorias diferenciadas. Em que pese  às argumentações defensivas da reclamada, o objeto social da reclamada consiste não só em -locação de máquinas e equipamentos de transporte rodoviáriosdecargas,logística,- mas também,  em -transportes e remoções em geral-. Tal diversidade no perfil da atividade econômica da empresa já submete a reclamada às Convenções Coletivas celebradas  entre os sindicatos da respectiva categoria profissional e econômica. Recurso que se dá provimento para deferir ao autor  as diferenças salariais oriundas do enquadramento sindical.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.10:acordao:2023-07-11;0010186-55.2022.5.03.0179', 'Acórdão PJe TRT 3ª / Decima Turma / 2023-07-11', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.10:acordao:2023-07-11;0010186-55.2022.5.03.0179', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2023-07-11', NULL, 'MOTORISTA. JORNADA. TURNOS. HORÁRIOS VARIADOS. O STF, em 02 de junho de 2022, julgou o mérito do tema 1046, relativo ao ARE 1121633, fixando tese expressa sobre a constitucionalidade e validade dos acordos e convenções coletivos. Assim, se a norma coletiva estabelece escala de trabalho com alternância de horários, em razão da natureza do serviço e das condições especiais de trabalho às quais são submetidos estritamente os motoristas de ônibus, não pode ser desprezada a previsão normativa, para invalidar o sistema de compensação ali previsto. Como sempre entendeu este Relator, não se verifica alternância estanque de turnos de trabalho dos motoristas, mas sim variação de horários, dada à peculiaridade da principal atividade econômica desenvolvida pelas empresas de transportedecarga/logística.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2018-09-26;0010802-84.2018.5.03.0077', 'Acórdão PJe TRT 3ª / Nona Turma / 2018-09-26', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2018-09-26;0010802-84.2018.5.03.0077', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2018-09-26', 'TERCEIRIZAÇÃO - CARACTERIZAÇÃO', 'TRANSPORTE RODOVIÁRIODECARGASPOR CONTA DE TERCEIROS. NATUREZA DA CONTRATAÇÃO ENTRE EMPRESAS. INEXISTÊNCIA DE TERCEIRIZAÇÃO DE SERVIÇOS. Não se há falar em terceirização de serviços quando uma empresa produtora de determinado produto ajusta contrato rodoviário de transporte deste com empresa especializada em transporte oulogística, uma vez que a atividade econômicadetransporte rodoviáriodecargas, em vias públicas, por conta de terceiros e mediante remuneração, é de natureza civil e comercial.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2018-11-23;0010420-91.2018.5.03.0077', 'Acórdão PJe TRT 3ª / Nona Turma / 2018-11-23', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2018-11-23;0010420-91.2018.5.03.0077', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2018-11-23', NULL, 'TRANSPORTE RODOVIÁRIODECARGASPOR CONTA DE TERCEIROS. NATUREZA DA CONTRATAÇÃO ENTRE EMPRESAS. INEXISTÊNCIA DE TERCEIRIZAÇÃO DE SERVIÇOS. Não se há falar em terceirização de serviços quando uma empresa produtora de determinado produto ajusta contrato rodoviário de transporte deste com empresa especializada em transporte oulogística, uma vez que a atividade econômicadetransporte rodoviáriodecargas, em vias públicas, por conta de terceiros e mediante remuneração, é de natureza civil e comercial.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2019-07-24;0011117-46.2018.5.03.0099', 'Acórdão PJe TRT 3ª / Nona Turma / 2019-07-24', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2019-07-24;0011117-46.2018.5.03.0099', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2019-07-24', NULL, 'TRANSPORTE RODOVIÁRIODECARGASPOR CONTA DE TERCEIROS. NATUREZA DA CONTRATAÇÃO ENTRE EMPRESAS. INEXISTÊNCIA DE TERCEIRIZAÇÃO DE SERVIÇOS. Não se há falar em terceirização de serviços quando uma empresa que comercializa determinados produtos ajusta contrato rodoviário de transporte destes com empresa especializada em transporte oulogística, uma vez que a atividade econômicadetransporte rodoviáriodecargas, em vias públicas, por conta de terceiros e mediante remuneração, é de natureza civil e comercial.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2016-03-31;00103953620155010531', 'ACÓRDÃO TRT 1ª  / 7ª Turma / 0010395-36.2015.5.01.0531 - DEJT 31-03-2016', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2016-03-31;00103953620155010531', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2016-03-31', NULL, 'NORMAS COLETIVAS. APLICAÇÃO. REPRESENTATIVIDADE SINDICAL. 
1. Como método de adequação, o critério geral de enquadramento dos trabalhadores, atualmente hegemônico no país, baseia-se na atividade preponderante do empregador. Admite-se, contudo, a estruturação de sindicatos por categorias diferenciadas, caso em que será levado em consideração o próprio labor dos empregados, ou seja, o ofício por eles exercido, independentemente da atividade principal do empregador.
2. Na hipótese,a documentação trazida pelo réu não foi atualizada, não espelhando a amplitude de atividades por ele desempenhadas.
3. Logo, não há como se afastar a aplicação das normas celebradas entre o SINDICATO DAS EMPRESAS DO TRANSPORTE RODOVIÁRIODECARGASELOGÍSTICADO RIO DE JANEIRO e o SINDICATO DOS TRABALHADORES RODOVIÁRIOSDECARGASE PASSAGEIROS DE TERESÓPOLIS E GUAPIMIRIM, este último, incontroversamente, representante da categoria profissional diferenciada em que se encontra o autor.
4. Isso porque, não haveria como se exigir a presença de todas as entidades sindicais patronais que contratam empregados pertencentes à referida categoria diferenciada, por absoluta impossibilidade material, não se podendo desprezar que, na hipótese, são as condições profissionais de trabalho do empregado que revelam seu enquadramento.
5. Assim considerando, resta patente que as convenções coletivas trazidas com a inicial são plenamente aplicáveis ao demandante, não havendo que se falar em observância do entendimento contido na Súmula nº 374 do C. TST, muito menos que se exigir a intervenção da demandada nas negociações entabuladas, para que sejam aplicáveis à relação mantida pelo trabalhador com a empresa as disposições delas constantes. Recurso autoral conhecido e parcialmente provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2022-05-04;10268-2015-129-15-0', 'Acórdão do processo Nº RR - 10268-53.2015.5.15.0129', 'urn:lex:br:tribunal.superior.trabalho;turma.1:acordao;rr:2022-05-04;10268-2015-129-15-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2022-05-04', NULL, 'AGRAVO. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. RESPONSABILIDADE SUBSIDIÁRIA. NÃO CONFIGURAÇÃO. CONTRATO DE TRANSPORTEDECARGAS. TRANSCENDÊNCIA POLÍTICA CARACTERIZADA. Ante as razões apresentadas pela agravante, há de ser afastado o óbice oposto na decisão agravada. Agravo conhecido e provido. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. RESPONSABILIDADE SUBSIDIÁRIA. NÃO CONFIGURAÇÃO. CONTRATO DE TRANSPORTEDECARGAS. 1. Não obstante o reconhecimento de que a empregadora do reclamante (MelgesLogística) e a Seara Alimentos, que integra o grupo econômico da agravante (JBS S.A.), firmaram contrato de transportedecargas, o Tribunal de origem concluiu pela responsabilidade subsidiária dessa última empresa. 2. Aparente má aplicação da Súmula 331, IV, do TST, a ensejar o provimento do agravo de instrumento. Agravo de instrumento conhecido e provido. RECURSO DE REVISTA. RESPONSABILIDADE SUBSIDIÁRIA. NÃO CONFIGURAÇÃO. CONTRATO DE TRANSPORTEDECARGAS. 1. A teor do acórdão regional, a empregadora do reclamante (MelgesLogística) e a Seara Alimentos, que integra o grupo econômico da agravante (JBS S.A.), firmaram contrato de transportedecargas, que ostenta natureza comercial. 2. Assim, e não havendo registro de fraude no acordão regional, não há como atribuir à JBS S.A. responsabilidade subsidiária pelos créditos trabalhistas deferidos.  Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;rodc:2007-05-10;2010000-2006-0-2-0', 'Acórdão do processo Nº RODC - 2010000-39.2006.5.02.0000', 'urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;rodc:2007-05-10;2010000-2006-0-2-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rodc', '2007-05-10', NULL, '1 - RECURSO DO SINDICATO DOS TRABALHADORES EM EMPRESAS DE TRANSPORTES RODOVIÁRIOSDECARGASSECAS E MOLHADAS, EMPRESAS DELOGÍSTICANO RAMODETRANSPORTEDECARGASDE SÃO PAULO E ITAPECERICA DA SERRA. I - Recurso provido para homologar as cláusulas 5ª, 6ª, 14ª, 15ª, 31ª e 32ª. II - Recurso provido parcialmente para homologar a cláusula 8ª sem a locução ¿nem ser objeto de postulação¿. III - Recurso desprovido em relação à cláusula 35ª - Contribuição Assistencial, face a proibição da reformatio in pejus. 2 - RECURSO DO SINDICATO DAS EMPRESAS DE TRANSPORTESDECARGADE SÃO PAULO E REGIÃO.  PRELIMINAR DE NEGATIVA DE PRESTAÇÃO JURISDICIONAL. I - Mesmo que eventualmente não tenha o Regional se pronunciado sobre as questões enfocadas no recurso ordinário, o amplo efeito devolutivo imprimido ao apelo abre ensejo para que o TST, como juízo de segundo grau, se manifeste sobre todas elas, sem receio de eventual supressão do grau de jurisdição inferior, por conta da aplicação subsidiaria do art. 515, § 1º do CPC, por ser o recurso ordinário mero sucedâneo da apelação cível. II - Nesse sentido consolidou-se a jurisprudência desta Corte por meio da Súmula 393.  Preliminar rejeitada.  DAS CLÁUSULAS DO ANEXO DO ACORDO COLETIVO DE TRABALHO. I - Relativamente ao parágrafo único da cláusula primeira, não se vislumbra a pretensa vulneração do princípio da inderrogabilidade da jurisdição. Ao contrário, reiterando o que prescreve o art. 625-D da CLT a cláusula se limita a erigir a tentativa de conciliação no âmbito das Comissões de Conciliação Prévia em pressuposto de válida constituição e desenvolvimento do processo de que trata o inciso IV do art. 267 do CPC. II - Já no que concerne as demais cláusulas, ainda que haja previsão legal, convém homologá-las por conta do seu sentido pedagógico. Recurso provido para homologar as cláusulas em sua integralidade, ficando prejudicado o exame das cláusulas 5ª, 6ª, 8ª, 14ª, 15ª, 31ª, 32ª e 35ª, já apreciadas quando do julgamento do recurso do sindicato profissional.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2016-11-09;1783-2010-261-1-0', 'Acórdão do processo Nº AIRR - 1783-22.2010.5.01.0261', 'urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;airr:2016-11-09;1783-2010-261-1-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '2016-11-09', NULL, 'AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA - PROCESSO ANTERIOR A VIGÊNCIA DA LEI Nº 13.015/2014 -  MULTA DE 1% ESTABELECIDA NO ART. 538 DO CPC. A multa prevista no art. 538, parágrafo único, do CPC é faculdade conferida ao Juiz que, verificando o intuito de protelação do feito, dela se utilizará. Se constatado que nada justificaria a oposição dos embargos de declaração, a imposição da multa é mera consequência. À parte foi garantido o direito ao devido processo legal, à ampla defesa e ao contraditório, entretanto, tais direitos devem ser exercidos na forma, nos limites e nas condições estabelecidos em lei. APLICAÇÃO CONVENÇÃO COLETIVA - DIFERENÇAS DO PISO DA CATEGORIA - TICKET-REFEIÇÃO - ABONO PECUNIÁRIO. Diante do enquadramento fático esposado na decisão recorrida, na qual se concluiu que a atividade preponderante da reclamada é o transporte rodoviáriodecargas, sendo o sindicato representativo da sua categoria o Sindicato das Empresas do Transporte RodoviáriodeCargaseLogísticado Rio de Janeiro, a sua reversão, como pretendida pela recorrente, só se viabilizaria mediante o revolvimento de fatos e provas, procedimento defeso nesta superior instância, conforme estabelece a Súmula nº 126 do TST. Agravo de instrumento desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2025-02-20;0010380-72.2024.5.03.0086', 'Acórdão PJe TRT 3ª / Quarta Turma / 2025-02-20', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2025-02-20;0010380-72.2024.5.03.0086', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2025-02-20', NULL, 'Trata-se de embargos de declaração opostos pela reclamada, EXPRESSO IDEAL,CARGAS, ENCOMENDAS ELOGÍSTICALTDA - ME, a qual requer sejam sanados supostos vícios no acórdão proferido por esta Eg.Turma.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;rr:2021-04-07;20557-2015-281-4-0', 'Acórdão do processo Nº RR - 20557-80.2015.5.04.0281', 'urn:lex:br:tribunal.superior.trabalho;turma.8:acordao;rr:2021-04-07;20557-2015-281-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2021-04-07', NULL, 'A) AGRAVOS DE INSTRUMENTO EM RECURSOS DE REVISTA DAS SEGUNDA E TERCEIRA RECLAMADAS, BRADOLOGÍSTICAS.A. E TIC TRANSPORTES LTDA. MATÉRIA COMUM. ANÁLISE CONJUNTA. RESPONSABILIDADE SUBSIDIÁRIA. TRANSPORTEDECARGAS. INAPLICABILIDADE DA SÚMULA Nº 331 DO TST. Diante da possível contrariedade à Súmula nº 331, IV, do TST, dá-se provimento aos agravos de instrumento para determinar o processamento dos recursos de revista. Agravos de instrumento conhecidos e providos. B) RECURSOS DE REVISTA DAS SEGUNDA E TERCEIRA RECLAMADAS, BRADOLOGÍSTICAS.A. E TIC TRANSPORTES LTDA. MATÉRIA COMUM. ANÁLISE CONJUNTA. RESPONSABILIDADE SUBSIDIÁRIA. TRANSPORTEDECARGAS. INAPLICABILIDADE DA SÚMULA Nº 331 DO TST. Consta do acórdão regional a premissa fática de que as segunda e terceira reclamadas celebraram contrato comercial para transporte rodoviáriodecargascom a primeira reclamada. Nessa situação, esta Corte Superior tem se manifestado no sentido de inexistir responsabilidade subsidiária, tendo em vista não haver intermediação de mão de obra e tampouco se discutir o direcionamento da atividade contratada, mas os meros efeitos de contrato de natureza civil, in casu, prestação de serviço de transportedecargas, sendo indevida a aplicação da diretriz da Súmula nº 331 do TST. Precedentes. Recursos de revista conhecidos e providos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-12-08;2022', 'ACÓRDÃO TCU 2022/2004', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-12-08;2022', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2004-12-08', NULL, 'Representação formulada pelo Ministério Público junto ao TCU. Possíveis irregularidades praticadas na Codeba. Informações apresentadas pelo Consórcio Nacional EADILogísticae Distribuição. Cobrança irregular de taxa adicional, em duplicidade, para movimentaçãodecargasno Porto de Salvador, pela arrendatária - Tecon Salvador S/A. Agravo interposto pela Tecon contra despacho denegatório de pedido de alteraçãodecargado processo para fins de vista na SECEX PR. Conhecimento. Negado provimento. Autorização para acesso aos autos na Sede do Tribunal.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('logística de carga', '2025-07-12 17:38:07', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;roaa:2003-10-09;9759700-2003-900-11-0', 'Acórdão do processo Nº ROAA - 9759700-87.2003.5.11.0900', 'urn:lex:br:tribunal.superior.trabalho;secao.dissidios.coletivos:acordao;roaa:2003-10-09;9759700-2003-900-11-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Roaa', '2003-10-09', NULL, 'NULIDADE DE CLÁUSULAS DE CONVENÇÃO COLETIVA DE TRABALHO. SETOR DE TRANSPORTEDECARGAS. PRESTAÇÃO DE SERVIÇOS POR MEMBROS DE COOPERATIVAS. 1. Mesmo que o trabalhador esteja formalmente associado a uma cooperativa, isso, por si só, não afasta a possibilidade do reconhecimento de vínculo empregatício. É necessário estarem presentes os elementos caracterizadores da sociedade cooperativa, principalmente se considerado o princípio da primazia da realidade que norteia o Direito do Trabalho, segundo o qual o aspecto formal não pode prevalecer sobre a realidade fática.  2. Para que não se forme o vínculo de emprego diretamente com o tomador de serviços, é necessário que os serviços terceirizados estejam ligados à atividade-meio do tomador, e que também não haja pessoalidade e subordinação (Enunciado 331, III, do TST). E a movimentaçãodecargase descargas não se inclui entre as atividades meramente instrumentais e de apoio estritamentelogísticoao empreendimento das empresasdetransportesdecargas. Trata-se de tarefa que compõe a essência da dinâmica empresarial das tomadoras de serviços e, por isso, insere-se entre suas atividades-fim. 3. Mantida a nulidade da cláusula que estabelece a possibilidade de utilização de mão-de-obra cooperada na movimentaçãodecargase descargas. Recurso Ordinário parcialmente provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
