INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('postos de abastecimento', '2025-07-12 17:38:16', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais;divinopolis:municipal:lei:2015-08-06;7984', 'Lei Ordinária n° 7984, de 06 de Agosto de 2015', 'urn:lex:br;minas.gerais;divinopolis:municipal:lei:2015-08-06;7984', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2015-08-06', 'Altera dispositivo da Lei no 2.418, de 18 de novembro de 1988, que dispõe sobre o uso e ocupação do solo no Município de Divinópolis e dá outras providências - Serviço do Bairro - atividades de serviço ligados ao atendimento da população do bairro, em estabelecimentos com até 300 m 2 (trezentos metros quadrados) de área construída, excetopostosdeabastecimentode combustíveis e lubrificantes com prestação de serviços -postodecombustível -posto-postos- combustível - combustíveis', 'Altera dispositivo da Lei no 2.418, de 18 de novembro de 1988, que dispõe sobre o uso e ocupação do solo no Município de Divinópolis e dá outras providências - Serviço do Bairro - atividades de serviço ligados ao atendimento da população do bairro, em estabelecimentos com até 300 m 2 (trezentos metros quadrados) de área construída, excetopostosdeabastecimentode combustíveis e lubrificantes com prestação de serviços.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('postos de abastecimento', '2025-07-12 17:38:16', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.1:acordao:2005-06-20;219374', 'Acórdão nº 219374 do Processo nº20040110329667apc', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.civel.1:acordao:2005-06-20;219374', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '2005-06-20', 'IMPROCEDÊNCIA, SUSPENSÃO DO PROCESSO,  ANULAÇÃO, AUTORIZAÇÃO, CONSTRUÇÃO,POSTODEABASTECIMENTO, COMBUSTÍVEL, ESTACIONAMENTO, SUPERMERCADO, INCONSTITUCIONALIDADE, LEI DISTRITAL, VIOLAÇÃO, PRINCÍPIO DA LIVRE CONCORRÊNCIA. 

VOTO VENCIDO: SUSPENSÃO DO PROCESSO,  PENDÊNCIA, JULGAMENTO, AÇÃO DIRETA DE INCONSTITUCIONALIDADE, POSSIBILIDADE, CONFLITO DE COMPETÊNCIA, DECISÃO,  CPC.', 'CONSTITUCIONAL E ADMINISTRATIVO. MANDADO DE SEGURANÇA.POSTODEABASTECIMENTO. ESTACIONAMENTO DE HIPERMERCADO. ANULAÇÃO DE ALVARÁ DE CONSTRUÇÃO. FUNDAMENTO. LEI INCONSTITUCIONAL. PRINCÍPIO DA LIVRE CONCORRÊNCIA. VIOLAÇÃO. 
1. A ANÁLISE E O AFASTAMENTO DOS EFEITOS CONCRETOS DE ATO ADMINISTRATIVO PRATICADO COM FUNDAMENTO EM NORMA QUE AFRONTA PRECEITO CONSTITUCIONAL PODEM SER REALIZADOS EM SEDE DE MANDADO DE SEGURANÇA.
2. AFIGURA-SE INVÁLIDO O ATO ADMINISTRATIVO QUE ANULA ALVARÁ DE CONSTRUÇÃO DEPOSTODEABASTECIMENTO, QUANDO MOTIVADO UNICAMENTE EM NORMA QUE VIOLA O PRINCÍPIO CONSTITUCIONAL DA LIVRE CONCORRÊNCIA.
3. APELO E REMESSA DE OFÍCIO CONHECIDOS E IMPROVIDOS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
