INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:distrital:decreto:2007-11-14;28435', 'Decreto nº 28435, de 14 de novembro de 2007', 'urn:lex:br;distrito.federal:distrital:decreto:2007-11-14;28435', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Distrital', '2007-11-14', 'LINHA DE ÔNIBUS, tarifa, valor, fixação. SERVIÇO DE TRANSPORTE COLETIVO URBANO.TRANSPORTADORAUTÔNOMO. REGIÃO ADMINISTRATIVA DO PARANOÁ (RA-VII). REGIÃO ADMINISTRATIVA DE SOBRADINHO (RA-V). REGIÃO ADMINISTRATIVA DO ITAPOÃ (RA-XXVIII).', 'FIXA NOVOS VALORES NAS LINHAS 510.1. PARANOA / SOBRADINHO DOS MELOS E 510.2 - PARANOA / E.C. NATUREZA (DEL LAGO / ITAPOÃ), DO SERVIÇO DE TRANSPORTE PUBLICO COLETIVO PORTRANSPORTADORESAUTONOMOS- STPCTA/DF, DO SISTEMA DE TRANSPORTE PUBLICO COLETIVO DO DISTRITO FEDERAL - STPC/DF, E DA OUTRAS PROVIDENICAS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2006-05-22;00927-2005-031-03-00-4', 'Acórdão TRT 3ª / Primeira Turma / 2006-05-22', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2006-05-22;00927-2005-031-03-00-4', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2006-05-22', 'RESPONSABILIDADE -TRANSPORTADOR', 'EMENTA:  JUSTIÇA  DO TRABALHO - MATÉRIA CIVIL (EC no. 45/2004)  -
RESPONSABILIDADE   CIVIL   DOTRANSPORTADORAUTÔNOMO-  É   dotransportadora responsabilidade pela condução da carga que lhe é
confiada, devendo zelar pela verificação do carregamento, podendo
inclusive  recusá-la  quando  constatar  a  inadequação  de   seu
acondicionamento,   só  se  isentando  da  responsabilidade   por
possíveis danos, se demonstrado ficar que era impossível conhecer
a deficiência do acondicionamento antes de iniciado o transporte.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:distrital:lei:1993-01-07;407', 'Lei nº 407, de 07 de janeiro de 1993', 'urn:lex:br;distrito.federal:distrital:lei:1993-01-07;407', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Distrital', '1993-01-07', 'NORMAS. PRESTAÇÃO DE SERVIÇO. TRANSPORTE PÚBLICO COLETIVO.TRANSPORTADORAUTÔNOMO. EMPRESA PRIVADA. SISTEMA DE TRANSPORTE COLETIVO DE BRASILIA. EXPLORAÇÃO. LINHA. NÚCLEO RURAL. ÁREA RURAL. ÁREA URBANA. TRANSPORTE URBANO. (STPC). (DMTU). (DF). CADASTRO. MOTORISTA. REGISTRO. VEÍCULO. OPERAÇÃO. PERMISSÃO. AUTORIZAÇÃO. UTILIZAÇÃO. ÔNIBUS. MICRO-ONIBUS. PLANEJAMENTO. ADJUDICAÇÃO. CONTROLE. FISCALIZAÇÃO. SERVIÇO PRESTADO. LICITAÇÃO PÚBLICA. TRANSPORTE DE ENCOMENDA. TRANSPORTE DE CARGA. NORMAS PAGAMENTO. TAXA DE SERVIÇO.', 'Dispõe sobre a prestação de serviço de transporte público coletivo portransportadoresautÔnomose empresas no Distrito Federal e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2006-04-19;01881-2004-032-03-00-6', 'Acórdão TRT 3ª / Quarta Turma / 2006-04-19', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2006-04-19;01881-2004-032-03-00-6', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2006-04-19', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:  VÍNCULO DE EMPREGO.TRANSPORTADORRODOVIÁRIOAUTÔNOMODE
BENS.  Na  forma  da previsão contida no parágrafo  1o.,  da  Lei
7.290/84, "Considera-seTransportadorRodoviárioAutônomode Bens
a  pessoa  física,  proprietário  ou  co-proprietário  de  um  só
veículo,  sem  vínculo  empregatício,  devidamente cadastrado  em
órgão  disciplinar competente,  que,  com seu  veículo,  contrate
serviço  de transporte a frete,  de carga ou  de  passageiro,  em
caráter  eventual  ou  continuado,   com  empresa  de  transporte
rodoviário  de  bens,   ou  diretamente  com  os  usuários  desse
serviço."', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.recursal.juiz.fora:acordao:2015-07-14;0002008-39.2014.5.03.0037', 'Acórdão TRT 3ª / Decima Primeira Turma / 2015-07-14', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.recursal.juiz.fora:acordao:2015-07-14;0002008-39.2014.5.03.0037', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2015-07-14', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:TRANSPORTADORAUTÔNOMODE CARGAS. AUSÊNCIA DE RELAÇÃO DE EMPREGO. LEI 11.422/2007. Evidenciado no caso concreto que a relação jurídica havida entre as partes litigantes é de natureza comercial, submetida aos ditames da Lei 11.422/2007, não há falar-se em reconhecimento de vínculo de emprego, porquanto o reclamante, comotransportadorautônomode cargas, assumiu os riscos do negócio.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2012-11-27;0000050-04.2012.5.03.0129', 'Acórdão TRT 3ª / Quinta Turma / 2012-11-27', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2012-11-27;0000050-04.2012.5.03.0129', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2012-11-27', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA: RELAÇÃO DE EMPREGO - MOTORISTATRANSPORTADORAAUTÔNOMO- Não se considera empregado o motoristatransportador, dono do próprio caminhão, que arca com os custos da manutenção do veículo e, ainda, pode se fazer substituir por terceiros, sem sofrer qualquer ingerência ou punição da empregadora. Constata-se que, na hipótese, a contratação visou a prestação de serviços de frete e não a prestação pessoal de serviços de motorista, tratando-se, por certo, de prestação de serviçosautônoma, nos moldes da Lei n. 7290/84, que define a atividade dotransportadorrodoviárioautônomode bens.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2001-02-14;ro0019991', 'Acórdão TRT 3ª / Terceira Turma / 2001-02-14', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2001-02-14;ro0019991', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2001-02-14', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:TRANSPORTADORDE  LEITE  -  TRABALHADORAUTÔNOMO-  CONFIGURAÇÃO  DE NEGÓCIO PRÓPRIO.  Otransportadorde  leite  que  possui linha de coleta exclusiva,  comerciável, arca com despesas  do negócio e pode contratar ajudantes é trabalhadorautônomo, que  assume  os riscos do seu empreendimento,  conforme artigo 2o.  da  CLT.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2014-08-26;0000516-13.2013.5.03.0145', 'Acórdão TRT 3ª / Segunda Turma / 2014-08-26', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2014-08-26;0000516-13.2013.5.03.0145', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2014-08-26', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA: RELAÇÃO DE EMPREGO.TRANSPORTADORAUTÔNOMODE CARGAS. INEXISTÊNCIA. Não há que se cogitar em reconhecimento de vínculo empregatício quando evidenciado nos autos que a prestação de serviços foi realizada portransportadorautônomode cargas "agregado", que realiza sua atividade profissional com exclusividade a determinada tomadora, utilizando-se de veículo próprio e assumindo os riscos da atividade econômica, mediante remuneração manifestamente superior àquela auferida por motoristas empregados. No caso vertente, trata-se de relaçãoautônomae de natureza comercial, regida pela Lei n. 11.442/2007.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2017-03-24;0011027-43.2016.5.03.0023', 'Acórdão PJe TRT 3ª / Segunda Turma / 2017-03-24', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2017-03-24;0011027-43.2016.5.03.0023', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2017-03-24', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'RELAÇÃO DE EMPREGO -TRANSPORTADORAUTÔNOMODE CARGAS - INEXISTÊNCIA. Não há que se cogitar em reconhecimento de vínculo empregatício quando evidenciado nos autos que a prestação de serviços foi realizada portransportadorautônomode cargas "agregado", que realiza sua atividade profissional com exclusividade a determinada tomadora, utilizando-se de veículo próprio e assumindo os riscos da atividade econômica. No caso vertente, trata-se de relaçãoautônomae de natureza comercial, consoante a inteligência das Leis n. 11.442/2007 e 7.920/84.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2017-09-29;0010618-46.2017.5.03.0148', 'Acórdão PJe TRT 3ª / Segunda Turma / 2017-09-29', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2017-09-29;0010618-46.2017.5.03.0148', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2017-09-29', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'RELAÇÃO DE EMPREGO -TRANSPORTADORAUTÔNOMODE CARGAS - INEXISTÊNCIA. Não há que se cogitar de declaração de vínculo empregatício quando evidenciado nos autos que a prestação de serviços foi realizada portransportadorautônomode cargas "agregado", que realiza sua atividade profissional com exclusividade a determinada tomadora, utilizando-se de veículo próprio e assumindo os riscos da atividade econômica. No caso vertente, trata-se de relaçãoautônomae de natureza comercial, consoante as Leis n. 11.442/2007 e 7.290/84.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:27', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2022-05-11;0010368-78.2021.5.03.0081', 'Acórdão PJe TRT 3ª / Segunda Turma / 2022-05-11', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2022-05-11;0010368-78.2021.5.03.0081', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2022-05-11', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'CONTRATO DE TRABALHO - NÃO CARACTERIZAÇÃO. LEI 11.442/07. Restando evidenciado nos autos os contornos da atividade detransportadorautônomode carga, não se reconhece o contrato de trabalho entre as partes, visto que a prestação de serviços portransportadorautônomo, devidamente inscrito nos órgãos administrativos, não configura a relação de emprego. Habitualidade e onerosidade, quando divorciadas da subordinação, são ineficazes para configuração do vínculo de emprego, pois a Lei 11442/07 considera o transporte rodoviário de cargas atividade de natureza comercial, exercida por pessoa física ou jurídica, em regime de livre concorrência, dependente de prévia inscrição do interessado em sua exploração no Registro Nacional deTransportadoresRodoviários de Cargas - RNTR-C da Agência Nacional de Transportes Terrestres - ANTT, na categoria deTransportadorAutônomode Cargas - TAC, ou seja, pessoa física que tenha no transporte rodoviário de cargas a sua atividade profissional. As relações decorrentes do contrato de transporte de cargas, nos termos do art. 4o da referida Lei, são sempre de natureza comercial, não ensejando, em nenhuma hipótese, a caracterização de vínculo de emprego.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2000-09-11;ro006333', 'Acórdão TRT 3ª / Primeira Turma / 2000-09-11', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2000-09-11;ro006333', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2000-09-11', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:   RELAÇÃO   DE  EMPREGO  -TRANSPORTADORDE   LEITE   -  INEXISTÊNCIA.  Não  é  empregado,  mas  trabalhadorautônomo,  otransportadorde leite que trabalha em veículo próprio, assumindo  os  riscos  do  negócio,  mediante o pagamento  de  frete  e  sem  exigência   da  pessoalidade  e  subordinação  na  prestação  dos  serviços.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2018-08-17;0010179-52.2017.5.03.0110', 'Acórdão PJe TRT 3ª / Quinta Turma / 2018-08-17', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2018-08-17;0010179-52.2017.5.03.0110', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2018-08-17', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'VÍNCULO DE EMPREGO -TRANSPORTADORAUTÔNOMO. Nos termos dos artigos 2º e 3º da CLT, para a caracterização de vínculo de emprego faz-se necessária a presença concomitante dos requisitos consubstanciados na pessoalidade, onerosidade, não eventualidade e subordinação jurídica. Evidenciada, na hipótese dos autos e à luz do conjunto probatório, a prestação de serviços pelo autor comotransportadorautônomo, inviável o reconhecimento da relação vindicada.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2016-08-19;0010382-21.2015.5.03.0001', 'Acórdão PJe TRT 3ª / Segunda Turma / 2016-08-19', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2016-08-19;0010382-21.2015.5.03.0001', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2016-08-19', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'TRANSPORTADORAUTÔNOMODE CARGA - SUBORDINAÇÃO - RELAÇÃO DE EMPREGO - CONFIGURAÇÃO. A princípio, não há relação de emprego entre oTransportadorAutônomode Carga - TAC e a empresa contratante, conforme Lei 11.442/2007. Todavia, comprovado que o reclamante atuava na atividade-fim da reclamada, desempenhava tarefas idênticas a de outros motoristas empregados, com subordinação a mesma chefia, podendo sofrer advertências e punições, impõe-se o reconhecimento do vínculo empregatício, não obstante o envoltório formal que se deu o contrato entre as partes.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2020-09-15;0010712-45.2016.5.03.0110', 'Acórdão PJe TRT 3ª / Quinta Turma / 2020-09-15', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2020-09-15;0010712-45.2016.5.03.0110', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2020-09-15', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'RELAÇÃO DE EMPREGO.TRANSPORTADORAUTÔNOMO. A Lei 11.442/07, no art. 2°, prescreve como sendo de natureza comercial a atividade econômica de transporte rodoviário de cargas em vias públicas; e no art. 4°, § 1°, define otransportadorautônomode cargas agregado como sendo aquele que coloca veículo de sua propriedade ou de sua posse, a ser dirigido por ele próprio ou por preposto seu, a serviço do contratante, com exclusividade, mediante remuneração certa. Dispõe ainda o art. 5° do mesmo diploma que "As relações decorrentes do contrato de transporte de cargas de que trata o art. 4º desta Lei são sempre de natureza comercial, não ensejando, em nenhuma hipótese, a caracterização de vínculo de emprego". Não se olvide que a questão da natureza comercial eautônomada relação dotransportadorrodoviário constitui presunção relativa, que deve ser confrontada com a realidade do contrato de trabalho. Desta forma, necessário que sejam verificadas as circunstâncias do caso concreto para a apuração das condições de trabalho do prestador dos serviços.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2014-07-16;0001004-70.2013.5.03.0111', 'Acórdão TRT 3ª / Quarta Turma / 2014-07-16', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2014-07-16;0001004-70.2013.5.03.0111', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2014-07-16', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:TRANSPORTADORAUTÔNOMO. INEXISTÊNCIA DE RELAÇÃO DE EMPREGO. O conjunto probatório não autoriza o reconhecimento do vínculo empregatício vindicado pelo autor, à ausência de elementos suficientes que por sua relevância jurídica pudessem comprovar a presença da pessoalidade, onerosidade e subordinação jurídica na prestação de serviços havida entre as partes (artigos 2º e 3º da CLT). O autor eratransportadorautônomo, prestava serviços nos exatos liames do contrato de transporte celebrado com o primeiro réu, possibilitada a prestação de serviços a qualquer empresa, sem se sujeitar ao poder diretivo dos reclamados, assumindo o empreendimento econômico segundo sua própria conveniência, o que somente se coaduna com o trabalho de naturezaautônoma, regido por lei especial.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2012-03-07;0001353-83.2010.5.03.0077', 'Acórdão TRT 3ª / Terceira Turma / 2012-03-07', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2012-03-07;0001353-83.2010.5.03.0077', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2012-03-07', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA: RELAÇÃO DE EMPREGO -TRANSPORTADORRODOVIÁRIO. No presente caso, entende-se que a reclamada se desincumbiu a contento de demonstrar a prestação de serviços pelo reclamante comotransportadorrodoviárioautônomona forma da Lei no 7.290/84, como alegado em razões recursais. O art. 1o da Lei no 7.290/84, dispõe que: "Art. 1o. Considera-seTransportadorAutônomode Bens a pessoa física proprietário ou co-proprietário de um só veículo, sem vínculo empregatício, devidamente cadastrado em órgão disciplinar competente, que, com o seu veículo, contrate serviço de transporte a frete, de carga ou de passageiro, em caráter eventual ou continuado, com empresa de transporte rodoviário de bens, ou diretamente com os usuários desse serviço". Recurso provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2020-10-29;0010346-22.2016.5.03.0040', 'Acórdão PJe TRT 3ª / Nona Turma / 2020-10-29', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2020-10-29;0010346-22.2016.5.03.0040', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2020-10-29', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'VÍNCULO DE EMPREGO. INEXISTÊNCIA. MOTORISTATRANSPORTADORAUTÔNOMO. A questão da natureza comercial eautônomada relação dotransportadorautônomode cargas constitui presunção relativa, que deve ser confrontada com a realidade do contrato de trabalho. Em recente julgamento proferido em 22/04/2020, o Supremo Tribunal Federal, nos autos da Ação Declaratória de Constitucionalidade n. 48, que teve como Relator o Excelentíssimo Ministro Roberto Barroso, proferiu a Tese: "1 - A Lei nº 11.442/2007 é constitucional, uma vez que a Constituição não veda a terceirização, de atividade-meio ou fim. 2 - O prazo prescricional estabelecido no art. 18 da Lei nº 11.442/2007 é válido porque não se trata de créditos resultantes de relação de trabalho, mas de relação comercial, não incidindo na hipótese o art. 7º, XXIX, CF. 3 - Uma vez preenchidos os requisitos dispostos na Lei nº 11.442/2007, estará configurada a relação comercial de natureza civil e afastada a configuração de vínculo trabalhista"', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2002-02-05;ro0116199', 'Acórdão TRT 3ª / Quinta Turma / 2002-02-05', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2002-02-05;ro0116199', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2002-02-05', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:  RELAÇÃO DE EMPREGO.  NÃO  CARACTERIZAÇÃO.TRANSPORTADORRODOVIÁRIOAUTÔNOMO.  LEI 7290/84.  Não se caracteriza relação de  emprego, quando o reclamante, motorista proprietário do veículo e  arcando  com  as  despesas  de  sua  manutenção,  recebia  apenas  comissões  pelas  entregas  de mercadorias  e  não  pela  simples  colocação  da  sua força de trabalho à disposição da reclamada  e  também  por se fazer substituir por pessoa por ele indicada,  sem  interferência da reclamada.  A atividade do reclamante insere-se,  portanto,  comotransportadorrodoviárioautônomo,  ainda  que  formalmente  não  provado  nos  autos  o  cadastro  no   registro  competente,   bem  como  a  existência  de  contrato  escrito  de  prestação  de serviçosautônomosou inscrição junto ao INSS.  É a  pura aplicação do princípio da primazia da realidade.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2013-04-24;0000581-57.2012.5.03.0043', 'Acórdão TRT 3ª / Quarta Turma / 2013-04-24', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2013-04-24;0000581-57.2012.5.03.0043', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2013-04-24', 'RELAÇÃO DE EMPREGO - TRABALHOAUTÔNOMO', 'EMENTA:TRANSPORTADORAUTÔNOMO. INEXISTÊNCIA DE RELAÇÃO DE EMPREGO. Na hipótese dos autos, o conjunto probatório não autoriza o reconhecimento do vínculo empregatício vindicado pelo autor, pois não há  elementos suficientes para comprovar a presença da pessoalidade e subordinação jurídica na prestação de serviços havida entre as partes (artigos 2º e 3º da CLT). O autor eratransportadorautônomo, prestava serviços em veículo próprio, sem se sujeitar ao poder diretivo da reclamada, além de ter assumido os riscos de seu empreendimento econômico, o que somente se coaduna com o trabalho de naturezaautônoma, regido por lei especial.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2020-07-22;0010957-96.2016.5.03.0032', 'Acórdão PJe TRT 3ª / Nona Turma / 2020-07-22', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.9:acordao:2020-07-22;0010957-96.2016.5.03.0032', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2020-07-22', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'RELAÇÃO DE EMPREGO. INEXISTÊNCIA.TRANSPORTADORRODOVIÁRIOAUTÔNOMO. Se o reclamante étransportadorautônomode cargas - TAC, nos termos da Lei 11.442/2007, não existe relação de emprego com a empresa de transporte rodoviário de cargas - ETC, ou mesmo com a empresa tomadora de serviços de transporte rodoviário de cargas. Com efeito, no dia 14/04/2020, no julgamento da ADC n. 48 e da ADI n. 3961, o Excelso STF fixou a seguinte tese : "1 - A Lei 11.442/2007 é constitucional, uma vez que a Constituição não veda a terceirização, de atividade-meio ou fim. 2 - O prazo prescricional estabelecido no art. 18 da Lei 11.442/2007 é válido porque não se trata de créditos resultantes de relação de trabalho, mas de relação comercial, não incidindo na hipótese o art. 7º, XXIX, CF. 3 - Uma vez preenchidos os requisitos dispostos na Lei nº 11.442/2007, estará configurada a relação comercial de natureza civil e afastada a configuração de vínculo trabalhista". Recurso desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2022-11-07;0010437-36.2021.5.03.0138', 'Acórdão PJe TRT 3ª / Primeira Turma / 2022-11-07', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2022-11-07;0010437-36.2021.5.03.0138', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2022-11-07', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'VÍNCULO DE EMPREGO.TRANSPORTADORRODOVIÁRIOAUTÔNOMODE CARGAS CONTRATADO NOS MOLDES DA LEI 11.442/2007. Em que pese a prevalência das regras que impedem a formação de vínculo de emprego entre otransportadorautônomode cargas e a empresa contratante, por expresso impedimento legal, é certo que o Direito do Trabalho fundamenta-se no Princípio da primazia da realidade sobre a forma e, portanto, não é possível olvidar a verificação da ocorrência ou não dos elementos fático-jurídicos da relação de emprego. Nesse contexto, a análise do caso concreto permite verificar se os requisitos dispostos na Lei 11.442/07 foram ou não preenchidos, de modo que, se estão presentes os requisitos do TransporteAutônomode Cargas, não se configura o vínculo empregatício. Por outro lado, se a prova do processo demonstrar que sequer as formalidades legais do contrato de transporteautônomode cargas foram cumpridas e que a prestação de serviços se deu com os foros de pessoalidade e subordinação jurídica, o vínculo de emprego deve ser reconhecido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2021-01-29;0011799-30.2016.5.03.0112', 'Acórdão PJe TRT 3ª / Setima Turma / 2021-01-29', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.7:acordao:2021-01-29;0011799-30.2016.5.03.0112', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2021-01-29', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'MOTORISTAAUTÔNOMO. LEI 11.442/2017. VÍNCULO DE EMPREGO. EXISTÊNCIA. Embora a legislação regulatória da atividade de transporte rodoviário (Lei 11.442/07) contemple a possibilidade da prestaçãoautônomados serviços, atualmente desenvolvida pelos denominadostransportadoresautônomosde carga (TAC), tal condição pressupõe a sua realização de forma regular e sem a configuração dos elementos fático-jurídicos disciplinados nos artigos 2º e 3º da CLT. No caso dos autos, existentes os pressupostos fático-jurídicos da relação de emprego, deve ser reconhecido o reconhecimento do vínculo empregatício entre as partes, declarando-se nula a contratação do autor pelas rés.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2005-02-22;00760-2004-100-03-00-0', 'Acórdão TRT 3ª / Segunda Turma / 2005-02-22', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2005-02-22;00760-2004-100-03-00-0', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2005-02-22', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:  RELAÇÃO DE EMPREGO.  NÃO  CARACTERIZAÇÃO.TRANSPORTADORRODOVIÁRIOAUTÔNOMO. LEI 7.290/84. "Não se caracteriza relação de  emprego, quando o reclamante, motorista proprietário do veículo e  arcando  com  as  despesas  de  sua  manutenção,  recebia  apenas  comissões  pelas  entregas  de mercadorias  e  não  pela  simples  colocação  da  sua força de trabalho à disposição da reclamada  e  também  por se fazer substituir por pessoa por ele indicada,  sem  interferência da reclamada.  A atividade do reclamante insere-se,  portanto,  comotransportadorrodoviárioautônomo,  ainda  que  formalmente  não  provado  nos  autos  o  cadastro  no   registro  competente,   bem  como  a  existência  de  contrato  escrito  de  prestação  de serviçosautônomosou inscrição junto ao INSS.  É a  pura aplicação do princípio da primazia da realidade". CARRETEIRO  - INEXISTÊNCIA DE RELAÇÃO DE EMPREGO.  "É carreteiroautônomo,  e  não motorista empregado, quem assume os riscos do negócio e não é  subordinado juridicamente à empresa. Em casos tais, o objetivo do  contrato é o veículo,  e não o motorista" (Juiz Alfio Amauri  dos  Santos).', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.10:acordao:2020-09-30;0010529-74.2017.5.03.0131', 'Acórdão PJe TRT 3ª / Decima Turma / 2020-09-30', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.10:acordao:2020-09-30;0010529-74.2017.5.03.0131', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2020-09-30', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'TERCEIRIZAÇÃO DO TRANSPORTE DE CARGA. VÍNCULO DE EMPREGO. NÃO OCORRÊNCIA. O STF, no julgamento do ADC nº 48 (Rel. Min. Roberto Barroso, DJE 19/05/2020), chancelou o entendimento de ser possível a terceirização de atividade-fim e fixou, em relação à terceirização do transporte de cargas, que "Uma vez preenchidos os requisitos dispostos na Lei 11.442/2007, estará configurada a relação comercial de natureza civil e afastada a configuração de vínculo trabalhista" entre o TAC -transportadorautônomode cargas - e a ETC - empresa de transporte rodoviário de cargas. "In casu", a prova dos foi no sentido de ser o autor autêntico TAC -transportadorautônomode cargas e que houve o cumprimento dos requisitos da Lei 11.442/2007, afastando-se a pretensão de declaração do vínculo empregatício.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2021-05-21;0011291-22.2019.5.03.0131', 'Acórdão PJe TRT 3ª / Segunda Turma / 2021-05-21', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2021-05-21;0011291-22.2019.5.03.0131', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2021-05-21', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'TRANSPORTADORAUTÔNOMODE CARGAS. VÍNCULO EMPREGATÍCIO. NÃO CARACTERIZAÇÃO. A prestação de serviços por motorista na condição deTransportadorAutônomode Cargas, responsável pelos custos do veículo e remunerado à base de fretes não comporta o reconhecimento do vínculo empregatício, mas de desempenho de atividades profissional nos moldes da Lei nº 11.442/2007. O Supremo Tribunal Federal julgou procedente o pedido formulado na Ação Declaratória de Constitucionalidade nº 48, a fim de reconhecer a constitucionalidade da Lei nº 11.442/2007, firmando a seguinte tese: "1 -A Lei nº 11.442/2007 é constitucional, uma vez que a Constituição não veda a terceirização, de atividade-meio ou fim. 2 -O prazo prescricional estabelecido no art. 18 da Lei nº 11.442/2007 é válido porque não se trata de créditos resultantes de relação de trabalho, mas de relação comercial, não incidindo na hipótese o art. 7º, XXIX, CF. 3 - Uma vez preenchidos os requisitos dispostos na Lei nº 11.442/2007, estará configurada a relação comercial de natureza civil e afastada a configuração de vínculo trabalhista".', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2021-09-03;0012184-90.2017.5.03.0031', 'Acórdão PJe TRT 3ª / Terceira Turma / 2021-09-03', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2021-09-03;0012184-90.2017.5.03.0031', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2021-09-03', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'VÍNCULO EMPREGATÍCIO.TRANSPORTADORAUTÔNOMODE CARGA (TAC). INAPLICABILIDADE DA LEI Nº 11.442/07 E DA ADC 48. AUSÊNCIA DE CONTRATO ESCRITO ENTRE O MOTORISTA E A EMPRESA DE TRANSPORTE RODOVIÁRIO DE CARGAS. O Supremo Tribunal Federal, por seu Tribunal Pleno, em 16/4/2020 julgou procedente a ADC nº 48 e declarou a constitucionalidade da Lei nº 11.442/2007, firmando entendimento de que "preenchidos os requisitos dispostos na Lei nº 11.442/2007, estará configurada a relação comercial de natureza civil e afastada a configuração de vínculo trabalhista". Todavia, tratando-se detransportadorautônomode carga (TAC), é imprescindível a elaboração de contrato escrito formal com a empresa de transporte rodoviário de cargas (ETC), sob pena de irregularidade da contratação nos moldes da legislação referida. In casu, evidenciado o descumprimento dos requisitos previstos na Lei nº 11.442/2007 e demonstrado o preenchimento dos elementos fático jurídicos dos artigos 2º e 3º da CLT, impõe-se o reconhecimento do vínculo empregatício entre as partes.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.recursal.juiz.fora:acordao:2021-10-21;0011835-90.2017.5.03.0030', 'Acórdão PJe TRT 3ª / Decima Primeira Turma / 2021-10-21', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.recursal.juiz.fora:acordao:2021-10-21;0011835-90.2017.5.03.0030', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2021-10-21', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'TRANSPORTADORAUTÔNOMODE CARGA - TAC. AUSÊNCIA DOS REQUISITOS DA LEI 11.442/2007. VÍNCULO EMPREGATÍCIO RECONHECIDO. A Lei 11.442/2007 dispõe que oTransportadorAutônomode Carga deverá comprovar ser proprietário, co-proprietário ou arrendatário de, pelo menos, um veículo automotor de carga, registrado em seu nome no órgão de trânsito como veículo de aluguel. Também deverá comprovar ter experiência de 3 anos na área, ou ter sido aprovado em curso específico. Além disso, o transporte rodoviário de cargas deve ser efetuado sob contrato ou conhecimento de transportes, que deverá conter informações para a completa identificação e dos serviços e de natureza fiscal. No julgamento da ADC 48, o STF reconheceu a constitucionalidade da referida lei e assentou que, uma vez atendidos os seus requisitos, resta configurada a relação comercial de natureza civil e afastada a configuração de vínculo trabalhista. Por outro lado, a ausência de qualquer um desses requisitos, os quais são essenciais para a formalização do transporte rodoviário de cargas prestado por motoristaautônomo, afasta a aplicação da referida legislação no caso concreto. Assim, não comprovada a tese da reclamada, de prestação de serviços por parte do reclamante na qualidade de TAC, e evidenciando a prova oral os pressupostos dos arts. 2º e 3º da CLT, admite-se que a relação jurídica havida entre as partes é de emprego.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2000-02-17;ro9913730', 'Acórdão TRT 3ª / Quinta Turma / 2000-02-17', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2000-02-17;ro9913730', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2000-02-17', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'E M E N T A: TRABALHADOR RODOVIÁRIOAUTÔNOMOLEI NO. 7.290/84 - O  trabalhador que labora com frete, em veículo próprio, arcando com  todas   as  despesas  deste,   enquadra-se   comoTransportadorRodoviárioAutônomo,   nos  moldes  estabelecidos  na  Lei   no.  7.290/84, ficando afastado, portanto, o reconhecimento do vínculo  empregatício.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('transportador autônomo', '2025-07-12 17:38:28', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2017-01-30;0002104-84.2013.5.03.0103', 'Acórdão TRT 3ª / Primeira Turma / 2017-01-30', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2017-01-30;0002104-84.2013.5.03.0103', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2017-01-30', 'RELAÇÃO DE EMPREGO -TRANSPORTADOR', 'EMENTA:TRANSPORTADORAUTÔNOMODE CARGAS. CONDIÇÃO NÃO COMPROVADA. VÍNCULO EMPREGATÍCIO RECONHECIDO. Evidenciadas as exigências previstas nos artigos 2º e 3º da CLT, há de ser reconhecida a relação de emprego. Na hipótese vertente, a prova oral logrou demonstrar a presença da subordinação jurídica, estando à época o falecido sujeito a sofrer punições, não havendo falar, assim, em prestação de serviçosautônomosde transporte.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('portaria', '2025-07-12 17:38:30', 'https://www.lexml.gov.br/urn/urn:lex:br:departamento.administrativo.servico.publico:portaria:1973-03-16;40', 'Portarianº 40 de 16-03-1973', 'urn:lex:br:departamento.administrativo.servico.publico:portaria:1973-03-16;40', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Departamento Administrativo Servico Publico', '1973-03-16', 'Especificações de classe. Grupo de Categoria Funcionais - Serviços de Transporte Oficial ePortaria.', 'Especificações de classe do Grupo de Categoria Funcionais - Serviços de Transporte Ofical ePortaria, criado com fundamento no artigo 4º da Lei nº 5.645, de 1º de dezembro de 1970.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
