INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2010-05-05;970', 'ACÓRDÃO TCU 970/2010', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2010-05-05;970', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2010-05-05', NULL, 'Monitoramento do cumprimento do Acórdão 168/2004-P. ISSQN. Revisão dos contratos de concessão rodoviária. Medidas adotadas pelaANTTatendem, no geral, ao determinado pelo Tribunal. Necessidade de ajustes nos fluxos de caixa. Determinações àANTT. Ciência à Comissão de Fiscalização Financeira e Controle da Câmara dos Deputados e aos demais interessados.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2014-11-19;3212', 'ACÓRDÃO TCU 3212/2014', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2014-11-19;3212', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2014-11-19', NULL, 'REPRESENTAÇÃO. INDÍCIOS DE IRREGULARIDADES RELATIVAS À FALTA DE SEGURANÇA VIÁRIA EM TRECHOS DAS RODOVIAS BR-116/BA E BR-324/BA, SOB CONCESSÃO. OITIVAS DAANTTE DA CONCESSIONÁRIA. DETERMINAÇÕES PROPOSTAS NO ÂMBITO DE OUTROS PROCESSOS. NECESSIDADE DE MELHORIA NOS PROCEDIMENTOS DE FISCALIZAÇÃO POR PARTE DAANTT. CIÊNCIA. APENSAMENTO.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-11-17;1819', 'ACÓRDÃO TCU 1819/2004', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-11-17;1819', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2004-11-17', NULL, 'Acompanhamento. Agência Nacional de Transportes Terrestre -ANTT. Remessa de documentação em cumprimento à IN TCU nº 27/98. Informações sobre o transporte rodoviário interestadual e internacional de passageiros. Determinação. Arquivamento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-12-01;1926', 'ACÓRDÃO TCU 1926/2004', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2004-12-01;1926', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2004-12-01', NULL, 'Auditoria operacional. Ministério dos Transportes.ANTT. Avaliação da regulação dos serviços públicos relativos ao transporte rodoviário internacional e interestadual de passageiros. Falta de regulamentação dos serviços prestados nos terminais rodoviários. Ausência de cadastramento de ligações do transporte semi-urbano naANTT. Elevada idade da frota e alta incidência de transporte clandestino. Existência de barreiras à entrada de novas empresas no setor. Elevado grau de concentração econômica na exploração de bens públicos e na prestação de serviços. Baixa freqüência de realização de licitações e longo prazo das outorgas de permissão. Recomendação. Representação. Determinação. Remessa de cópia ao Congresso Nacional. Arquivamento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;

-- Batch 19: Records 1801-1900
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2005-07-13;981', 'ACÓRDÃO TCU 981/2005', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2005-07-13;981', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2005-07-13', NULL, 'Acompanhamento. Ministério dos Transportes.ANTT. Segunda etapa do programa de outorga de concessão de trechos rodoviários. Primeiro estágio. Análise da consistência das premissas adotadas, da exatidão dos cálculos, da estrutura e da correção técnica das planilhas eletrônicas desenvolvidas. Existência de aspectos controversos nos estudos de viabilidade apresentados pelo referido Ministério, que acarreta a majoração do nível tarifário. Necessidade de deixar de publicar os editais para concessão dos trechos rodoviários tratados nos presentes autos, até ulterior manifestação do TCU sobre os estudos de viabilidade desenvolvidos para fundamentar a tarifa máxima a ser exigida nos respectivos certames. Determinação. Restituição dos autos à unidade técnica. Ciência ao Ministro de Estado dos Transportes e àANTT.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.contas.uniao;plenario:acordao:2005-08-10;1121', 'ACÓRDÃO TCU 1121/2005', 'urn:lex:br:tribunal.contas.uniao;plenario:acordao:2005-08-10;1121', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Contas Uniao', 'Acordao', '2005-08-10', NULL, 'Auditoria realizada na Concessionária da Ponte Rio-Niterói S.A. - PONTE, para verificar a pertinência das tarifas de pedágio cobradas desde o início da concessão, a execução contratual e a manutenção do seu equilíbrio econômico-financeiro em virtude das revisões, reajustes e adequações realizadas. Determinações àANTT. Determinação à Secretaria de Fiscalização de Desestatização/TCU para realização de auditoria nas obras realizadas pela concessionária. Autorização para requisição de técnicos especializados da Universidade Federal do Rio de Janeiro. Arquivamento dos autos com proposta de monitoramento. Ciência ao Ministério dos Transportes, àANTTe à Concessionária.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2020-10-13;1889364-1994228', 'REsp 1889364 / PR', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2020-10-13;1889364-1994228', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2020-10-13', NULL, 'ADMINISTRATIVO E PROCESSUAL CIVIL. RECURSO ESPECIAL. AGÊNCIA
NACIONAL DE TRANSPORTES TERRESTRES -ANTT. PROCESSO ADMINISTRATIVO
SIMPLIFICADO. ARTS. 64 A 70 DA RESOLUÇÃO 442/2004 -ANTT. NÃO
OPORTUNIZAÇÃO DE ALEGAÇÕES FINAIS. ACÓRDÃO RECORRIDO QUE DECRETOU A
NULIDADE DO PROCESSO ADMINISTRATIVO E DA MULTA. OMISSÃO DO ACÓRDÃO
RECORRIDO QUANTO A QUESTÕES RELEVANTES PARA O DESLINDE DA
CONTROVÉRSIA. OFENSA AO ART. 1.022 DO CPC/2015 RECONHECIDA. RETORNO
DOS AUTOS À ORIGEM, PARA ANÁLISE DAS QUESTÕES ARGUIDAS PELA PARTE
RECORRENTE. RECURSO ESPECIAL CONHECIDO E PROVIDO.
I. Recurso Especial interposto contra acórdão publicado na vigência
do CPC/2015.
II. Trata-se, na origem, de ação anulatória, proposta por Rumo Malha
Sul S.A. em face da Agência Nacional de Transportes Terrestres -ANTT, objetivando a declaração de nulidade da Notificação de
Infração nº URRS 051/2011, lavrada pelaANTT, em face de suposto
descumprimento de cláusula de contrato de arrendamento. O Juízo de
1º Grau julgou procedente a ação, "para declarar a nulidade da
Notificação de Infração nº URRS 051/2011 e, conseqüentemente, da
penalidade de multa decorrente", ante a não oportunização do direito
ao oferecimento de alegações finais pelo administrado, na forma dos
arts. 2º, X, e 3º, III, da Lei 9.784/99. O Tribunal de origem deu
parcial provimento ao apelo daANTT, para declarar a nulidade
parcial do processo administrativo, a partir do momento em que
adotado o rito do processo administrativo simplificado. Segundo o
acórdão recorrido, "não houve observação, pelaANTT, das disposições
contidas na Lei 9.784/1999 (Lei que regula o processo administrativo
no âmbito da Administração Pública Federal)". Concluiu que, "tendo o
processo administrativo seguido o rito simplificado (PAS) e não
tendo sido oportunizada à parte autora a apresentação de alegações
finais, o reconhecimento da nulidade parcial do processo
administrativo, a partir do momento em que adotado o rito do
processo administrativo simplificado, é medida que se impõe".
III. A autarquia, nos Embargos de Declaração, opostos em 2º Grau,
alegou, em síntese, que, "embora a Lei nº 9.784/99 contenha previsão
quanto à apresentação de alegações finais, verifica-se a existência
de legislação específica, consistente da ResoluçãoANTT442/2004,
que disciplina o PAS - Processo Administrativo Simplificado,
destinado à apuração de infrações puníveis com as penalidades de
advertência ou multa decorrentes de condutas que infrinjam a
legislação de transportes terrestres e os deveres estabelecidos nos
editais de licitações, nos contratos de concessão, de permissão e de
arrendamento e nos termos de outorga de autorização". Aduziu que, no
processo administrativo simplificado, as alegações finais não se
mostraram necessárias, "uma vez que depois de apresentada a defesa
administrativa o processo já vai para a fase de julgamento, nos
termos do art. 68 da Resolução 442/2004. Ou seja, não há fase de
instrução a ensejar a apresentação de alegações finais". Alegou que,
"no processo do rito ordinário, onde há fase de instrução, a
Resolução prevê no seu artigo 51,que ''encerrada a instrução, o
indiciado será intimado para, querendo, manifestar-se, no prazo de
dez dias, improrrogável''", tal como ocorre no art. 44 da Lei
9.784/99. Concluiu, assim, que, "se no processo administrativo
simplificado, as alegações  no processo administrativo de rito
simplificado, uma vez apresentada a defesa o processo passa direto
para julgamento, não há razão para nova intimação para apresentação
de alegações finais imediatamente após a apresentação da defesa,
porquanto não houve a prática de nenhum ato instrutório posterior".
Assim, sustentou a recorrente que "eventual nulidade no processo
administrativo exigiria que o interessado comprovasse o prejuízo
sofrido, o que não restou configurado, de sorte que não há que se
falar em nulidade do processo administrativo se não comprovado real
prejuízo". No entanto, os Embargos de Declaração foram rejeitados,
sem que tais alegações fossem apreciadas.
IV.Tais questões de fato são relevantes para o deslinde da
controvérsia, mormente considerando a jurisprudência desta Corte, em
casos análogos, no sentido de que o processo administrativo
simplificado, previsto na ResoluçãoANTT442/2004, possui respaldo
na Lei 8.987/95 e na Lei 10.233/2001. Nesse contexto, concluindo não
ser o caso de aplicação da Lei 9.784/1999, esta Corte entende
inexistir cerceamento de defesa, em razão da não oportunização de
oferecimento de alegações finais, no âmbito do  processo
administrativo simplificado. Nesse sentido: STJ, REsp 1.723.086/RS,
Rel. Ministro OG FERNANDES, SEGUNDA TURMA, DJe de 18/09/2018; AgInt
nos EDcl no AgInt no AREsp 1152519/PR, Rel. Ministro SÉRGIO KUKINA,
PRIMEIRA TURMA, DJe de 19/12/2019; AgInt no REsp 1.779.362/PR, Rel.
Ministro HERMAN BENJAMIN, SEGUNDA TURMA, DJe de 12/09/2019; AgInt no
REsp 1.581.109/PR, Rel. Ministro GURGEL DE FARIA, PRIMEIRA TURMA,
DJe de 26/10/2017.
V. Deixando o acórdão de se manifestar sobre matéria de fato
relevante ao deslinde da controvérsia, rejeitando os Embargos
Declaratórios e persistindo na omissão oportunamente alegada,
incorre em ofensa ao art. 1.022 do CPC/2015, reiterada, em sede de
Recurso Especial.
VI. Recurso Especial provido, para anular o acórdão que julgou os
Declaratórios e determinar o retorno dos autos à origem, a fim de
que o Tribunal a quo sane os aludidos vícios.
Decis?o
Vistos, relatados e discutidos os autos em que são partes as acima
indicadas, acordam os Ministros da Segunda Turma do Superior
Tribunal de Justiça, por unanimidade, dar provimento ao recurso, nos
termos do voto da Sra. Ministra Relatora.
Os Srs. Ministros Francisco Falcão, Herman Benjamin, Og Fernandes e
Mauro Campbell Marques votaram com a Sra. Ministra Relatora.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2021-05-10;1705448-2052795', 'AgInt no AREsp 1705448 / PR', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2021-05-10;1705448-2052795', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Aresp', '2021-05-10', NULL, 'PROCESSUAL CIVIL. ADMINISTRATIVO.ANTT. CONCESSÃO DE TRANSPORTE
FERROVIÁRIO. REPOSIÇÃO DE BENS PARA PRESTAÇÃO DOS SERVIÇOS.
AUSÊNCIA. MULTA ADMINISTRATIVA. ANULAÇÃO PARCIAL DO PROCESSO
ADMINISTRATIVO. MOTIVAÇÃO. AUSÊNCIA DE INFRAÇÃO CONTRATUAL.
PRETENSÃO DE REEXAME FÁTICO-PROBATÓRIO. APLICAÇÃO DAS SÚMULAS N. 5 E
7, AMBAS DO STJ.
I -Na origem, trata-se de ação ajuizada por Rumo Malha Sul S.A.
contra a Agência Nacional de Transportes Terrestres ?ANTTobjetivando a anulação de multa administrativa, por ausência de
reposição de bens vinculados à concessão para prestação dos serviços
de transporte ferroviário de cargas na Malha Sul. Na sentença,
julgou-se parcialmente procedente o pedido para manter a penalidade
imposta, com exclusão dos juros e da multa de mora aplicada antes da
coisa julgada administrativa. No Tribunal a quo, a decisão foi
reformada para anular parcialmente o processo administrativo. Nesta
Corte, conheceu-se do agravo para não conhecer do recurso especial.
II - A jurisprudência do Superior Tribunal de Justiça é firme no
sentido de que se a Corte de origem analisou a controvérsia a
respeito da ausência de motivação das decisões que compõem o
processo administrativo questionado, levando em consideração os
fatos e provas relacionados à matéria. Assim, para se chegar à
conclusão diversa, seria necessário o reexame fático-probatório, o
que é vedado pelo enunciado n. 7 da Súmula do STJ, segundo o qual "a
pretensão de simples reexame de provas não enseja recurso especial".
III - O Tribunal a quo assim decidiu (fls. 1.775-1.776):
"Acresça-se que, de acordo com a Notificação de Infração
URRS014/2011, decorrente do processo administrativo n.º
50520.063757/2010-93, os fatos imputados à autora - ''não promover a
reposição de bens vinculados à concessão de forma a assegurar
prestação de serviço adequado'', em relação ao trecho ferroviário de
Iperó a Pinhalzinho, Itaboa a Apiaí e uvaranas a Pinhalzinho - foram
objetivamente descritos no relatório de inspeção e configuram, em
tese, infração ao Inciso X, parágrafo 9.1 - cláusula nona, do
Contrato de Concessão (CONTR6 do evento 1). Nesse aspecto, é
irretocável a sentença: 2.5. Não procedem as alegações de que a
autuação não foi motivada.O auto de infração foi lavrado com
fundamento em um extenso relatório de inspeção técnica programada
elaborado por técnicos daANTT(Evento 1,PROCADM13, páginas 11), no
qual foi relacionado um grande número de equipamentos que não foram
repostos pela ALL, todos necessários à prestação de um serviço de
transporte ferroviário adequado. Por exemplo, foram constatados em
vários trechos trilhos patinados, dormentes inservíveis, trilhos
desgastados finos, trilhos corrugados, flambagem (torção)de trilhos,
juntas defeituosas, falta de parafusos, etc, sendo que muitos
trilhos estão em final de sua vida útil, reclamando, portanto, a sua
substituição. Vale lembrar que o artigo 50, § 1º, da Lei n. 9.784/99
prevê que a motivação pode ''consistir em declaração de concordância
com fundamentos de anteriores pareceres, informações, decisões ou
propostas, que, neste caso, serão parte integrante do ato''.
Portanto, o fato do auto de infração reportar-se a pareceres ou
relatórios anteriores não o torna nulo. Por idênticas razões, não
são nulas a DECISÃOGEFER/SUCAR, de 04 de novembro de 2011, e a
decisão que apreciou o recurso administrativo."
IV - Para rever tal posição e interpretar os dispositivos legais
indicados como violados (arts. 2° e 50 da Lei n. 9.784/1999), seria
necessário o reexame desses mesmos elementos fático-probatórios, o
que é vedado no âmbito estreito do recurso especial, em virtude da
disposição da Súmula n. 7/STJ.
V - Quanto à alegação de negativa de vigência do art. 6° da Lei n.
8.987/1995 e do art. 3°, § 1°, do Decreto n. 4.130/2002 e o
consequente argumento de que a cláusula contratual infringida deve
ser interpretada à luz da legislação federal, que é genérica e
carece de elaboração de norma técnica complementar, sem a qual a
penalidade não lhe poderia ter sido imposta.
VI - No particular, o Tribunal a quo, com lastro no conjunto
probatório constante dos autos, assim decidiu à fl. 1.776: "Também
não procede a alegação de que a autora só poderia ser autuada se não
estivesse prestando um serviço adequado e cumprindo as metas
impostas pelaANTT. De igual modo, não procedem os argumentos de que
foi penalizada por supostamente infringir normas técnicas que nunca
foram editadas pelaANTT. O contrato de concessão firmado com aANTTé muito claro ao dispor que, entre as obrigações da concessionária,
inclui-se a de ''Promover a reposição de bens e equipamentos
vinculados à CONCESSÃO, bem como a aquisição de novos bens, de forma
a assegurar prestação de serviço adequado'' (item 9.1, X). Percebe-se
que essa cláusula contratual não isenta a concessionária de sua
responsabilidade se ela atingir metas de segurança ou metas de
tonelagem transportadas. Além disso, as infrações cometidas pela ALL
são tão claras, e o relatório técnico elaborado pelaANTTbem
demonstra isso, que não havia necessidade alguma - pelo menos neste
caso - de aANTTelaborar norma técnica destinada a informar a ALL
sobre quais seriam os bens e equipamentos a serem repostos. A ALL é
uma empresa voltada ao transporte ferroviário de cargas, de modo que
ela sabe muito bem que não pode, por exemplo, manterem suas linhas
ferroviárias trilhos finos, corrugados e patinados, ou dormentes
inservíveis."
VII - Impossível sobrepor o juízo de cognição realizado pelo
Tribunal recorrido, porquanto tal providência demandaria o
revolvimento de matéria fática, ressaltando-se que a jurisprudência
deste Tribunal é assente no sentido da impossibilidade de se
discutir, em recurso especial, questões relacionadas à
caracterização ou não de infração contratual e seus consectários, a
exemplo das sanções impostas, em razão dos óbices contidos nas
Súmulas n. 5 e 7/STJ. A propósito, confira-se: (AgInt no AREsp n.
1.589.232/SP, relator Ministro Sérgio Kukina, Primeira Turma,
julgado em 28/9/2020, DJe 1º/10/2020 e AgInt no AREsp n.
1.483.931/SP, relator Ministro Francisco Falcão, Segunda Turma,
julgado em 17/12/2019, DJe 19/12/2019).
VIII  - Agravo interno improvido .
Decis?o
Vistos e relatados estes autos em que são partes as acima indicadas,
acordam os Ministros da SEGUNDA TURMA do Superior Tribunal de
Justiça, por unanimidade, negar provimento ao recurso, nos termos do
voto do Sr. Ministro Relator.
Os Srs. Ministros Herman Benjamin, Og Fernandes, Mauro Campbell
Marques e Assusete Magalhães votaram com o Sr. Ministro Relator.
Presidiu o julgamento o Sr. Ministro Herman Benjamin.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:senado.federal:projeto.lei;pl:2024;4158', '[ Projeto de Lei nº 4158/2024 ]', 'urn:lex:br:senado.federal:projeto.lei;pl:2024;4158', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Senado Federal', '2024-01-01', NULL, 'Altera a Lei nº 10.233, de 05 de junho de 2001, para conferir àANTTatribuições específicas relativas ao transporte ferroviário, disciplinar a responsabilidade das concessionárias de ferrovias quanto à prestação de serviço adequado e disciplinar a responsabilidade daANTTsobre as comissões tripartites de ferrovias.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;corte.especial:acordao;sls:2015-12-02;1964-1501051', 'AgRg na SLS 1964 / DF', 'urn:lex:br:superior.tribunal.justica;corte.especial:acordao;sls:2015-12-02;1964-1501051', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Sls', '2015-12-02', NULL, 'PEDIDO DE SUSPENSÃO DE LIMINAR. COMPETÊNCIA DO SUPERIOR TRIBUNAL DE
JUSTIÇA. LEGITIMIDADE ATIVA AD CAUSAM. OPERAÇÃO DE EMPRESA DE
TRANSPORTE. AUSÊNCIA DE AUTORIZAÇÃO DA AGÊNCIA NACIONAL DE
TRANSPORTE TERRESTRE -ANTT. INTERFERÊNCIA NA ATUAÇÃO FISCALIZATÓRIA
DO PODER PÚBLICO. GRAVE LESÃO À ORDEM PÚBLICA.
I - É dispensável o exaurimento da instância recursal para o
ajuizamento da medida de contracautela no Superior Tribunal de
Justiça.
II - Espécie em que a causa de pedir da ação ordinária é
eminentemente infraconstitucional - ou seja, poder regulatório da
Agência Nacional de Transporte Terrestre (ANTT) e violação ao art.
22 do Código de Defesa do Consumidor. Competência do Superior
Tribunal de Justiça.
III - Legitimidade ativa ad causam da requerente do pleito
suspensivo. Controvérsia acerca da prestação do serviço público a
ela também outorgado.
IV - A decisão sub judice causa grave lesão à ordem administrativa.
AANTT, responsável pela regulação da atividade em exame, não
autorizou administrativamente a operação da empresa Kandango
Transportes e Turismo Ltda. Interferência na atuação fiscalizatória
do Poder Público.
V - Potencial efeito de causar o desequilíbrio econômico-financeiro
das autorizações efetivadas pelaANTT. Interesse público. Atividade
não autorizada pela agência reguladora. Risco à segurança dos
passageiros.
VI - Preservação da continuidade do serviço público de transporte.
Informações daANTTno sentido de que há empresas regularmente
explorando trechos da linha São Paulo-Apodi. Razoabilidade da
alegação da agência de que nem todos os municípios têm que ser
ligados de forma direta.
VII - "Não pode o Poder Judiciário pretender suprir a omissão do
Executivo autorizando o funcionamento de serviços de transportes,
sob pena de desorganizar o modelo político da divisão de tarefas
pelos Poderes" (REsp n.º 661.122/PR). Precedentes do STJ.
Agravo regimental desprovido.
Decisão
Prosseguindo no julgamento, após o voto-vista do Ministro Felix
Fischer, vistos, relatados e discutidos os autos em que são partes
as acima indicadas, a Corte Especial, por unanimidade, negou
provimento ao agravo regimental nos termos do voto do Ministro
Relator. Os Ministros Felix Fischer, Maria Thereza de Assis Moura,
Herman Benjamin, Napoleão Nunes Maia Filho, Jorge Mussi, Luis Felipe
Salomão e Raul Araújo votaram com o Ministro Relator.
Não participaram do julgamento os Ministros João Otávio de Noronha e
Og Fernandes.
Ausentes, justificadamente, a Ministra Nancy Andrighi e os Ministros
Humberto Martins, Mauro Campbell Marques e Benedito Gonçalves.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('ANTT', '2025-07-12 17:38:40', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2018-03-13;1066294-1702065', 'AgInt no AREsp 1066294 / RS', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2018-03-13;1066294-1702065', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Aresp', '2018-03-13', NULL, 'ADMINISTRATIVO  E  PROCESSUAL  CIVIL.  AGRAVO  INTERNO  NO AGRAVO EM
RECURSO  ESPECIAL.ANTT.  FISCALIZAÇÃO.  TRANSPORTE  RODOVIÁRIO  DE
CARGAS.  LEI  10.233/2001.  RESOLUÇÃOANTT3.056/2009. CONTROVÉRSIA
RESOLVIDA,  PELO  TRIBUNAL  DE  ORIGEM,  À LUZ DAS PROVAS DOS AUTOS.
IMPOSSIBILIDADE   DE   REVISÃO,   NA  VIA  ESPECIAL.  SÚMULA  7/STJ.
CONTROVÉRSIA  QUE  EXIGE  ANÁLISE  DE  RESOLUÇÃO.  ATO NORMATIVO NÃO
INSERIDO  NO  CONCEITO  DE LEI FEDERAL. DIVERGÊNCIA JURISPRUDENCIAL.
DISSÍDIO NÃO DEMONSTRADO. AGRAVO INTERNO IMPROVIDO.
I. Agravo interno interposto contra decisão monocrática publicada em
03/08/2017,  que,  por  sua  vez,  julgara recurso interposto contra
decisum publicado na vigência do CPC/73.
II.  Na  origem,  trata-se  de  Ação  Ordinária, ajuizada pela parte
agravante  contra  a  Agência  Nacional  de Transportes Terrestres -ANTT,  objetivando  o reconhecimento da nulidade do Auto de Infração
2429664,  bem  como  das penalidades aplicadas no âmbito do processo
administrativo  50520.132201/2013-05, em face da não observância das
disposições previstas na ResoluçãoANTT3.056/2009, pela "conduta de
''evadir,  obstruir ou de qualquer forma, dificultar a fiscalização'',
em  04-10-2013, às 13:34h, à BR 392, Km 48, em Rio Grande/RS", assim
como  pela  desobediência  da  "sinalização  para adentrar à área de
fiscalização".  O  acórdão do Tribunal de origem reformou a sentença
para julgar improcedente o pedido inicial.
III. No caso, não obstante a apontada violação a dispositivos de lei
federal,  a  controvérsia  foi  dirimida, pelo Tribunal de origem, a
partir  da  análise da ResoluçãoANTT3.056/2009 - diploma normativo
que  não  se insere no conceito de lei federal -, fugindo, assim, da
hipótese constitucional de cabimento do Recurso Especial.
IV.  Na  forma  da jurisprudência, "a via especial é inadequada para
análise de Portarias, Resoluções, Regimentos, ou qualquer outro tipo
de norma que não se enquadre no conceito de Lei Federal" (STJ, AgInt
no  AREsp  801.104/DF, Rel. Ministro MAURO CAMPBELL MARQUES, SEGUNDA
TURMA, DJe de 13/10/2016).
V.   Descabimento   do   Recurso   Especial  com  base  no  dissídio
jurisprudencial,   pois   as  mesmas  razões  que  inviabilizaram  o
conhecimento  do  apelo, pela alínea a do permissivo constitucional,
servem de justificativa quanto à sua alínea c.
VI. Agravo interno improvido.
Decisão
Vistos,  relatados  e discutidos os autos em que são partes as acima
indicadas,  acordam  os  Ministros  da  Segunda  Turma  do  Superior
Tribunal  de  Justiça,  por  unanimidade, negar provimento ao agravo
interno, nos termos do voto da Sra. Ministra Relatora.
Os Srs. Ministros Herman Benjamin (Presidente), Og Fernandes e Mauro
Campbell Marques votaram com a Sra. Ministra Relatora.
Ausente, justificadamente, o Sr. Ministro Francisco Falcão.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('isenção', '2025-07-12 17:38:43', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:lei:1995-02-24;8989', 'Lei nº 8.989, de 24 de Fevereiro de 1995', 'urn:lex:br:federal:lei:1995-02-24;8989', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '1995-02-24', 'HIPOTESE ,  TRANSFERENCIA ,  DIREITOS ,  AQUISIÇÃO ,  AUTOMOVEL ,ISENÇÃO,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  MORTE ,  INCAPACIDADE ,  MOTORISTA PROFISSIONAL . NORMAS ,  CONCESSÃO ,ISENÇÃO,  IMPOSTO SOBRE PRODUTOS INDUSTRIALIZADOS (IPI) ,  OBJETIVO ,  AQUISIÇÃO ,  VEICULO AUTOMOTOR ,  AUTOMOVEL ,  UTILIZAÇÃO ,  TAXI ,  TRANSPORTE COLETIVO ,  PESSOA COM DEFICIENCIA ,  DEFICIENTE FISICO ,  TRANSPORTE ESCOLAR .', 'Dispõe sobreisençãodo Imposto sobre Produtos Industrializados (IPI) na aquisição de automóveis para utilização no transporte autônomo de passageiros, bem como por pessoas portadoras de deficiência física e aos destinados ao transporte escolar, e dá outras providências.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('isenção', '2025-07-12 17:38:43', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2020-11-25;1010', 'MPV 1010/2020', 'urn:lex:br:congresso.nacional:medida.provisoria;mpv:2020-11-25;1010', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Congresso Nacional', '2020-11-25', NULL, 'Isenta os consumidores dos Municípios do Estado do Amapá abrangidos pelo estado de calamidade pública do pagamento da fatura de energia elétrica referente aos últimos trinta dias e altera a Lei nº 10.438, de 26 de abril de 2002.

NOVA EMENTA: Isenta os consumidores dos Municípios do Estado do Amapá abrangidos pelo estado de calamidade pública do pagamento de fatura de energia elétrica nos termos em que especifica; altera as Leis nºs 10.438, de 26 de abril de 2002, 12.111, de 9 de dezembro de 2009, e 10.848, de 15 de março de 2004; e dá outras providência', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('isenção', '2025-07-12 17:38:43', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024-02-06;1206', 'MPV 1206/2024', 'urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024-02-06;1206', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Congresso Nacional', '2024-02-06', NULL, 'Altera os valores da tabela progressiva mensal do Imposto sobre a Renda da Pessoa Física de que trata o art. 1º da Lei nº 11.482, de 31 de maio de 2007.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;secao.especializada.1:acordao:1999-03-23;01483-1996-011-03-00-8', 'Acórdão TRT 3ª / Secao Especializada / 1999-03-23', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;secao.especializada.1:acordao:1999-03-23;01483-1996-011-03-00-8', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '1999-03-23', 'EXECUÇÃO -RASTREAMENTO- CONTA BANCÁRIA', 'EMENTA:  EXECUÇÃO  -RASTREAMENTODE CONTAS - INDEFERIMENTO  -  O  Juiz no comando da execução dispõe de meios eficazes para obter a  satisfação do crédito, mas não pode, para tanto, praticar ato que  viole  direitos ou garantias individuais do réu,  sem observar  o  devido  processo  legal.  Correto o indeferimento  de  pedido  derastreamentode contas pelo Banco Central, seguido de bloqueio de  possíveis  valores  existentes em estabelecimentos  bancários  em  nome dos sócios da executada. Agravo desprovido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2001-11-06;00156-1996-032-03-00-0', 'Acórdão TRT 3ª / Quinta Turma / 2001-11-06', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.5:acordao:2001-11-06;00156-1996-032-03-00-0', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2001-11-06', 'EXECUÇÃO -RASTREAMENTO- CONTA BANCÁRIA', 'EMENTA  -  EXECUÇÃO  -RASTREAMENTODE CONTAS  -  IMPOSSIBILIDADE
Porque  inespecífico e genérico,  não prospera o requerimento  do
Exeq"uente  no  sentido de ser oficiado o Banco Central do  Brasil
para fins derastreamentode contas dos Executados.  Uma pesquisa
tão   ampla  e  genérica  não  está  incluída  entre  as  medidas
necessárias ao cumprimento da obrigação pelo devedor, fugindo aos
limites  da  razoabilidade,  já  que  visa  atender  a  uma  mera
expectativa, distante e sem nenhum respaldo, sequer indiciário.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais;ponte.nova:municipal:lei:2019-10-11;4315', 'Lei n° 4315, de 11 de Outubro de 2019', 'urn:lex:br;minas.gerais;ponte.nova:municipal:lei:2019-10-11;4315', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2019-10-11', 'Luz Central -Rastreamento- 24 horas', 'Autoriza o Poder Executivo a conceder à empresa Luz Central deRastreamentoe Assistência 24 horas Ltda. o direito de uso de bem público da área que especifica.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2013-03-07;0099800-16.1996.5.03.0007', 'Acórdão TRT 3ª / Terceira Turma / 2013-03-07', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.3:acordao:2013-03-07;0099800-16.1996.5.03.0007', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2013-03-07', 'SISTEMA DE ATENDIMENTO AO JUDICIÁRIO (BACENJUD) -RASTREAMENTO- ENDEREÇO', 'EMENTA: EXECUÇÃO - NOVO ACIONAMENTO AO SISTEMA BACENJUD PARARASTREAMENTODE ENDEREÇO DO EXECUTADO - POSSIBILIDADE. Merece ser deferido o pleito do exequente de novo acionamento ao sistema Bacen-Jud com a finalidade de rastrear os dados cadastrais e o endereço dos executados, mormente quando a execução perdura há anos, já foram exauridos todos os meios executórios para a satisfação do crédito exequendo, além do que os sócios executados encontram em lugar incerto e não sabido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2013-09-25;0027800-28.2006.5.03.0149', 'Acórdão TRT 3ª / Quarta Turma / 2013-09-25', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.4:acordao:2013-09-25;0027800-28.2006.5.03.0149', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2013-09-25', 'SISTEMA DE ATENDIMENTO AO JUDICIÁRIO (BACENJUD) -RASTREAMENTO- ENDEREÇO', 'EMENTA: EXECUÇÃO - NOVO ACIONAMENTO AO SISTEMA BACENJUD PARARASTREAMENTODE ENDEREÇO DO EXECUTADO - POSSIBILIDADE. Nos termos do artigo 878 da CLT, "A execução poderá ser promovida por qualquer interessado, ou ex officio pelo próprio Juiz ou Presidente ou Tribunal competente (...)". Sendo assim, a satisfação do crédito trabalhista consiste no objetivo basilar da execução, para cujo alcance não pode o Poder Judiciário minimizar esforços, não sendo possível atribuir-se ao credor o encargo exclusivo de buscar incansavelmente pelos bens do Devedor. Lado outro, considerando-se que deve a Justiça do Trabalho buscar a máxima efetividade de suas decisões, é necessário o esgotamento dos meios possíveis ao prosseguimento da execução, devendo o Juízo efetivar as medidas requeridas pelo exequente. Merece ser deferida a pretensão do exequente inerente ao novo acionamento ao sistema Bacen-Jud com a finalidade de rastrear os dados cadastrais e o endereço dos executados, mormente quando a execução perdura há anos e já foram exauridos todos os meios executórios para a satisfação do crédito exequendo.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.2:acordao:2016-06-07;0199700-62.2013.5.16.0023', 'ACORDÃO TRT 16ª / 2ª Turma / RO 0199700-62.2013.5.16.0023', 'urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.2:acordao:2016-06-07;0199700-62.2013.5.16.0023', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 16', 'Tribunal Regional Trabalho', 'Acordao', '2016-06-07', 'ACIDENTE,ADVOCATÍCIOS,ASSISTÊNCIA,CIVIL,COMPROVAÇÃO,DANO,EMPREGADOR,HONORÁRIOS,JORNADA,MORAL,MOTORISTA,RASTREAMENTO,RECLAMADA,RECLAMANTE,RECURSO,RESPONSABILIDADE,SATÉLITE,SINDICAL,TRABALHO,TST', 'RECURSO DO RECLAMANTE. HONORÁRIOS ADVOCATÍCIOS. COMPROVAÇÃO DA ASSISTÊNCIA SINDICAL . Na hipótese dos autos, verifica-se que há declaração de hipossuficiência econômica, bem como restou comprovada a assistência por advogado credenciado pelo sindicato profissional, conforme termo de credenciamento. Ressalte-se que a Lei 5.584 /70 não estabelece uma forma específica para a comprovação da assistência sindical. Assim, são devidos os honorários advocatícios na forma da Súmula 219, I, do TST. RECURSO DA RECLAMADA. JORNADA DE TRABALHO. MOTORISTA.RASTREAMENTOPOR SATÉLITE. A utilização de veículo que tem sua trajetória rastreada por satélite que registra o momento em que o autor atende a cada um dos clientes possibilita o controle de jornada por parte do empregador e implica em não aplicação ao caso o art. 62, I, da CLT, sendo devidas, portanto, as horas extras.ACIDENTE DE TRABALHO - DANO MORAL - RESPONSABILIDADE CIVIL DO EMPREGADOR. A responsabilidade civil do empregador, por acidente de trabalho, prevista no art. 7º, XXVIII, da Constituição Federal, vincula-se ao elemento subjetivo do empregador, ou seja, "incorrer em dolo ou culpa". In casu, cabia ao empregador zelar pela integridade dos seus empregados, diligenciando, principalmente, o cumprimentos das medidas e normas de segurança e saúde no ambiente de trabalho. Não tendo obedecidos a tais normas de segurança assumiu o empregador o risco de dano sofrido pelo obreiro. Por isso, impõe-se-lhe a obrigação da indenização por dano moral.Recursos conhecidos. Improvido o do reclamado e parcialmente provido o do reclamante.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2015-01-22;0000062-34.2011.5.03.0135', 'Acórdão TRT 3ª / Segunda Turma / 2015-01-22', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2015-01-22;0000062-34.2011.5.03.0135', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2015-01-22', 'EXECUÇÃO -RASTREAMENTO- CONTA BANCÁRIA', 'EMENTA: EXECUÇÃO TRABALHISTA. RESPONSABILIDADE. SÓCIO RETIRANTE. Consoante disposto nos artigos 1.003, parágrafo único, e 1.032 do Código Civil, a responsabilidade do sócio retirante pelas dívidas da empresa somente pode ser reconhecida no período máximo de dois anos após a averbação da alteração contratual na Junta Comercial. Assim, in casu, proposta a reclamação trabalhista quando já transcorrido este biênio, impossível reconhecer a responsabilidade da ex-sócia pelo pagamento do crédito exequendo, ademais quando constatado que a prestação de labor da obreira se deu após a retirada da sócia da empresa reclamada.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2024-04-16;1967252-2429805', 'REsp 1967252 / RJ', 'urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2024-04-16;1967252-2429805', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2024-04-16', '"A decisão agravada, com efeito, teve por baliza o melhor
interesse da massa falida, e as conclusões do tribunal de origem
decorreram inquestionavelmente da análise da interpretação da
cláusula contratual acerca da remuneração de êxito e dos custos com
orastreamentode ativos no caso em análise, assim como do conjunto
fático-probatório carreado aos autos acerca dos indícios de desvio
de patrimônio da falida, o que se pode aferir da leitura dos
fundamentos do julgado atacado [...]".', 'RECURSO ESPECIAL. FALÊNCIA.RASTREAMENTOATIVOS. CONTRATAÇÃO.
REMUNERAÇÃO. ÊXITO. POSSIBILIDADE. MELHOR INTERESSE DA MASSA FALIDA.
PREQUESTIONAMENTO. AUSÊNCIA. SÚMULA Nº 211/STJ. FUNDAMENTAÇÃO
DEFICIENTE. SÚMULA Nº 284/STF. IMPUGNAÇÃO. INSUFICIÊNCIA. SÚMULA Nº
283/STF. REEXAME DE PROVAS E CLÁUSULAS. SÚMULAS NºS 5 E 7/STJ.
1. A questão controvertida resume-se a definir o critério de
remuneração da contratação de serviço derastreamentoe busca de
bens, no Brasil e no exterior, para satisfação dos credores da massa
falida.
2. Orastreamentoe a busca de ativos desviados de massas falidas
constituem procedimentos de risco, que, em muitos casos, não pode
ser assumido pela massa falida, o que justifica que o juízo da
falência, atento ao melhor interesse da massa, autorize a
contratação mediante honorários de êxito, com a assunção dos riscos
com o custeio das despesas para o trabalho pelo contratado.
3. Trata-se, na espécie, de honorários contratuais, estipulados
pelas partes, não se aplicando os critérios para o arbitramento dos
honorários do administrador judicial, previstos no art. 24, § 1º, da
Lei nº 11.101/2005, ou mesmo os limites dispostos no art. 85, § 2º,
do Código de Processo Civil, destinados à fixação dos honorários
sucumbenciais. Incidência da Súmula nº 284/STF.
4. Apesar de opostos embargos de declaração com a finalidade de
sanar omissão, a parte recorrente não indicou a contrariedade ao
art. 1.022 do Código de Processo Civil nas razões do especial,
atraindo a incidência da Súmula nº 211/STJ.
5. A subsistência de fundamento não impugnado apto a manter a
conclusão do aresto recorrido impõe o não conhecimento da pretensão
recursal. Súmula nº 283/STF.
6. Na hipótese, acolher a tese pleiteada pelo agravante exigiria
exceder os fundamentos do acórdão impugnado e adentrar no exame das
provas e cláusulas contratuais, procedimentos vedados em recurso
especial, a teor das Súmulas nºs 5 e 7/STJ.
7. Recurso especial não conhecido.
Decisão
Vistos e relatados estes autos em que são partes as acima indicadas,
prosseguindo no julgamento, após o voto-vista do Sr. Ministro
Ricardo Villas Bôas Cueva inaugurando a divergência e a ratificação
do voto do Sr. Ministro Humberto Martins, decide a Terceira Turma,
por maioria, não conhecer do recurso especial, nos termos do voto do
Sr. Ministro Ricardo Villas Bôas Cueva, que lavrará o acórdão.
Vencido o Sr. Ministro Humberto Martins (Presidente) que dava
parcial provimento.
Votaram com o Sr. Ministro Ricardo Villas Bôas Cueva os Srs.
Ministros Moura Ribeiro e Nancy Andrighi.
Não participou do julgamento o Sr. Ministro Marco Aurélio Bellizze
(art. 162, § 4º do RISTJ).', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.3:acordao;aresp:2016-03-15;813686-1524095', 'AgRg no AREsp 813686 / SP', 'urn:lex:br:superior.tribunal.justica;turma.3:acordao;aresp:2016-03-15;813686-1524095', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Aresp', '2016-03-15', '"[...]   a  impossibilidade  de  reexame  de  provas  impede  o
conhecimento do recurso por ambas as alíneas do inciso III do artigo
105 da Constituição Federal".
     "[...]  a  condenação  da agravante ao pagamento de indenização
que  incluiu o valor do veículo subtraído não decorre da equiparação
do  contrato  derastreamentoao  contrato de seguro, mas, sim, da
mensuração  do dano material decorrente da falha da sua prestação de
serviço".', 'AGRAVO REGIMENTAL NO AGRAVO EM RECURSO ESPECIAL. CIVIL. INDENIZAÇÃO.
CONTRATO DERASTREAMENTODE VEÍCULO. FALHA NA PRESTAÇÃO DO SERVIÇO.
AFASTAMENTO. IMPOSSIBILIDADE. REEXAME DE PROVAS.
1.  É vedada a percuciente incursão na esfera probatória, haja vista
o óbice previsto na Súmula nº 7/STJ.
2.  No  caso,  afastar  a  falha  na  prestação  do  serviço,  e por
consequência  a responsabilidade da agravante, é pretensão que exige
o vedado reexame das circunstâncias fáticas.
3. Agravo regimental não provido.
Decisão
Vistos  e  relatados  estes  autos,  em  que  são  partes  as  acima
indicadas,   decide   a   Terceira  Turma,  por  unanimidade,  negar
provimento  ao agravo regimental, nos termos do voto do Sr. Ministro
Relator.  Os  Srs.  Ministros Marco Aurélio Bellizze, Moura Ribeiro,
João  Otávio  de  Noronha  (Presidente) e Paulo de Tarso Sanseverino
votaram com o Sr. Ministro Relator.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais;divinopolis:municipal:lei.complementar:2022-07-05;226', 'Lei Complementar n° 226, de 05 de Julho de 2022', 'urn:lex:br;minas.gerais;divinopolis:municipal:lei.complementar:2022-07-05;226', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '2022-07-05', 'Altera dispositivos relativos ao Imposto Sobre Serviços de Qualquer Natureza - ISSQN - contidos na Lei Complementar nº 007, de 28 de dezembro de 1991 - Serviços de guarda, estacionamento, armazenamento, vigilância e congêneres - 11.05 - Serviços relacionados ao monitoramento erastreamentoa distância, em qualquer via ou local, de veículos, cargas, pessoas e semoventes em circulação ou movimento, realizados por meio de telefonia móvel, transmissão de satélites, rádio ou qualquer outro meio, inclusive pelas empresas de Tecnologia da Informação Veicular, independentemente de o prestador de serviços ser proprietário ou não da infraestrutura de telecomunicações que utiliza.', 'Altera dispositivos relativos ao Imposto Sobre Serviços de Qualquer Natureza - ISSQN - contidos na Lei Complementar nº 007, de 28 de dezembro de 1991 - Serviços de guarda, estacionamento, armazenamento, vigilância e congêneres - 11.05 - Serviços relacionados ao monitoramento erastreamentoa distância, em qualquer via ou local, de veículos, cargas, pessoas e semoventes em circulação ou movimento, realizados por meio de telefonia móvel, transmissão de satélites, rádio ou qualquer outro meio, inclusive pelas empresas de Tecnologia da Informação Veicular, independentemente de o prestador de serviços ser proprietário ou não da infraestrutura de telecomunicações que utiliza.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-03-20;190-2014-222-5-0', 'Acórdão do processo Nº RR - 190-25.2014.5.05.0222', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-03-20;190-2014-222-5-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2018-03-20', NULL, 'I - AGRAVO. AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Dou provimento para analisar o agravo de instrumento. II - AGRAVO DE INSTRUMENTO. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Observo possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. III - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DE TACÓGRAFO ERASTREAMENTO. Na hipótese, o TRT esclarece que havia tacógrafo erastreamentopor satélite. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-11-27;2128-2012-242-9-0', 'Acórdão do processo Nº RR - 2128-52.2012.5.09.0242', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2018-11-27;2128-2012-242-9-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2018-11-27', NULL, 'I - AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DERASTREAMENTO. Observa-se possível violação ao art. 62, I, da CLT. Agravo de instrumento conhecido e provido. II - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. EXISTÊNCIA DERASTREAMENTO. Na hipótese, o TRT esclarece que haviarastreamentodos veículos. Para configuração da hipótese do art. 62, I, da CLT não se exige a simples constatação de exercício de atividade externa, mas, sim, daquela que, por sua natureza, seja incompatível com a fixação ou possibilidade de controle direto ou indireto da jornada de trabalho. Do exame do acórdão regional, infere-se a possibilidade de controle da jornada do empregado, pois o veículo utilizado pelo autor era equipado com dispositivo derastreamentovia satélite. A jurisprudência desta Corte Superior firmou entendimento de que o sistema de monitoramento erastreamentoviabiliza o controle de jornada do empregado. Precedentes. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.24:tribunal.regional.trabalho;turma.2:acordao:2013-12-04;0001300-54.2010.5.24.0001', 'ACÓRDÃO TRT 24ª / 2ª Turma / RO.1 0001300-54.2010.5.24.0001', 'urn:lex:br;justica.trabalho;regiao.24:tribunal.regional.trabalho;turma.2:acordao:2013-12-04;0001300-54.2010.5.24.0001', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 24', 'Tribunal Regional Trabalho', 'Acordao', '2013-12-04', 'HORA EXTRA', 'HORAS EXTRAS. MOTORISTA. CONTROLE DE
JORNADA PORRASTREAMENTOVIA SATÉLITE.
CONVENÇÃO COLETIVA EXCLUINDO ESSE
PROCEDIMENTO COMO FORMA DE CONTROLE DE
JORNADA. Orastreamentodo caminhão via
satélite não era feito pela reclamada,
mas sim por empresa seguradora, pessoa
diversa e estranha à relação
empregatícia. Destarte, por entender
que a reclamada não controlava a
jornada de trabalho do autor pelo
sistema derastreamentodo caminhão via
satélite, bem como por haver norma
coletiva desconsiderando o sistema derastreamentopor satélite com
finalidade de controle da jornada de
trabalho, concluo que o autor não
estava sujeito a controle de jornada.
Recurso improvido, por unanimidade.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2021-06-08;10890-2016-18-18-0', 'Acórdão do processo Nº RR - 10890-59.2016.5.18.0018', 'urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2021-06-08;10890-2016-18-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2021-06-08', NULL, 'A) AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA (APPLE BENEFICIAMENTO E LOGISTICA LTDA-EPP). ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DA LEI Nº 13.015/2014 E ANTES DA VIGÊNCIA DA LEI 13.467/2017.  1. JORNADA DE TRABALHO. MOTORISTA. CONTROLE POR SISTEMA DERASTREAMENTOVIA SATÉLITE. CONHECIMENTO E PROVIMENTO. I. Hipótese em que o Tribunal Regional entendeu que orastreamentode veículo via satélite não serve como efetiva prova de controle de jornada do empregado motorista. II. Demonstrada divergência jurisprudencial quanto ao tema. III. Agravo de instrumento de que se conhece e a que se dá provimento, para determinar o processamento do recurso de revista, observando-se o disposto no ATO SEGJUD.GP Nº 202/2019 do TST.  B) RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA (APPLE BENEFICIAMENTO E LOGISTICA LTDA-EPP). ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DA LEI Nº 13.015/2014 E ANTES DA VIGÊNCIA DA LEI 13.467/2017.  1. JORNADA DE TRABALHO. MOTORISTA. CONTROLE POR SISTEMA DERASTREAMENTOVIA SATÉLITE. CONHECIMENTO E PROVIMENTO. I. A jurisprudência desta Corte Superior é no sentido de que orastreamentovia satélite viabiliza o controle da jornada de trabalho do empregado motorista, porquanto se realiza por meio de aparelho que capta sinais de GPS e permite a transmissão de dados como a localização exata do veículo, tempo no qual ficou parado, bem como a velocidade em que trafega. II. No caso dos autos, consta do acórdão regional que a Reclamada apresentou relatórios, oriundos de sistema derastreamentode veículo via satélite, para controle de jornada do Reclamante. III.  Logo, conforme entendimento desta Corte Superior, os relatórios obtidos por sistema derastreamentovia satélite são viáveis para o efetivo controle de jornada de empregado motorista. Recurso de revista de que se conhece, por divergência jurisprudencial, e a que se dá provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;ed:2020-10-20;107100-1998-16-2-0', 'Acórdão do processo Nº ED-AIRR - 107100-58.1998.5.02.0016', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;ed:2020-10-20;107100-1998-16-2-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Ed', '2020-10-20', NULL, 'EMBARGOS DE DECLARAÇÃO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. CERCEAMENTO DO DIREITO DE DEFESA - NULIDADE DA ARREMATAÇÃO DE BEM IMÓVEL POR VÍCIO DE NOTIFICAÇÃO POSTAL DO LEILÃO JUDICIAL - AUSÊNCIA DE JUNTADA DO AVISO DE RECEBIMENTO OU COMPROVANTE DERASTREAMENTO-  NÚMEROS DERASTREAMENTOEMITIDOS PELOS CORREIOS -  PREQUESTIONAMENTO - APLICAÇÃO DO ARTIGO 896, §1º-A, I, DA CLT. A 3ª Turma do TST afastou a transcendência do recurso de revista de ROSEMEIRE ARANIBAR LOPEZ SOARES DA SILVA E OUTRO, notadamente em razão de o acórdão de agravo de petição estar em sintonia com a Súmula/TST nº 16, sendo irrelevante a ausência de juntada de aviso de recebimento para se ter presumida a notificação quarenta e oito horas depois de sua postagem. Este Colegiado acrescentou que a questão concernente aos números derastreamentoemitidos pelos Correios não se encontra prequestionada na decisão recorrida, razão pela qual incide o artigo 896, §1º-A, da CLT, no particular. Os embargantes sustentam que "o acórdão embargado foi omisso quanto à análise das provas relativas ao prequestionamento relacionado à ausência de números derastreamentoemitidos pelos Correios". Argumentam que "a discussão sobre a absoluta impossibilidade de os Recorrentes produzirem a prova que deles é exigida, ante a falta de informações básicas de materialidade da postagem, foi expressamente prequestionada junto ao Tribunal de origem, não havendo margem para dúvidas de que os recorrentes trataram expressamente da ausência de números derastreamentodas postagens". Afirmam que "os argumentos relacionados à falta de código derastreamentodas correspondências" foram expostos nos embargos de declaração opostos contra o acórdão de agravo de petição. Asseveram que "o Tribunal a quo simplesmente desconsiderou os argumentos acima reproduzidos, rejeitando os embargos sem enfrentar a discussão jurídica apresentada". Alegam que "não se trata, portanto, de falta de prequestionamento, mas sim de verdadeira recusa à prestação jurisdicional por parte do Tribunal Regional do Trabalho da 2ª Região". Aduzem que "esta C. Turma foi absolutamente omissa quanto à comprovação de que os embargantes não dispunham de meios possíveis para a comprovação da não-entrega das cartas de intimação". Destacam que "os recorrentes não têm meios de provar que a correspondência não foi entregue em suas residências, uma vez que não há nos autos elementos para a rastreabilidade das cartas de intimação". Insistem que "não há nos autos o aviso de recebimento das correspondências e não há o código derastreamentodessas cartas". Colacionam decisão da 5ª Turma do TST. Defendem a transcendência política e jurídica do recurso de revista e invocam os princípios constitucionais do contraditório e da ampla defesa. Equivoca-se o polo embargante ao sugerir que as razões de recurso de natureza ordinária dirigido ao Tribunal Regional configurariam o prequestionamento exigido pelo artigo 896, §1º-A, I, da CLT. Na verdade, considera-se prequestionada a tese jurídica, ou a questão fática a ela imprescindível, quando a decisão impugnada adotar entendimento explícito a respeito. Esse, aliás, é o teor do item I da Súmula/TST nº 297. E nem se insista no argumento de que a circunstância relativa aos números derastreamentoemitidos pelos Correios estaria prequestionada pela mera oposição de embargos declaratórios acerca dessa temática contra o acórdão de agravo de petição. É que o prequestionamento ficto abraçado pelo item III da Súmula/TST nº 297 é restrito à matéria de direito, não alcançando os fatos que instruem o processo. Os recorrentes deveriam ter suscitado a alegada omissão do Tribunal Regional em preliminar de nulidade por negativa de prestação jurisdicional; não o fazendo, assumiram as consequências de sua inércia, haja vista a impossibilidade de trânsito do recurso de revista no aspecto, em virtude do obstáculo de natureza instrumental do artigo 896, §1º-A, I, da CLT. Embargos de declaração conhecidos e providos, apenas para prestar esclarecimentos, sem conferir efeito modificativo ao julgado. PENALIDADES PROCESSUAIS REQUERIDAS EM CONTRARRAZÕES. SUELI FLORENTINO alega que a irresignação dos embargantes quanto ao prequestionamento do número derastreamentodos Correios não passa de expediente dissimulatório e procrastinatório, que enseja a aplicação da penalidade prevista no artigo 81 do CPC. Sustenta que a utilização dos declaratórios como sucedâneo recursal também dá azo à multa do artigo 1.026, §2º, do CPC. Ao contrário do que sugere a embargada, os presentes embargos de declaração não denotam intuito protelatório, apenas desconhecimento a respeito do que seria prequestionamento. Note-se que os embargantes chegam a expor que "o Tribunal a quo simplesmente desconsiderou os argumentos acima reproduzidos, rejeitando os embargos sem enfrentar a discussão jurídica apresentada", argumento que contradiz suas próprias razões de declaratórios e que ratifica tanto a ausência de tese do Tribunal Regional acerca do número derastreamentodos Correios quanto a aplicação do artigo 896, §1º-A, I, da CLT neste particular. Pedidos formulados em contrarrazões indeferidos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2022-09-27;2076095-2212753', 'AREsp 2076095 / RS', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;aresp:2022-09-27;2076095-2212753', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Aresp', '2022-09-27', '"[...] a mera conduta que implique em riscos de dano ao meio
ambiente, ainda que materialmente não concretizados, já é suficiente
para configurar uma infração administrativa passível de autuação e
de sanção pecuniária [...]".', 'ADMINISTRATIVO. PESCA DE PARELHA. SISTEMA PREPS DERASTREAMENTOINOPERANTE. INFRAÇÃO AMBIENTAL. MULTA E APREENSÃO DO PESCADO. AÇÃO
ANULATÓRIA DOS AUTOS DE INFRAÇÃO. ALEGAÇÃO DE PESCA NA MODALIDADE
PARELHA. EMBARCAÇÕES QUE NAVEGAM LADO-A-LADO. SISTEMA DERASTREAMENTODE UMA EMBARCAÇÃO EM OPERAÇÃO. PELO QUE COMPROVARIA A
PRESENÇA DA OUTRA FORA DO ZONA DE EXCLUSÃO. SENTENÇA DE PROCEDÊNCIA
DA AÇÃO ANULATÓRIA. ACÓRDÃO CONFIRMANDO A SENTENÇA. RECURSO ESPECIAL
DO IBAMA. PEDIDO DE MANUTENÇÃO DOS AUTOS DE INFRAÇÃO. ALEGAÇÃO DA
HIGIDEZ DA AUTUAÇÃO. NAVEGAÇÃO SEMRASTREAMENTOOBRIGATÓRIO EM
DESACORDO COM A AUTORIZAÇÃO EMITIDA. RECURSO ESPECIAL PROVIDO.
INFRAÇÃO ADMINISTRATIVA FORMAL CONSTATADA. INDEPENDENDO DA
OCORRÊNCIA DE INFRAÇÃO ADMINISTRATIVA MATERIAL. MANUTENÇÃO DOS AUTOS
DE INFRAÇÃO.
I. Na origem, trata-se de ação anulatória de auto de infração
decorrente de atividade pesqueira com embarcação sem orastreamentoobrigatório (Sistema PREPS).
II. Sentença dando provimento à pretensão autoral de anulação dos
autos de infração, entendendo que, por se tratar de pesca na
modalidade parelha, o funcionamento do sistema derastreamentode
uma das embarcações comprovaria a presença da outra no mesmo local,
ou seja, fora da zona de exclusão.
III. Apelação da autarquia ambiental, entendimento de que o cruzeiro
de pesca não atendeu à autorização emitida pelo órgão competente,
que previarastreamentoobrigatório nas embarcações.
IV. Acórdão confirmando a sentença de primeiro grau, entendendo que,
por se tratar de pesca na modalidade parelha, o sinal emitido por
uma das embarcações comprovaria a presença da outra no mesmo local.
V. Recurso especial do IBAMA a regularidade e legalidade da
autuação, tendo em vista o não atendimento, pelos recorridos, das
exigências previstas na autorização de pesca emitida, além de que
não seria possível assegurar que a embarcação semrastreamentotenha, de fato, se limitado fora da zona de exclusão.
VI. Recurso especial provido. Constatação que de fato houve infração
administrativa formal, consistente em navegação pesqueira com o
Sistema PREPS inoperante/desativado, não sendo o caso de se
rediscutir eventuais justificativas da inocorrência de infração
administrativa material, ou seja, de não ter havido a efetiva pesca
de arrasto dentro da área de exclusão.
VII. Agravo conhecido para dar provimento ao recurso especial do
IBAMA e restabelecer a higidez dos autos de infração.
Decis?o
Vistos, relatados e discutidos os autos em que são partes as acima
indicadas, acordam os Ministros da Segunda Turma do Superior
Tribunal de Justiça,  por unanimidade, conhecer do agravo para dar
provimento ao recurso especial, nos termos do voto do Sr.
Ministro-Relator." Os Srs. Ministros Herman Benjamin, Mauro Campbell
Marques e Assusete Magalhães votaram com o Sr. Ministro Relator.
Ausente, justificadamente, o Sr. Ministro Humberto Martins.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2023-05-16;2580', 'PL 2580/2023', 'urn:lex:br:camara.deputados:projeto.lei;pl:2023-05-16;2580', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Camara Deputados', '2023-05-16', NULL, 'Dispõe mecanismo derastreamentodigital obrigatório para operações envolvendo ouro.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2002-05-02;6672', '[ Projeto de Lei (CD) nº 6672/2002 > Projeto de Lei da Câmara nº 24/2007 : Lei nº 11.903 de 14/01/2009 ]', 'urn:lex:br:senado.federal:projeto.lei;plc:2007;24', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Senado Federal', '2002-05-02', NULL, 'Cria orastreamentoda produção e consumo de medicamentos por meio do controle eletrônico por códigos de barra.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2016-05-11;1314-2011-802-4-0', 'Acórdão do processo Nº RR - 1314-81.2011.5.04.0802', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2016-05-11;1314-2011-802-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2016-05-11', NULL, 'I - AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. HORAS EXTRAS. TRABALHADOR EXTERNO. CONTROLE DE JORNADA.RASTREAMENTOVIA SATÉLITE. POSSIBILIDADE. Demonstrada divergência jurisprudencial, impõe-se o provimento do agravo de instrumento para determinar o processamento do recurso de revista. Agravo de instrumento provido.   II - RECURSO DE REVISTA 1 - ADICIONAL DE PERICULOSIDADE. INDEVIDO. MOTORISTA. ACOMPANHAMENTO DE ABASTECIMENTO DO VEÍCULO SEM OPERAR A BOMBA DE COMBUSTÍVEL. A atividade do reclamante de conduzir o veículo ao posto de combustível para abastecê-lo, acompanhando o abastecimento sem operação da bomba não enseja o pagamento do adicional de periculosidade, porquanto não está inserida na Norma Regulamentadora 16 do Ministério do Trabalho. Precedentes da SBDI-1 do TST. Ressalva do entendimento pessoal da relatora. Recurso de revista não conhecido.  2 - HORAS EXTRAS. TRABALHADOR EXTERNO. CONTROLE DE JORNADA.RASTREAMENTOVIA SATÉLITE. POSSIBILIDADE. A jurisprudência deste Tribunal Superior tem se consolidado no sentido de que orastreamentovia satélite viabiliza o controle da jornada de trabalho do empregado motorista. E no caso em apreço, a empresa possuíarastreamentopor via satélite, viabilizando a plena possibilidade do controle da jornada do trabalhador. Precedentes. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2015-09-09;374-2012-871-4-0', 'Acórdão do processo Nº RR - 374-69.2012.5.04.0871', 'urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2015-09-09;374-2012-871-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2015-09-09', NULL, 'RECURSO DE REVISTA - HORAS EXTRAORDINÁRIAS -  MOTORISTA DE CAMINHÃO -  TRABALHO EXTERNO -  POSSIBILIDADE DE CONTROLE DE JORNADA DE TRABALHO VIARASTREAMENTOVIA SATÉLITE -  INAPLICABILIDADE DO ART. 62, I, DA CLT -  INVALIDADE DAS NORMAS COLETIVAS QUE PREVIAM A IMPOSSIBILIDADE DE CONTROLE PELO SISTEMA DERASTREAMENTO. Diante do contexto fático-probatório delineado nos autos, insuscetível de reexame neste momento processual, nos termos da Súmula nº 126 do TST, constata-se que o entendimento esposado no acórdão regional está em consonância com a jurisprudência atual e remansosa desta Corte, no sentido de que orastreamentovia satélite consiste em meio efetivo para controle da jornada de trabalho do empregado motorista, haja vista demonstrar a localização exata do veículo, o tempo de parada e, ainda, a velocidade desenvolvida. Tal realidade que prevalece, inclusive, sobre as normas coletivas que previam a impossibilidade de controle mediante o sistema derastreamento. Incidência da Súmula nº 333 do TST. Recurso de revista não conhecido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2022-03-09;11048-2019-8-18-0', 'Acórdão do processo Nº RR - 11048-42.2019.5.18.0008', 'urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2022-03-09;11048-2019-8-18-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2022-03-09', NULL, 'AGRAVO EM AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. LEI Nº 13.467/2017. NULIDADE DA CITAÇÃO. NÃO RECEBIMENTO. ÔNUS DE PROVA DO DESTINATÁRIO. AUSÊNCIA DE AVISO DE RECEBIMENTO (AR).RASTREAMENTO. VALIDADE. ACÓRDÃO REGIONAL. RECORRIBILIDADE IMEDIATA. NATUREZA NÃO INTERLOCUTÓRIA. SÚMULA Nº 214, "A", DO TST. Constatado equívoco na decisão agravada, dá-se provimento ao agravo para determinar o processamento do agravo de instrumento. AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. NULIDADE DA CITAÇÃO. NÃO RECEBIMENTO. ÔNUS DE PROVA DO DESTINATÁRIO. AUSÊNCIA DE AVISO DE RECEBIMENTO (AR).RASTREAMENTO. VALIDADE. TRANSCENDÊNCIA POLÍTICA CONSTATADA. Agravo de instrumento a que se dá provimento, para determinar o processamento do recurso de revista, em face de haver sido demonstrada possível contrariedade à Súmula nº 16 do Tribunal Superior do Trabalho. RECURSO DE REVISTA. LEI Nº 13.467/2017. NULIDADE DA CITAÇÃO. NÃO RECEBIMENTO. ÔNUS DE PROVA DO DESTINATÁRIO. SÚMULA Nº 16 DO TST. AUSÊNCIA DE AVISO DE RECEBIMENTO (AR).RASTREAMENTO. VALIDADE. TRANSCENDÊNCIA POLÍTICA CONSTATADA. Nos termos da Súmula nº 16 deste Tribunal Superior, "Presume-se recebida a notificação 48 (quarenta e oito) horas depois de sua postagem. O seu não-recebimento ou a entrega após o decurso desse prazo constitui ônus de prova do destinatário.". Ainda segundo dispõe o artigo 841, § 1º, da CLT, a citação (notificação inicial), no Processo do Trabalho, não necessita ocorrer pessoalmente para que seja considerada válida, a tanto bastando que seja entregue no endereço correto. Na espécie, ressalte-se que o TRT assim registrou: "No caso dos autos, verifico que foi enviada à reclamada notificação postal (código derastreamentoMH086364946BR), no endereço informado na petição inicial, sem o aviso de recebimento - AR. Entendo que o fato de constar na consulta feita ao site dos Correios que a referida notificação foi recebida pelo destinatário em 23/07/2019 às 14h01min, não confere a segurança necessária à confirmação da prática do ato citatório válido e regular, ante a ausência de recibo de entrega devidamente assinado". O que representa a prova cabal do registro, pelorastreamento, da entrega, independentemente de assinatura no aviso de recebimento e de que não houve prova no sentido contrário ao que atesta a mencionada comprovação. Nesse contexto, entende esta Corte Superior que a ausência do Aviso de Recebimento (AR) não é suficiente, por si só, a caracterizar irregularidade no recebimento e consequente nulidade da citação, porquanto -  reitere-se -  há prova cabal do registro da entrega, pelorastreamento, tal como registrado no caso. Precedentes. Transcendência política constatada. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;rr:2017-04-05;184100-2009-32-3-0', 'Acórdão do processo Nº RR - 184100-73.2009.5.03.0032', 'urn:lex:br:tribunal.superior.trabalho;turma.6:acordao;rr:2017-04-05;184100-2009-32-3-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2017-04-05', NULL, 'I - AGRAVO DE INSTRUMENTO. HORAS EXTRAS.RASTREAMENTO. JORNADA DE TRABALHO. CONTROLE EXTERNO. Agravo de instrumento provido ante a existência de divergência jurisprudencial. II -  RECURSO DE REVISTA. HORAS EXTRAS.RASTREAMENTO. JORNADA DE TRABALHO. CONTROLE EXTERNO. O contexto probatório trazido no acórdão recorrido evidencia ser plenamente possível o controle da jornada do reclamante, considerando que haviarastreamentopela seguradora do trajeto do veículo conduzido pelo obreiro, bem como constantes mensagens enviadas pela reclamada para que o motorista informasse a localização. Note-se que a jurisprudência desta Corte é no sentido de que basta haver a possibilidade de controle da jornada,ainda que de forma indireta, para que o trabalhador externonão seja enquadrado na exceção do art. 62, I, da CLT. Há precedentes. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2015-04-08;36-2011-103-3-0', 'Acórdão do processo Nº RR - 36-35.2011.5.03.0103', 'urn:lex:br:tribunal.superior.trabalho;turma.2:acordao;rr:2015-04-08;36-2011-103-3-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2015-04-08', NULL, 'I - AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA. HORAS EXTRAS. TRABALHADOR EXTERNO. CONTROLE DE JORNADA.RASTREAMENTOVIA SATÉLITE. POSSIBILIDADE. Demonstrada divergência jurisprudencial, impõe-se o provimento do agravo de instrumento para determinar o processamento do recurso de revista. Agravo de instrumento provido.   II - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHADOR EXTERNO. CONTROLE DE JORNADA.RASTREAMENTOVIA SATÉLITE. POSSIBILIDADE. A jurisprudência deste Tribunal Superior tem se consolidado no sentido de que orastreamento via satélite viabiliza ocontrole da jornadade trabalho do empregado motorista. E no caso em apreço, a empresa possuíarastreamentopor via satélite, viabilizando a plena possibilidade do controle da jornada do trabalhador. Precedentes. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;rr:2021-09-01;20-2018-669-9-0', 'Acórdão do processo Nº RR - 20-20.2018.5.09.0669', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;rr:2021-09-01;20-2018-669-9-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2021-09-01', NULL, 'I - AGRAVO DE INSTRUMENTO. PROVIMENTO. HORAS EXTRAS. TRABALHO EXTERNO. POSSIBILIDADE DE CONTROLE DE JORNADA.RASTREAMENTOVIA SATÉLITE.POTENCIAL VIOLAÇÃO DO ART. 62, I, DA CLT. Diante de potencial violação do art. 62, I, da CLT, merece processamento o recurso de revista. Agravo de instrumento conhecido e provido. II - RECURSO DE REVISTA. HORAS EXTRAS. TRABALHO EXTERNO. POSSIBILIDADE DE CONTROLE DE JORNADA.RASTREAMENTOVIA SATÉLITE. A jurisprudência desta Corte firmou-se no sentido de que,factível o controle de jornada, ainda que por meio indireto -  sistema derastreamentovia satélite -, é necessário o respeito ao limite diário a que alude o art. 7º, XIII, da Constituição Federal, sendo devida a remuneração extra das horas que o ultrapassarem. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.1:acordao;rms:2019-03-25;44501-1816511', 'EDcl nos EDcl no AgInt no RMS 44501 / AL', 'urn:lex:br:superior.tribunal.justica;turma.1:acordao;rms:2019-03-25;44501-1816511', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Rms', '2019-03-25', '"O   andamento  dorastreamentofornecido  pela  agência  dos
correios  não  é  suficiente  para  comprovar  a  efetiva entrega da
petição original ao tribunal de origem".', 'PROCESSUAL  CIVIL. EMBARGOS DE DECLARAÇÃO NOS EMBARGOS DE DECLARAÇÃO
NO  AGRAVO INTERNO NO RECURSO EM MANDADO DE SEGURANÇA. ART. 1.022 DO
CPC/2015.  OMISSÃO CONFIGURADA. 1. Nos termos do que dispõe o artigo
1.022  do  CPC/2015,  cabem  embargos  de declaração contra qualquer
decisão  judicial para esclarecer obscuridade, eliminar contradição,
suprir  omissão de ponto ou questão sobre a qual devia se pronunciar
o  juiz  de  ofício  ou  a requerimento, bem como para corrigir erro
material.
2.  A  tempestividade do recurso interposto para o Superior Tribunal
de  Justiça  é  aferida  pelo  registro  no  protocolo da Secretaria
Tribunal  de  origem.  Ao  optar  pelos  serviços  dos  Correios,  a
pontualidade,  fidelidade  e  efetiva entrega da petição original no
protocolo   do  Tribunal  constitui  responsabilidade  exclusiva  do
recorrente,  de  forma  que  o  protocolo fora do prazo não pode ser
imputado  ao serventuário da justiça. Nesse sentido: EDcl no AgRg no
AREsp   525.757/ES,  Rel.  Ministro  Olindo  Menezes  (Desembargador
Convocado  do TRF 1ª Região), Primeira Turma, DJe 26/6/2015; AgRg no
AREsp  434.324/SP, Rel. Ministro Sebastião Reis Júnior, Sexta Turma,
DJe  13/10/2014)  3.  Embargos de declaração acolhidos, para sanar a
omissão apontada, sem efeitos infringentes.
Decisão
Vistos e relatados estes autos em que são partes as acima indicadas,
acordam  os  Ministros  da  Primeira  Turma  do Superior Tribunal de
Justiça,  por  unanimidade,  acolher  os embargos de declaração, sem
efeitos modificativos, nos termos do voto do Sr. Ministro Relator.
Os  Srs.  Ministros Napoleão Nunes Maia Filho, Sérgio Kukina, Regina
Helena Costa e Gurgel de Faria votaram com o Sr. Ministro Relator.
Presidiu o julgamento a Sra. Ministra Regina Helena Costa.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:federal:lei:2009-01-14;11903', 'Lei nº 11.903, de 14 de Janeiro de 2009', 'urn:lex:br:federal:lei:2009-01-14;11903', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Federal', '2009-01-14', 'CRIAÇÃO ,  SISTEMA NACIONAL ,  CONTROLE ,  PRODUÇÃO ,  CONSUMO ,  COMERCIALIZAÇÃO ,  PRESCRIÇÃO MEDICA ,  ODONTOLOGIA ,  VETERINARIA ,  MEDICAMENTOS ,  PRODUTO FARMACEUTICO ,  UTILIZAÇÃO ,  TECNOLOGIA ,  PROCESSO ELETRONICO ,  INFORMATICA .', 'Dispõe sobre orastreamentoda produção e do consumo de medicamentos por meio de tecnologia de captura, armazenamento e transmissão eletrônica de dados.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:camara.deputados:projeto.lei;pl:2012-06-12;4047', '[ Projeto de Lei (CD) nº 4047/2012 > Projeto de Lei da Câmara nº 127/2013 ]', 'urn:lex:br:senado.federal:projeto.lei;plc:2013;127', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Senado Federal', '2012-06-12', NULL, 'Torna obrigatória a utilização de mecanismo derastreamentode carga durante o transporte de materiais nucleares e radioativos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2016-06-09;0010445-49.2015.5.03.0097', 'Acórdão PJe TRT 3ª / Oitava Turma / 2016-06-09', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.8:acordao:2016-06-09;0010445-49.2015.5.03.0097', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2016-06-09', 'NOTIFICAÇÃO - RECEBIMENTO', 'NOTIFICAÇÃO. VIA POSTAL. AUSÊNCIA DO AVISO DE RECEBIMENTO.RASTREAMENTODO CORREIO. VALIDADE. No processo do trabalho, a citação/notificação é impessoal, porquanto realizada via postal (artigo 841 da CLT). Assim, orastreamentoda postagem mediante o número de registro emitido pelos correios, mostra-se perfeitamente válido para aferir o recebimento da notificação e, por conseguinte o aperfeiçoamento deste ato processual.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rastreamento', '2025-07-12 17:38:56', 'https://www.lexml.gov.br/urn/urn:lex:br:conselho.administrativo.recursos.fiscais;secao.julgamento.3;camara.3;turma.ordinaria.2:acordao:2020-09-22;3302-009.336,8549740', 'Acórdão nº 3302-009.336 do Processo 19311.720044/2015-69', 'urn:lex:br:conselho.administrativo.recursos.fiscais;secao.julgamento.3;camara.3;turma.ordinaria.2:acordao:2020-09-22;3302-009.336,8549740', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Conselho Administrativo Recursos Fiscais', 'Acordao', '2020-09-22', NULL, 'ASSUNTO: CONTRIBUIÇÃO PARA O PIS/PASEP
Período de apuração: 01/01/2011 a 31/12/2013
PEDÁGIO. SEGUROS. SERVIÇOS DERASTREAMENTO. SERVIÇOS DE SEGURANÇA E ESCOLTA. SERVIÇO DE AVALIAÇÃO DE RISCO PARA SEGUROS.
Os gastos relativos arastreamentode veículos e cargas, a seguros de qualquer espécie, a pedágio, a serviços de segurança e escolta, a serviços de avaliação de risco para seguro geram créditos de PIS/Pasep e de Cofins nas empresas prestadoras de serviço de transporte rodoviário de cargas.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
